# S3 bucket for application versions
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  versioning_configuration {
    status = "Enabled"
  }
}

# S3 object for application version source bundle
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.id
  key    = "examplebucket_object"
  source = "app_version.zip"
}

# Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

# Application version
resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.sampleapril26426.id
  key         = aws_s3_object.examplebucket_object.id
}

# VPC for Elastic Beanstalk environment
resource "aws_vpc" "eb_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "eb-vpc"
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "eb_subnet" {
  count = 2

  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = cidrsubnet(aws_vpc.eb_vpc.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  map_public_ip_on_launch = true

  tags = {
    Name = "eb-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "eb_igw" {
  vpc_id = aws_vpc.eb_vpc.id

  tags = {
    Name = "eb-igw"
  }
}

# Route table for public subnets
resource "aws_route_table" "eb_public" {
  vpc_id = aws_vpc.eb_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eb_igw.id
  }

  tags = {
    Name = "eb-public-rt"
  }
}

# Associate route table with subnets
resource "aws_route_table_association" "eb_subnet" {
  count = 2

  subnet_id      = aws_subnet.eb_subnet[count.index].id
  route_table_id = aws_route_table.eb_public.id
}

# Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = "myapp-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = data.aws_elastic_beanstalk_solution_stack.nodejs.name
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.eb_vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.eb_subnet[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "internet facing"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service,
    aws_iam_role_policy_attachment.eb_web_tier,
    aws_iam_role_policy_attachment.eb_multicontainer_docker
  ]
}

terraform {
  required_version = ">= 1.0"
