      source  = "hashicorp/random"
      version = ">= 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.0"
    }
  }
}

variable "domain_name" {
  type    = string
  default = "example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_lb_hosted_zone_id" "eb" {}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "eb-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 1
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true
  tags = {
    Name = "eb-public-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = 1
  subnet_id      = aws_subnet.public[0].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "eb_sg" {
  name_prefix = "eb-sg-"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "eb-sg"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "eb_app_bucket" {
  bucket = "elasticbeanstalk-app-bucket-${random_id.bucket_suffix.hex}"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eb_app_bucket" {
  bucket = aws_s3_bucket.eb_app_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eb_app_bucket" {
  bucket = aws_s3_bucket.eb_app_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "local_file" "app_source" {
  filename = "${path.module}/app/index.html"
  content  = "<html><body><h1>Hello from Elastic Beanstalk</h1></body></html>"
}

data "archive_file" "app_zip" {
  type        = "zip"
  source_dir  = "${path.module}/app"
  output_path = "${path.module}/app.zip"
  depends_on  = [local_file.app_source]
}

resource "aws_s3_object" "examplebucket_object" {
  bucket  = aws_s3_bucket.eb_app_bucket.id
  key     = "app-version.zip"
  source  = data.archive_file.app_zip.output_path
  etag    = filemd5(data.archive_file.app_zip.output_path)
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.eb_app_bucket.id
  key         = aws_s3_object.examplebucket_object.id
}

resource "aws_elastic_beanstalk_environment" "eb-env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  version_label       = aws_elastic_beanstalk_application_version.version.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Node.js 14"
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = aws_subnet.public[0].id
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }
}

resource "aws_route53_record" "alias_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  alias {
    name                   = aws_elastic_beanstalk_environment.eb-env.cname
    zone_id                = data.aws_lb_hosted_zone_id.eb.id
    evaluate_target_health = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "domain" {
  description = "Domain name for Route53 hosted zone (must be owned)"
  default     = "example.com"
}

variable "app_name" {
  description = "Elastic Beanstalk application name"
  default     = "blue-green-app"
}

variable "record_name" {
  description = "DNS record name for the application (e.g., app.example.com)"
  default     = "app"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = data.aws_availability_zones.available.names
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "blue-green-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "blue-green-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "blue-green-igw"
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "blue-green-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for EB instances
resource "aws_security_group" "eb" {
  name        = "blue-green-eb-sg"
  description = "Security group for Elastic Beanstalk instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "blue-green-eb-sg"
  }
}

# IAM Role for Elastic Beanstalk Service
resource "aws_iam_role" "eb_service" {
  name = "aws-elasticbeanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# Attach managed policy to service role (replaces deprecated managed_policy_arns)
resource "aws_iam_role_policy_attachment" "eb_service_attach" {
  role       = aws_iam_role.eb_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkService"
}

# IAM Role for EC2 instances
resource "aws_iam_role" "ec2_eb" {
  name = "aws-elasticbeanstalk-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_eb_web_tier" {
  role       = aws_iam_role.ec2_eb.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_eb_multicontainer" {
  role       = aws_iam_role.ec2_eb.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb" {
  name = "aws-elasticbeanstalk-ec2-profile"
  role = aws_iam_role.ec2_eb.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name = var.app_name
}

# Elastic Beanstalk Environments
resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Node.js 20"
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb.name
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb.id
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Node.js 20"
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb.name
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb.id
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Data sources to look up the load balancer hosted zone IDs
data "aws_lb" "blue" {
  name = element(aws_elastic_beanstalk_environment.blue.load_balancers, 0)
}

data "aws_lb" "green" {
  name = element(aws_elastic_beanstalk_environment.green.load_balancers, 0)
}

# Route53 Hosted Zone
resource "aws_route53_zone" "main" {
  name = var.domain

  lifecycle {
    prevent_destroy = true
  }
}

# Route53 Record for Blue
resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "${var.record_name}.${var.domain}"
  type    = "A"
  set_identifier = "blue"

  weighted_routing_policy {
    weight = 100
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.blue.cname
    zone_id                = data.aws_lb.blue.zone_id
    evaluate_target_health = true
  }
}

# Route53 Record for Green
resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "${var.record_name}.${var.domain}"
  type    = "A"
  set_identifier = "green"

  weighted_routing_policy {
    weight = 0
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.green.cname
    zone_id                = data.aws_lb.green.zone_id
    evaluate_target_health = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "us_west"
  region = "us-west-2"
}

provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

variable "domain_name" {
  description = "Domain name for the Route53 hosted zone"
  type        = string
  default     = "example.com"
}

# ------------------------------------------------------------------------------
# Data sources for static lookups
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available_us_west" {
  provider = aws.us_west
  state    = "available"
}

data "aws_availability_zones" "available_eu_central" {
  provider = aws.eu_central
  state    = "available"
}

data "aws_elastic_beanstalk_solution_stack" "nodejs_us_west" {
  provider    = aws.us_west
  most_recent = true
  name_regex  = "^64bit Amazon Linux 2 .* running Node.js"
}

data "aws_elastic_beanstalk_solution_stack" "nodejs_eu_central" {
  provider    = aws.eu_central
  most_recent = true
  name_regex  = "^64bit Amazon Linux 2 .* running Node.js"
}

data "aws_elb_hosted_zone_id" "us_west" {
  provider = aws.us_west
  region   = "us-west-2"
}

data "aws_elb_hosted_zone_id" "eu_central" {
  provider = aws.eu_central
  region   = "eu-central-1"
}

# ------------------------------------------------------------------------------
# IAM resources (global, using us-west-2 provider)
# ------------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  provider = aws.us_west
  name     = "eb_service_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_service_attach" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

resource "aws_iam_role" "eb_ec2_role" {
  provider = aws.us_west
  name     = "eb_ec2_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  provider = aws.us_west
  name     = "eb_ec2_profile"
  role     = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

# ------------------------------------------------------------------------------
# Elastic Beanstalk Application (global)
# ------------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "main" {
  provider    = aws.us_west
  name        = "my-eb-application"
  description = "Elastic Beanstalk application for geolocation routing"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# US West Region Resources
# ------------------------------------------------------------------------------

resource "aws_vpc" "us_west" {
  provider             = aws.us_west
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "us-west-vpc"
  }
}

resource "aws_subnet" "us_west_public_1" {
  provider                = aws.us_west
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available_us_west.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "us-west-public-1"
  }
}

resource "aws_subnet" "us_west_public_2" {
  provider                = aws.us_west
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available_us_west.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "us-west-public-2"
  }
}

resource "aws_internet_gateway" "us_west" {
  provider = aws.us_west
  vpc_id   = aws_vpc.us_west.id

  tags = {
    Name = "us-west-igw"
  }
}

resource "aws_route_table" "us_west" {
  provider = aws.us_west
  vpc_id   = aws_vpc.us_west.id

  tags = {
    Name = "us-west-public-rt"
  }
}

resource "aws_route" "us_west_default" {
  provider               = aws.us_west
  route_table_id         = aws_route_table.us_west.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.us_west.id
}

resource "aws_route_table_association" "us_west_public_1" {
  provider       = aws.us_west
  subnet_id      = aws_subnet.us_west_public_1.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_route_table_association" "us_west_public_2" {
  provider       = aws.us_west
  subnet_id      = aws_subnet.us_west_public_2.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_security_group" "us_west_eb" {
  provider    = aws.us_west
  name        = "eb-sg-us-west"
  description = "Security group for Elastic Beanstalk environment in us-west-2"
  vpc_id      = aws_vpc.us_west.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-sg-us-west"
  }
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  provider            = aws.us_west
  name                = "us_west"
  application         = aws_elastic_beanstalk_application.main.name
  solution_stack_name = data.aws_elastic_beanstalk_solution_stack.nodejs_us_west.name
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.us_west.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.us_west_public_1.id, aws_subnet.us_west_public_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.us_west_eb.id
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# EU Central Region Resources
# ------------------------------------------------------------------------------

resource "aws_vpc" "eu_central" {
  provider             = aws.eu_central
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
