terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name to map to an IPv4 address"
  type        = string
  default     = "example.com"
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_eip" "main" {
  domain = "vpc"
}

resource "aws_route53_record" "a_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = aws_route53_zone.main.name
  type    = "A"
  ttl     = 300
  records = [aws_eip.main.public_ip]
}

output "name_servers" {
  description = "Name servers for the hosted zone, to be used for domain delegation"
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the Route 53 hosted zone and record"
  type        = string
  default     = "example.com"
}

variable "ipv6_address" {
  description = "The IPv6 address to map to the domain name"
  type        = string
  default     = "::1"
}

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "AAAA"
  ttl     = 300
  records = [var.ipv6_address]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "reverse_ip_address" {
  description = "IP address for which the reverse DNS PTR record is created"
  type        = string
  default     = "192.0.2.1"
}

locals {
  ip_parts          = split(".", var.reverse_ip_address)
  reverse_zone_name = format("%s.%s.%s.in-addr.arpa", local.ip_parts[2], local.ip_parts[1], local.ip_parts[0])
  record_name       = format("%s.%s.%s.%s.in-addr.arpa", local.ip_parts[3], local.ip_parts[2], local.ip_parts[1], local.ip_parts[0])
}

resource "aws_route53_zone" "reverse_zone" {
  name = local.reverse_zone_name
}

resource "aws_route53_record" "ptr" {
  zone_id = aws_route53_zone.reverse_zone.zone_id
  name    = local.record_name
  type    = "PTR"
  ttl     = 300
  records = ["host.example53.com"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_route53_zone" "main" {
  name    = "example"
  comment = "Hosted zone for domain ownership verification"
}

resource "aws_route53_record" "verification_txt" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "example"
  type    = "TXT"
  ttl     = 300
  records = ["\"passwordpassword\""]
}

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "domain_name" {
  description = "Domain name for Route 53 hosted zone"
  type        = string
  default     = "example.com"
}

# ------------------------------------------------------------------------------
# Networking: VPC, Subnets, Internet Gateway, Route Table
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "beanstalk-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "beanstalk-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "beanstalk-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "beanstalk-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security Group for Elastic Beanstalk environment
# ------------------------------------------------------------------------------
resource "aws_security_group" "beanstalk" {
  name        = "beanstalk-sg"
  description = "Security group for Elastic Beanstalk environment"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "All traffic from within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "beanstalk-sg"
  }
}

# ------------------------------------------------------------------------------
# IAM roles and instance profile
# ------------------------------------------------------------------------------
resource "aws_iam_role" "beanstalk_service" {
  name = "beanstalk-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_service" {
  role       = aws_iam_role.beanstalk_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkService"
}

resource "aws_iam_role" "ec2_instance" {
  name = "beanstalk-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_web_tier" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_multicontainer" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  role = aws_iam_role.ec2_instance.name
}

# ------------------------------------------------------------------------------
# S3 bucket for Elastic Beanstalk application versions
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "beanstalk_apps" {
  bucket = "myapp-beanstalk-versions-${data.aws_caller_identity.current.account_id}"
  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket_server_side_encryption_configuration" "beanstalk_apps" {
  bucket = aws_s3_bucket.beanstalk_apps.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "beanstalk_apps" {
  bucket = aws_s3_bucket.beanstalk_apps.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "beanstalk_apps" {
  bucket = aws_s3_bucket.beanstalk_apps.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# Elastic Beanstalk Application
# ------------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp-application"
  description = "Application for myapp"
}

# ------------------------------------------------------------------------------
# Random password and Secrets Manager for RDS master password
# ------------------------------------------------------------------------------
resource "random_password" "rds_master" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "rds_master" {
  name = "myapp-rds-master-password"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = random_password.rds_master.result
}

# ------------------------------------------------------------------------------
# Elastic Beanstalk Environment
# ------------------------------------------------------------------------------
resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.0 running Node.js 18"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBEngine"
    value     = "mysql"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceClass"
    value     = "db.t3.micro"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBAllocatedStorage"
    value     = "5"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = "myapp_user"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = random_password.rds_master.result
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBName"
    value     = "myapp_db"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Route 53: Hosted Zone and CNAME record
# ------------------------------------------------------------------------------
resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_elastic_beanstalk_environment.myenv.cname]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  alias  = "us_east_1"
}

provider "aws" {
  region = "eu-west-1"
  alias  = "eu_west_1"
}

locals {
  common_tags = {
    Environment = "multi-region"
    ManagedBy   = "terraform"
  }
  db_name     = "appdb"
  db_username = "dbadmin"
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available_us_east" {
  provider = aws.us_east_1
  state    = "available"
}

data "aws_availability_zones" "available_eu_west" {
  provider = aws.eu_west_1
  state    = "available"
}

data "aws_caller_identity" "current" {
  provider = aws.us_east_1
}

data "aws_elb_hosted_zone_id" "us_east" {
  provider = aws.us_east_1
}

data "aws_elb_hosted_zone_id" "eu_west" {
  provider = aws.eu_west_1
}

# ------------------------------------------------------------------------------
# IAM resources (global – use us-east-1 provider)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2" {
  provider = aws.us_east_1
  name     = "eb-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  provider   = aws.us_east_1
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_multicontainer_docker" {
  provider   = aws.us_east_1
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  provider   = aws.us_east_1
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile3" {
  provider = aws.us_east_1
  name     = "eb_ec2_profile3"
  role     = aws_iam_role.eb_ec2.name
}

# ------------------------------------------------------------------------------
# Route 53 hosted zone (global)
# ------------------------------------------------------------------------------
resource "aws_route53_zone" "main" {
  provider = aws.us_east_1
  name     = var.domain_name
  tags     = local.common_tags
}

# ------------------------------------------------------------------------------
# Random passwords for RDS (stored in Secrets Manager)
# ------------------------------------------------------------------------------
resource "random_password" "rds_us_east" {
  length  = 16
  special = false
}

resource "random_password" "rds_eu_west" {
  length  = 16
  special = false
}

# ------------------------------------------------------------------------------
# Secrets Manager secrets and versions
# ------------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "rds_password_us_east" {
  provider = aws.us_east_1
  name     = "rds_password_us_east"
  tags     = local.common_tags
}

resource "aws_secretsmanager_secret_version" "rds_password_us_east" {
  provider      = aws.us_east_1
  secret_id     = aws_secretsmanager_secret.rds_password_us_east.id
  secret_string = random_password.rds_us_east.result
}

resource "aws_secretsmanager_secret" "rds_password_eu_west" {
  provider = aws.eu_west_1
  name     = "rds_password_eu_west"
  tags     = local.common_tags
}

resource "aws_secretsmanager_secret_version" "rds_password_eu_west" {
  provider      = aws.eu_west_1
  secret_id     = aws_secretsmanager_secret.rds_password_eu_west.id
  secret_string = random_password.rds_eu_west.result
}

# ------------------------------------------------------------------------------
# US East (us-east-1) resources
# ------------------------------------------------------------------------------

# -- VPC and Networking --
resource "aws_vpc" "main_us_east" {
  provider             = aws.us_east_1
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "main-us-east" })
}

resource "aws_internet_gateway" "igw_us_east" {
  provider = aws.us_east_1
  vpc_id   = aws_vpc.main_us_east.id
  tags     = merge(local.common_tags, { Name = "igw-us-east" })
}

resource "aws_subnet" "public_us_east" {
  provider          = aws.us_east_1
  count             = 2
  vpc_id            = aws_vpc.main_us_east.id
  cidr_block        = cidrsubnet(aws_vpc.main_us_east.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available_us_east.names[count.index]
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "public-us-east-${count.index}" })
}

resource "aws_route_table" "public_us_east" {
  provider = aws.us_east_1
  vpc_id   = aws_vpc.main_us_east.id
  tags     = merge(local.common_tags, { Name = "public-rt-us-east" })
}

resource "aws_route" "internet_access_us_east" {
  provider = aws.us_east_1
  route_table_id         = aws_route_table.public_us_east.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw_us_east.id
}

resource "aws_route_table_association" "public_us_east" {
  provider = aws.us_east_1
  count          = 2
  subnet_id      = aws_subnet.public_us_east[count.index].id
  route_table_id = aws_route_table.public_us_east.id
}

# -- Security Groups --
resource "aws_security_group" "eb_us_east" {
  provider    = aws.us_east_1
  name        = "eb-sg-us-east"
  description = "Allow HTTP and HTTPS from internet"
  vpc_id      = aws_vpc.main_us_east.id
  tags        = merge(local.common_tags, { Name = "eb-sg-us-east" })
}

resource "aws_security_group_rule" "eb_http_us_east" {
  provider = aws.us_east_1
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_us_east.id
}

resource "aws_security_group_rule" "eb_https_us_east" {
  provider = aws.us_east_1
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_us_east.id
}

resource "aws_security_group_rule" "eb_egress_us_east" {
  provider = aws.us_east_1
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_us_east.id
}

resource "aws_security_group" "rds_us_east" {
  provider    = aws.us_east_1
  name        = "rds-sg-us-east"
  description = "Allow MySQL from EB security group"
  vpc_id      = aws_vpc.main_us_east.id
  tags        = merge(local.common_tags, { Name = "rds-sg-us-east" })
}

resource "aws_security_group_rule" "rds_mysql_us_east" {
  provider                 = aws.us_east_1
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eb_us_east.id
  security_group_id        = aws_security_group.rds_us_east.id
}

# -- S3 bucket for application versions --
resource "aws_s3_bucket" "app_versions_us_east" {
  provider = aws.us_east_1
  bucket   = "myapp-us-east-versions-${data.aws_caller_identity.current.account_id}"
  tags     = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "app_versions_us_east" {
  provider               = aws.us_east_1
  bucket                 = aws_s3_bucket.app_versions_us_east.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_versions_us_east" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.app_versions_us_east.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "app_versions_us_east" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.app_versions_us_east.id
  versioning_configuration {
    status = "Enabled"
  }
}

# -- Elastic Beanstalk --
resource "aws_elastic_beanstalk_application" "myapp_us_east" {
  provider = aws.us_east_1
  name     = "myapp_us_east"
  tags     = local.common_tags
}

resource "aws_elastic_beanstalk_environment" "myenv_us_east" {
  provider            = aws.us_east_1
  name                = "myenv_us_east"
  application         = aws_elastic_beanstalk_application.myapp_us_east.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.5 running Node.js 16"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile3.name
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main_us_east.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public_us_east[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_us_east.id
  }

  # RDS connection details as environment properties
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main_db_us_east.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.main_db_us_east.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_username
  }

  # Password from Secrets Manager secret string
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = aws_secretsmanager_secret_version.rds_password_us_east.secret_string
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.rds_password_us_east.arn
  }

  tags = local.common_tags
}

# -- RDS Database --
resource "aws_db_subnet_group" "main_us_east" {
  provider   = aws.us_east_1
  name       = "main-db-subnet-group-us-east"
  subnet_ids = aws_subnet.public_us_east[*].id
  tags       = local.common_tags
}

resource "aws_db_instance" "main_db_us_east" {
  provider                 = aws.us_east_1
  identifier               = "main-db-us-east"
  allocated_storage        = 20
  storage_type             = "gp3"
  engine                   = "mysql"
  engine_version           = "8.0"
  instance_class           = "db.t3.micro"
  db_name                  = local.db_name
  username                 = local.db_username
  password                 = random_password.rds_us_east.result
  db_subnet_group_name     = aws_db_subnet_group.main_us_east.name
  vpc_security_group_ids   = [aws_security_group.rds_us_east.id]
  storage_encrypted        = true
  multi_az                 = true
  skip_final_snapshot      = false
  final_snapshot_identifier = "main-db-us-east-final-${formatdate("YYYYMMDDHHmmss", timestamp())}"
  tags                     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -- Route 53 Record --
resource "aws_route53_record" "us_east" {
  provider = aws.us_east_1
  zone_id  = aws_route53_zone.main.zone_id
  name     = "us-east-1"
  type     = "A"

  alias {
    name                   = aws_elastic_beanstalk_environment.myenv_us_east.cname
    zone_id                = data.aws_elb_hosted_zone_id.us_east.id
    evaluate_target_health = true
  }
}

# ------------------------------------------------------------------------------
# EU West (eu-west-1) resources
