}

resource "aws_security_group_rule" "eb_https_eu_west" {
  provider = aws.eu_west_1
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_eu_west.id
}

resource "aws_security_group_rule" "eb_egress_eu_west" {
  provider = aws.eu_west_1
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_eu_west.id
