resource "aws_security_group_rule" "rds_mysql_eu_west" {
  provider                 = aws.eu_west_1
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eb_eu_west.id
  security_group_id        = aws_security_group.rds_eu_west.id
