}

resource "aws_s3_bucket_public_access_block" "app_versions_eu_west" {
  provider               = aws.eu_west_1
  bucket                 = aws_s3_bucket.app_versions_eu_west.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
