resource "aws_s3_bucket_server_side_encryption_configuration" "app_versions_eu_west" {
  provider = aws.eu_west_1
  bucket   = aws_s3_bucket.app_versions_eu_west.id
  rule {
    apply_server_side_encryption_by_default {
