  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_username
  }

  # Password from Secrets Manager secret string
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = aws_secretsmanager_secret_version.rds_password_eu_west.secret_string
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
