  provider   = aws.eu_west_1
  name       = "main-db-subnet-group-eu-west"
  subnet_ids = aws_subnet.public_eu_west[*].id
  tags       = local.common_tags
}

resource "aws_db_instance" "main_db_eu_west" {
  provider                  = aws.eu_west_1
  identifier                = "main-db-eu-west"
  allocated_storage         = 20
  storage_type              = "gp3"
  engine                    = "mysql"
  engine_version            = "8.0"
  instance_class            = "db.t3.micro"
  db_name                   = local.db_name
  username                  = local.db_username
  password                  = random_password.rds_eu_west.result
  db_subnet_group_name      = aws_db_subnet_group.main_eu_west.name
  vpc_security_group_ids    = [aws_security_group.rds_eu_west.id]
  storage_encrypted         = true
  multi_az                  = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "main-db-eu-west-final-${formatdate("YYYYMMDDHHmmss", timestamp())}"
