# Data source for account ID (static metadata)
data "aws_caller_identity" "current" {}

# CodeBuild Project
resource "aws_codebuild_project" "example_project" {
  name         = "example-codebuild-project"
  description  = "Example CodeBuild project with GitHub source and S3 artifact/cache"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.artifact_bucket.bucket
    path           = "/"
    namespace_type = "NONE"
    name           = "build-output"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.cache_bucket.bucket
  }

  environment {
