# ---------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${var.project_name}"
  retention_in_days = var.log_retention_days

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CODEBUILD PROJECT
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_codebuild_project" "this" {
  name         = var.project_name
  description  = "CodeBuild project with secondary sources"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.artifacts.bucket
    path     = "/"
    name     = "build-output"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:7.0"
    type         = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type      = "NO_SOURCE"
    buildspec = <<-BUILDSPEC
version: 0.2
phases:
  build:
    commands:
      - echo "Primary build"
BUILDSPEC
  }

  secondary_sources {
    type            = "S3"
    location        = aws_s3_bucket.secondary_source.bucket
    source_identifier = "secondary_source"
  }

  secondary_source_version {
    source_identifier = "secondary_source"
    source_version    = aws_s3_object.secondary_source_placeholder.key
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
      status     = "ENABLED"
    }
  }

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

