resource "aws_codebuild_project" "codebuild_project" {
  name         = var.project_name
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type     = "S3"
    location = aws_s3_bucket.primary_source.bucket
    buildspec = <<EOF
version: 0.2
phases:
  build:
    commands:
      - echo "Building..."
      - ls
artifacts:
  files:
    - '**/*'
EOF
  }

  secondary_sources {
    source_identifier = "secondary_source_1"
    type              = "S3"
    location          = aws_s3_bucket.secondary_source_1.bucket
  }

  secondary_sources {
    source_identifier = "secondary_source_2"
    type              = "S3"
    location          = aws_s3_bucket.secondary_source_2.bucket
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.primary_artifact.bucket
    namespace_type = "BUILD_ID"
    packaging      = "ZIP"
  }

  secondary_artifacts {
    artifact_identifier = "secondary_artifact_1"
    type                = "S3"
    location            = aws_s3_bucket.secondary_artifact_1.bucket
  }

  secondary_artifacts {
    artifact_identifier = "secondary_artifact_2"
    type                = "S3"
    location            = aws_s3_bucket.secondary_artifact_2.bucket
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    type            = "LINUX_CONTAINER"
    image           = "aws/codebuild/standard:7.0"
    privileged_mode = false

    environment_variable {
      name  = "EXAMPLE_VAR"
      value = "plaintext-value"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "SECRET_VAR"
      value = aws_secretsmanager_secret.secret_var.arn
      type  = "SECRETS_MANAGER"
    }
  }

  logs_config {
    cloudwatch_logs {
      status     = "ENABLED"
      group_name = aws_cloudwatch_log_group.build_logs.name
    }
  }
}

