    ]
  })
}

resource "aws_iam_role_policy" "lex_bot_policy" {
  name = "lex_bot_policy"
  role = aws_iam_role.lex_bot_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_lex_intent" "greeting_intent" {
  name = "greeting_intent"

  sample_utterances = ["Hello", "Hi", "Greetings"]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "Did you mean to greet me?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, talk to you later."
      content_type = "PlainText"
    }
  }
}

resource "aws_lex_bot" "hello_bot" {
  name                      = "hello_bot"
  child_directed            = false
  idle_session_ttl_in_seconds = 300
  process_behavior          = "BUILD"

