  }
}

# ──────────────────────────────────────────────────────────────────────────────
# Intent
# ──────────────────────────────────────────────────────────────────────────────

resource "aws_lex_intent" "order_pizza" {
  name           = "${local.name_prefix}_order_pizza"
  description    = "Intent to order a pizza"
  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name        = "PizzaSize"
    description = "Size of the pizza"
    slot_constraint = "Required"
    slot_type    = aws_lex_slot_type.pizza_size.name
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza would you like? (small, medium, large)"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name        = "PizzaCrust"
    description = "Type of crust"
    slot_constraint = "Required"
    slot_type    = aws_lex_slot_type.pizza_crust.name
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What type of crust? (thin, thick, stuffed)"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name        = "Quantity"
    description = "Number of pizzas"
    slot_constraint = "Required"
    slot_type    = "AMAZON.NUMBER"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name        = "Address"
    description = "Delivery address"
    slot_constraint = "Required"
    slot_type    = "AMAZON.ADDRESS"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What is your delivery address?"
        content_type = "PlainText"
      }
    }
  }

  sample_utterances = [
    "I want to order a pizza",
    "Order {PizzaSize} pizza with {PizzaCrust} crust",
    "I'd like {Quantity} {PizzaSize} pizzas delivered to {Address}",
    "Can I get a {PizzaSize} pizza?",
    "Order pizza for delivery"
  ]

  depends_on = [
    aws_lex_slot_type.pizza_size,
    aws_lex_slot_type.pizza_crust
  ]
}

