data "aws_caller_identity" "current" {}

# IAM roles
resource "aws_iam_role" "lambda_role" {
  name = local.lambda_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "${local.lambda_name}-policy"
  role = aws_iam_role.lambda_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.lambda_log_group}:*"
    }]
  })
}

resource "aws_iam_role" "lex_role" {
  name = local.lex_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lex.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lex_policy" {
  name = "${local.bot_name}-policy"
  role = aws_iam_role.lex_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = "lambda:InvokeFunction"
      Resource = aws_lambda_function.pizza_fulfillment.arn
    }]
  })
}

# Lambda function
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function_payload.zip"
  source_content = <<-EOF
import json
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

def lambda_handler(event, context):
    logger.info(json.dumps(event))
    intent_name = event['currentIntent']['name']
    slots = event['currentIntent']['slots']
    confirmation_status = event.get('currentIntent', {}).get('confirmationStatus', 'None')

    # If this is the initial invocation or after a followup, ask for extra cheese
    if confirmation_status == 'None':
        # Elicit a followup question via ConfirmIntent
        response = {
            "dialogAction": {
                "type": "ConfirmIntent",
                "intentName": intent_name,
                "slots": slots,
                "message": {
                    "contentType": "PlainText",
                    "content": "Would you like extra cheese?"
                }
            }
        }
        return response
    elif confirmation_status == 'Confirmed':
        # User confirmed, proceed to fulfillment
        # Build a simple response
        size = slots.get('PizzaSize', '')
        toppings = slots.get('PizzaToppings', '')
        message = f"Your {size} pizza with {toppings} is on its way!"
        response = {
            "dialogAction": {
                "type": "Close",
                "fulfillmentState": "Fulfilled",
                "message": {
                    "contentType": "PlainText",
                    "content": message
                }
            }
        }
        return response
    elif confirmation_status == 'Denied':
        # User denied extra cheese, just fulfill with original order
        size = slots.get('PizzaSize', '')
        toppings = slots.get('PizzaToppings', '')
        message = f"Alright, your {size} pizza with {toppings} will be ready soon."
        response = {
            "dialogAction": {
                "type": "Close",
                "fulfillmentState": "Fulfilled",
                "message": {
                    "contentType": "PlainText",
                    "content": message
                }
            }
        }
        return response
    else:
        # Fallback
        response = {
            "dialogAction": {
                "type": "Close",
                "fulfillmentState": "Failed",
                "message": {
                    "contentType": "PlainText",
                    "content": "Sorry, something went wrong."
                }
            }
        }
        return response
EOF
  source_content_filename = "index.py"
}

resource "aws_lambda_function" "pizza_fulfillment" {
  filename         = data.archive_file.lambda_zip.output_path
  function_name    = local.lambda_name
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.lambda_handler"
  runtime          = "python3.12"
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  lifecycle {
    create_before_destroy = true
  }
}

