# ------------------------------------------------------------
# Intent for ordering pizza
# ------------------------------------------------------------
resource "aws_lex_intent" "order_pizza" {
  name           = local.intent_name
  description    = "Intent to order a pizza"
  fulfillment_activity {
    type = "ReturnIntent"
  }

  sample_utterances = [
    "I want to order a pizza",
    "Order a pizza",
    "Pizza order",
  ]

  # Confirmation prompt – required because rejection_statement is present
  confirmation_prompt {
    max_attempts = 2
    message {
      content_type = "PlainText"
      content      = "Shall I place your order for a {PizzaSize} {PizzaCrust} pizza with {PizzaToppings}?"
    }
  }

  # Rejection statement – if the user cancels after confirmation
  rejection_statement {
    message {
      content_type = "PlainText"
      content      = "Okay, your pizza order has been cancelled. Let us know if you need anything else."
    }
  }

  # Slot for pizza size
  slot {
    name             = "PizzaSize"
    slot_type        = aws_lex_slot_type.pizza_size.name
    slot_constraint  = "Required"
    slot_type_version = "$LATEST"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "What size pizza would you like? (Small, Medium, Large)"
      }
    }
  }

  # Slot for crust type
  slot {
    name             = "PizzaCrust"
    slot_type        = aws_lex_slot_type.pizza_crust.name
    slot_constraint  = "Required"
    slot_type_version = "$LATEST"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "What crust type would you like? (Thin, Thick, Stuffed)"
      }
    }
  }

  # Slot for toppings
  slot {
    name             = "PizzaToppings"
    slot_type        = aws_lex_slot_type.pizza_toppings.name
    slot_constraint  = "Required"
    slot_type_version = "$LATEST"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "What toppings would you like? (Cheese, Pepperoni, Mushrooms, Olives)"
      }
    }
  }

  # Conclusion statement – confirms the order after all slots are filled
  conclusion_statement {
    message {
      content_type = "PlainText"
      content      = "Your {PizzaSize} {PizzaCrust} pizza with {PizzaToppings} has been ordered. Thank you!"
    }
  }
}

