    name        = "OrderID"
    slot_constraint = "Optional"
    slot_type    = "AMAZON.Number"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What is the order ID you want to cancel?"
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_intent" "track_order" {
  name        = "TrackOrder"
  description = "Intent to track the status of an existing order"
  sample_utterances = [
    "Track my order",
    "Where is my order?",
    "Order status",
    "Check order {OrderID}"
  ]
  fulfillment_activity {
    type = "ReturnIntent"
  }
  slot {
    name        = "OrderID"
    slot_constraint = "Optional"
    slot_type    = "AMAZON.Number"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What is the order ID you want to track?"
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_intent" "greeting" {
  name        = "Greeting"
  description = "Intent to greet the user and start the conversation"
  sample_utterances = [
    "Hello",
    "Hi",
    "Good morning",
    "Hey",
    "What's up"
  ]
  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_intent" "help" {
  name        = "Help"
  description = "Intent to provide help information to the user"
  sample_utterances = [
    "Help",
    "What can you do?",
    "I need assistance",
    "Help me"
  ]
  fulfillment_activity {
    type = "ReturnIntent"
  }
}

# ------------------------------------------------------------------------------
# Lex Bot
# ------------------------------------------------------------------------------
resource "aws_lex_bot" "pizza_ordering_bot" {
  name           = local.bot_name
  description    = local.bot_description
  child_directed = false
  process_behavior = "BUILD"

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }
  intent {
    intent_name    = aws_lex_intent.cancel_order.name
    intent_version = aws_lex_intent.cancel_order.version
  }
  intent {
    intent_name    = aws_lex_intent.track_order.name
    intent_version = aws_lex_intent.track_order.version
  }
  intent {
    intent_name    = aws_lex_intent.greeting.name
    intent_version = aws_lex_intent.greeting.version
  }
  intent {
    intent_name    = aws_lex_intent.help.name
    intent_version = aws_lex_intent.help.version
  }

  # Clarification prompt and abort statement are required for the bot.
  clarification_prompt {
    max_attempts = 3
    message {
      content      = "Sorry, I didn't understand. Could you please rephrase?"
      content_type = "PlainText"
    }
  }
  abort_statement {
    message {
      content      = "Sorry, I'm not able to help at the moment. Goodbye."
      content_type = "PlainText"
    }
  }

  # Optional: voice settings (disabled by default)
  voice_id = "Joanna"
}

locals {
  common_tags = {
    Environment = "dev"
    Purpose     = "kid-pizza-bot"
  }

  lambda_code = <<-EOF
import json

def lambda_handler(event, context):
    return {
        "dialogAction": {
            "type": "Close",
            "fulfillmentState": "Fulfilled",
            "message": {
                "contentType": "PlainText",
                "content": "Thanks, your pizza order is on its way!"
            }
        }
    }
EOF
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
  }
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "/tmp/pizza_order_lambda.zip"
  source_content = local.lambda_code
  source_content_filename = "index.py"
}

resource "aws_iam_role" "lambda_exec" {
  name = "pizza-order-lambda-exec"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "lambda_logging" {
  name = "pizza-order-lambda-logging"
  role = aws_iam_role.lambda_exec.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_lambda_function" "pizza_order_fulfillment" {
  function_name = "pizza-order-fulfillment"
  role          = aws_iam_role.lambda_exec.arn
  handler       = "index.lambda_handler"
  runtime       = "python3.12"
  filename      = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lambda_permission" "lex" {
  statement_id  = "AllowLexInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.pizza_order_fulfillment.function_name
  principal     = "lex.amazonaws.com"
}

resource "aws_lex_slot_type" "pizza_size" {
  name = "PizzaSize"
  description = "Size of the pizza"
  enumeration_value {
    value = "Small"
    synonyms = ["mini"]
  }
  enumeration_value {
    value = "Medium"
  }
  enumeration_value {
    value = "Large"
    synonyms = ["big", "jumbo"]
  }
}

resource "aws_lex_slot_type" "pizza_crust" {
  name = "PizzaCrust"
  description = "Type of crust"
  enumeration_value {
    value = "Thin"
  }
  enumeration_value {
    value = "Thick"
    synonyms = ["deep dish"]
  }
  enumeration_value {
    value = "Stuffed"
    synonyms = ["cheese stuffed"]
  }
}

resource "aws_lex_slot_type" "pizza_toppings" {
  name = "PizzaToppings"
  description = "Toppings for the pizza"
  enumeration_value {
    value = "Cheese"
    synonyms = ["cheese only"]
  }
  enumeration_value {
    value = "Pepperoni"
    synonyms = ["pepperoni"]
  }
  enumeration_value {
    value = "Mushrooms"
    synonyms = ["mushroom"]
  }
  enumeration_value {
    value = "Olives"
    synonyms = ["olive"]
  }
  enumeration_value {
    value = "Ham"
  }
  enumeration_value {
    value = "Pineapple"
    synonyms = ["pineapple"]
  }
}

resource "aws_lex_intent" "order_pizza" {
  name = "OrderPizza"
  description = "Intent to order a pizza"
  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      message_version = "1.0"
      uri             = aws_lambda_function.pizza_order_fulfillment.arn
    }
  }
  sample_utterances = [
    "I want to order a pizza",
    "Can I have a {PizzaSize} pizza with {PizzaToppings}",
    "I'd like a {PizzaSize} {PizzaCrust} crust pizza with {PizzaToppings}",
    "Order a pizza"
  ]
  slot {
    name        = "PizzaSize"
    slot_constraint = "Required"
    slot_type   = aws_lex_slot_type.pizza_size.name
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza would you like? Small, medium, or large?"
        content_type = "PlainText"
      }
    }
  }
  slot {
    name        = "PizzaCrust"
    slot_constraint = "Required"
    slot_type   = aws_lex_slot_type.pizza_crust.name
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What kind of crust do you want? Thin, thick, or stuffed?"
        content_type = "PlainText"
      }
    }
  }
  slot {
    name        = "PizzaToppings"
    slot_constraint = "Required"
    slot_type   = aws_lex_slot_type.pizza_toppings.name
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What toppings would you like? Cheese, pepperoni, mushrooms, olives, ham, or pineapple?"
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_intent" "greeting" {
  name = "GreetingIntent"
  description = "Intent to greet the user"
  fulfillment_activity {
    type = "ReturnIntent"
  }
  sample_utterances = [
    "Hi",
    "Hello",
    "Hey",
    "Good morning",
    "Good afternoon"
  ]
  conclusion_statement {
    message {
      content      = "Hello! Welcome to Pizza Fun! Let's order a pizza together!"
      content_type = "PlainText"
    }
    response_card = null
  }
}

resource "aws_lex_bot" "pizza_order_for_kids" {
  name           = "PizzaOrderForKids"
  description    = "A fun pizza ordering bot for kids"
  child_directed = true
  locale         = "en-US"
  voice_id       = "Joanna"
  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Oops! I didn't get that. Try again, little buddy!"
