      content      = "Sorry, I couldn't process your order. Please try again."
      content_type = "PlainText"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "tags" {
  type = map(string)
  default = {
    Environment = "dev"
    Project     = "pizza-lex"
  }
}

locals {
  function_name = "PizzaOrderHandler"
  log_group_name = "/aws/lambda/${local.function_name}"
}

# ------------------------------------------------------------
# Lambda function packaging
# ------------------------------------------------------------
data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "${path.module}/lambda_function.py"
  output_path = "${path.module}/lambda_function.zip"
}

# ------------------------------------------------------------
# IAM role for Lambda
# ------------------------------------------------------------
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_role" {
  name               = "PizzaOrderLambdaRole"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = var.tags
}

# Custom policy for Lambda to write logs to its log group
data "aws_iam_policy_document" "lambda_logs" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:*:*:log-group:${local.log_group_name}:*",
      "arn:aws:logs:*:*:log-group:${local.log_group_name}:log-stream:*"
    ]
  }
}

resource "aws_iam_policy" "lambda_logs" {
  name   = "PizzaOrderLambdaLogsPolicy"
  policy = data.aws_iam_policy_document.lambda_logs.json
  tags   = var.tags
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_logs.arn
}

# ------------------------------------------------------------
# CloudWatch log group for Lambda
# ------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda" {
  name              = local.log_group_name
  retention_in_days = 14
  tags              = var.tags
}

# ------------------------------------------------------------
# Lambda function
# ------------------------------------------------------------
resource "aws_lambda_function" "pizza_order_lambda" {
  function_name    = local.function_name
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.lambda_handler"
  runtime          = "python3.12"
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  tags             = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------
# IAM role for Lex
# ------------------------------------------------------------
data "aws_iam_policy_document" "lex_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lex.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lex_role" {
  name               = "PizzaOrderLexRole"
  assume_role_policy = data.aws_iam_policy_document.lex_assume_role.json
  tags               = var.tags
}

# Policy for Lex to invoke the Lambda function
data "aws_iam_policy_document" "lex_invoke_lambda" {
  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = [aws_lambda_function.pizza_order_lambda.arn]
  }
}

resource "aws_iam_policy" "lex_invoke_lambda" {
  name   = "PizzaOrderLexInvokeLambdaPolicy"
  policy = data.aws_iam_policy_document.lex_invoke_lambda.json
  tags   = var.tags
}

resource "aws_iam_role_policy_attachment" "lex_invoke_lambda" {
  role       = aws_iam_role.lex_role.name
  policy_arn = aws_iam_policy.lex_invoke_lambda.arn
}

# ------------------------------------------------------------
# Resource-based policy to allow Lex to invoke Lambda
# ------------------------------------------------------------
resource "aws_lambda_permission" "lex_invoke" {
  statement_id  = "AllowLexInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.pizza_order_lambda.function_name
  principal     = "lex.amazonaws.com"
  source_arn    = aws_lex_bot.pizza_ordering_bot.arn
}

# ------------------------------------------------------------
# Lex slot type for pizza size
# ------------------------------------------------------------
resource "aws_lex_slot_type" "pizza_size" {
  name         = "PizzaSize"
  description  = "Pizza size options"
  enumeration_value {
    value = "Small"
  }
  enumeration_value {
    value = "Medium"
  }
  enumeration_value {
    value = "Large"
  }
  # NOTE: aws_lex_slot_type does not support tags - omitted
}

# ------------------------------------------------------------
# Lex intent
# ------------------------------------------------------------
resource "aws_lex_intent" "order_pizza" {
  name        = "OrderPizzaIntent"
  description = "Intent to order a pizza"

  sample_utterances = [
    "I want to order a pizza",
    "Order a pizza",
    "Can I get a pizza",
    "Pizza please"
  ]

  slot {
    name        = "size"
    slot_type   = aws_lex_slot_type.pizza_size.name
    slot_constraint = "Required"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "What size pizza would you like? Small, Medium, or Large?"
      }
    }
  }

  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      message_version = "1.0"
      uri             = aws_lambda_function.pizza_order_lambda.arn
    }
  }

  # NOTE: aws_lex_intent does not support tags - omitted
}

# ------------------------------------------------------------
# Lex bot
# ------------------------------------------------------------
resource "aws_lex_bot" "pizza_ordering_bot" {
  name           = "PizzaOrderingBot"
  description    = "Bot to order pizzas"
  child_directed = false
  process_behavior = "BUILD"

  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Sorry, I could not process your order. Please try again."
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = "$LATEST"
  }

  # NOTE: aws_lex_bot does not support role_arn or tags - omitted
}

# ------------------------------------------------------------
# Lex bot alias
# ------------------------------------------------------------
resource "aws_lex_bot_alias" "production" {
  bot_name    = aws_lex_bot.pizza_ordering_bot.name
  bot_version = "$LATEST"
  name        = "production"
  description = "Production alias for the pizza ordering bot"

  lifecycle {
    prevent_destroy = true
  }

  # NOTE: aws_lex_bot_alias does not support tags - omitted
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "bot_name" {
  description = "Name of the Amazon Lex V2 bot"
  type        = string
  default     = "my-lex-bot"
}

locals {
  aws_region                = "us-east-1"
  lex_log_group_arn_prefix  = "arn:aws:logs:${local.aws_region}:*:log-group:/aws/lex/*"
  lex_log_stream_arn_prefix = "${local.lex_log_group_arn_prefix}:log-stream:*"
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = "dev"
  }
}

resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-cloudwatch-policy"
  description = "Least-privilege CloudWatch Logs permissions for Amazon Lex V2 bot"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "logs:CreateLogGroup"
        Resource = local.lex_log_group_arn_prefix
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.lex_log_stream_arn_prefix
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

resource "aws_lexv2models_bot" "my_bot" {
  name                        = var.bot_name
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = true
  }

  tags = {
    Environment = "dev"
    Name        = var.bot_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.lex_bot_policy_attachment
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  log_group_name = "/aws/lex/children-bot"
  tags = {
    Environment = "dev"
    Project     = "children-lex-bot"
    ManagedBy   = "terraform"
  }
}

# IAM role for Lex V2
data "aws_iam_policy_document" "lex_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lexv2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "lex_bot_role" {
  name               = "children-lex-bot-role"
  assume_role_policy = data.aws_iam_policy_document.lex_trust.json
  tags               = local.tags
}

# CloudWatch Log group for Lex conversation logs
resource "aws_cloudwatch_log_group" "lex_bot_logs" {
  name              = local.log_group_name
  retention_in_days = 7
  tags              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege policy for Lex to write logs
data "aws_iam_policy_document" "lex_logging" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.lex_bot_logs.arn}:*"
    ]
  }
}

resource "aws_iam_policy" "lex_logging_policy" {
  name        = "children-lex-bot-logging"
  description = "Policy for Lex V2 to write conversation logs"
  policy      = data.aws_iam_policy_document.lex_logging.json
  tags        = local.tags
}

resource "aws_iam_role_policy_attachment" "lex_logging_attach" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_logging_policy.arn
}

# Lex V2 Bot
resource "aws_lexv2models_bot" "children_bot" {
  name                        = "ChildrenBot"
  idle_session_ttl_in_seconds = 300
  role_arn                    = aws_iam_role.lex_bot_role.arn
  description                 = "A children-friendly Lex bot compliant with COPPA"
  data_privacy {
    child_directed = true
  }
  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Bot Locale – en_US
resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.children_bot.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  n_lu_intent_confidence_threshold = 0.4
  description                      = "Locale for children's bot"
  voice_settings {
    voice_id = "Ivy"
    engine   = "standard"
  }
}

# Intent – GreetingIntent
resource "aws_lexv2models_intent" "greeting" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id
  name        = "GreetingIntent"
  description = "Handles simple greetings from children"
  sample_utterance {
    utterance = "hello"
  }
  sample_utterance {
    utterance = "hi"
  }
  sample_utterance {
    utterance = "hey"
  }
  sample_utterance {
    utterance = "good morning"
  }
  sample_utterance {
    utterance = "howdy"
  }

  fulfillment_code_hook {
    enabled = false
  }
}

# Optional slot type – ColorType
resource "aws_lexv2models_slot_type" "color" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id
  name        = "ColorType"
  description = "Primary colors for children"
  slot_type_values {
    sample_value {
      value = "red"
    }
  }
  slot_type_values {
    sample_value {
      value = "blue"
    }
  }
  slot_type_values {
    sample_value {
      value = "green"
    }
  }
  slot_type_values {
    sample_value {
      value = "yellow"
    }
  }
  slot_type_values {
    sample_value {
      value = "pink"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.36"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Amazon Connect Instance
# ------------------------------------------------------------------------------
resource "aws_connect_instance" "main" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = "connect-instance-${random_id.suffix.hex}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Service-Linked Role for Amazon Connect
# ------------------------------------------------------------------------------
resource "aws_iam_service_linked_role" "connect" {
  aws_service_name = "connect.amazonaws.com"
  description      = "Service-linked role for Amazon Connect"

  tags = local.tags
}

# Attach IAM policy to the Connect service-linked role granting Lex bot permissions
resource "aws_iam_role_policy" "connect_role_policy" {
  name = "connect-lex-bot-policy"
  role = aws_iam_service_linked_role.connect.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "lex:PostContent",
          "lex:PostText"
        ]
        Resource = aws_lexv2models_bot.main.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM Role for the Lex v2 Bot
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role-${random_id.suffix.hex}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

# Attach IAM policy to the Lex bot role granting invoke permissions on the bot
resource "aws_iam_role_policy" "lex_bot_role_policy" {
  name = "lex-bot-invoke-policy"
  role = aws_iam_role.lex_bot_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "lex:PostContent",
          "lex:PostText"
        ]
        Resource = aws_lexv2models_bot.main.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Lex v2 Bot
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot" "main" {
  name                        = "lex-bot-${random_id.suffix.hex}"
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Lex v2 Bot Locale
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot_locale" "main" {
  bot_id                         = aws_lexv2models_bot.main.id
  bot_version                    = "DRAFT"
  locale_id                      = "en_US"
  n_lu_intent_confidence_threshold = 0.40
}

# ------------------------------------------------------------------------------
# Lex v2 Bot Version
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot_version" "main" {
  bot_id = aws_lexv2models_bot.main.id

  locale_specification = {
    (aws_lexv2models_bot_locale.main.locale_id) = {
      source_bot_version = "DRAFT"
    }
  }
  description = "Initial version"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Connect Bot Association
# ------------------------------------------------------------------------------
resource "aws_connect_bot_association" "main" {
  instance_id = aws_connect_instance.main.id

  lex_bot {
    name       = aws_lexv2models_bot.main.name
    lex_region = "us-east-1"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

locals {
  tags = {
    Project     = "KidsConnect"
    Environment = "dev"
  }
}

resource "aws_connect_instance" "kids" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = "kids-connect-instance"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot" "kids" {
  name             = "KidsBot"
  child_directed   = true
  process_behavior = "BUILD"

  intent {
    intent_name    = "HelloIntent"
    intent_version = "$LATEST"
  }

  abort_statement {
    message {
      content      = "Sorry, I didn't understand."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand. Please rephrase."
      content_type = "PlainText"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot_alias" "kids" {
  bot_name    = aws_lex_bot.kids.name
  bot_version = "$LATEST"
  name        = "KidsBotAlias"
}

resource "aws_iam_role" "connect" {
  name = "KidsConnectRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "connect_lex" {
  name        = "KidsConnectLexPolicy"
  description = "Allow Amazon Connect to interact with the Lex bot"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lex:PostContent",
          "lex:PostText"
        ]
        Resource = aws_lex_bot_alias.kids.arn
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "connect_lex" {
  role       = aws_iam_role.connect.name
  policy_arn = aws_iam_policy.connect_lex.arn
}

resource "aws_connect_bot_association" "kids" {
  instance_id = aws_connect_instance.kids.id

  lex_bot {
    name = aws_lex_bot.kids.name
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

variable "instance_alias" {
  description = "Alias for the Amazon Connect instance"
  type        = string
  default     = "saml-connect-instance"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Name        = "saml-connect-instance"
    Environment = "dev"
  }
}

locals {
  common_tags = var.tags
}

resource "aws_connect_instance" "saml_connect" {
  identity_management_type = "SAML"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = var.instance_alias

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot" "example" {
  name           = "ExampleBot"
  child_directed = false
  process_behavior = "BUILD"

  intent {
    intent_name    = "GreetingIntent"
    intent_version = "$LATEST"
  }

  abort_statement {
    message {
      content      = "Sorry, I didn't understand that."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Please clarify your request."
      content_type = "PlainText"
    }
  }

  locale = "en-US"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_connect_bot_association" "main" {
  instance_id = aws_connect_instance.saml_connect.id

  lex_bot {
    name       = aws_lex_bot.example.name
    lex_region = "us-east-1"
  }
}

terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.90, < 5.100"
    }
  }
}

variable "stream_name" {
  type        = string
  default     = "basic-kinesis-stream"
  description = "Name of the Kinesis data stream."
}

variable "shard_count" {
  type        = number
  default     = 1
  description = "Number of shards for the Kinesis data stream."
}

variable "retention_period" {
  type        = number
  default     = 24
  description = "Data retention period in hours."
}

variable "environment" {
  type        = string
  default     = "dev"
  description = "Deployment environment."
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  common_tags = {
    Environment = var.environment
    Name        = var.stream_name
  }
}

resource "aws_kms_key" "kinesis" {
  description             = "KMS key for Kinesis stream server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "basic-kinesis-stream-key-policy"
    Statement = [
      {
        Sid    = "Allow root account administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:CreateAlias",
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DeleteAlias",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:DisableKeyRotation",
          "kms:EnableKey",
          "kms:EnableKeyRotation",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:GetParametersForImport",
          "kms:GetPublicKey",
          "kms:ImportKeyMaterial",
          "kms:ListAliases",
          "kms:ListGrants",
          "kms:ListKeyPolicies",
          "kms:ListResourceTags",
          "kms:ListRetirableGrants",
          "kms:PutKeyPolicy",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:RevokeGrant",
          "kms:ScheduleKeyDeletion",
          "kms:Sign",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateAlias",
          "kms:UpdateKeyDescription",
          "kms:Verify"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Kinesis to use key for stream encryption"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "kinesis" {
  name          = "alias/basic-kinesis-stream-key"
  target_key_id = aws_kms_key.kinesis.key_id
}

resource "aws_kinesis_stream" "main" {
  name             = var.stream_name
  shard_count      = var.shard_count
  retention_period = var.retention_period
  encryption_type  = "KMS"
  kms_key_id       = aws_kms_key.kinesis.arn

  enforce_consumer_deletion = true

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords",
    "IteratorAgeMilliseconds",
    "WriteProvisionedThroughputExceeded"
  ]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "stream_name" {
  description = "Name of the Kinesis stream."
  value       = aws_kinesis_stream.main.name
}

output "stream_arn" {
  description = "ARN of the Kinesis stream."
  value       = aws_kinesis_stream.main.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used by the Kinesis stream."
  value       = aws_kms_key.kinesis.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

data "aws_iam_policy_document" "kinesis_analytics_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["kinesisanalytics.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "kinesis_analytics_policy" {
  statement {
    actions = [
      "kinesis:GetRecords",
      "kinesis:GetShardIterator",
      "kinesis:DescribeStream",
      "kinesis:ListShards",
    ]
    resources = [aws_kinesis_stream.input.arn]
  }
}

resource "aws_kinesis_stream" "input" {
  name             = "input"
  shard_count      = 1
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"
  retention_period = 24

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name               = "kinesis_analytics_role"
  assume_role_policy = data.aws_iam_policy_document.kinesis_analytics_assume_role.json
}

resource "aws_iam_role_policy" "kinesis_analytics_policy" {
  name   = "kinesis_analytics_policy"
  role   = aws_iam_role.kinesis_analytics_role.name
  policy = data.aws_iam_policy_document.kinesis_analytics_policy.json
}

resource "aws_kinesis_analytics_application" "main" {
  name = "main"

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    parallelism {
      count = 1
    }

    schema {
      record_encoding = "UTF-8"

      record_format {
        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }

      record_columns {
        name     = "COLUMN_1"
        sql_type = "VARCHAR(256)"
        mapping  = "$.COLUMN_1"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "application_name" {
  description = "Name of the Kinesis Analytics Flink application"
  type        = string
  default     = "my-flink-app"
}

variable "flink_runtime_environment" {
  description = "Apache Flink runtime version for the Kinesis Analytics application"
  type        = string
  default     = "FLINK-1_18"
}

variable "flink_jar_file_key" {
  description = "S3 object key for the Flink application JAR or ZIP file"
  type        = string
  default     = "flink-app.jar"
}

variable "log_retention_days" {
  description = "Number of days to retain CloudWatch logs"
  type        = number
  default     = 14
}

# Random suffix for S3 bucket name to ensure global uniqueness
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# S3 bucket for storing Flink application artifacts
resource "aws_s3_bucket" "flink_code" {
  bucket = "kinesis-analytics-flink-code-${random_id.bucket_suffix.hex}"

  tags = {
    Name        = "Kinesis Analytics Flink Code"
    Application = var.application_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "flink_code" {
  bucket = aws_s3_bucket.flink_code.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flink_code" {
  bucket = aws_s3_bucket.flink_code.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "flink_code" {
  bucket = aws_s3_bucket.flink_code.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role for Kinesis Analytics to assume
resource "aws_iam_role" "kinesis_analytics_flink" {
  name = "kinesis-analytics-flink-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "kinesis-analytics-flink-role"
    Application = var.application_name
  }
}

# CloudWatch log group for application monitoring
resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = "/aws/kinesis-analytics/${var.application_name}"
  retention_in_days = var.log_retention_days

  tags = {
    Application = var.application_name
  }
}

# IAM policy with least-privilege permissions
resource "aws_iam_policy" "kinesis_analytics_flink" {
  name        = "kinesis-analytics-flink-policy"
  description = "Permissions for Kinesis Analytics Flink application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.flink_code.arn,
          "${aws_s3_bucket.flink_code.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.kinesis_analytics.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_flink" {
  role       = aws_iam_role.kinesis_analytics_flink.name
  policy_arn = aws_iam_policy.kinesis_analytics_flink.arn
}

# CloudWatch log stream for runtime logs
resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = "application-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# Kinesis Analytics V2 application (Apache Flink)
resource "aws_kinesisanalyticsv2_application" "flink_app" {
  name                   = var.application_name
  runtime_environment    = var.flink_runtime_environment
  service_execution_role = aws_iam_role.kinesis_analytics_flink.arn

  application_configuration {
    application_code_configuration {
      code_content {
        s3_content_location {
          bucket_arn = aws_s3_bucket.flink_code.arn
          file_key   = var.flink_jar_file_key
        }
      }
      code_content_type = "ZIPFILE"
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
  }

  tags = {
    Application = var.application_name
  }
}

# main.tf

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random suffix for globally unique names
resource "random_id" "suffix" {
  byte_length = 4
}

# Static data sources
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Local values
locals {
  project_name = "firehose-dynamic-partitioning"
  bucket_name  = "${local.project_name}-${random_id.suffix.hex}"
  stream_name  = "${local.project_name}-${random_id.suffix.hex}"
  bucket_arn   = "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}"
}

# S3 bucket for Firehose destination
resource "aws_s3_bucket" "firehose_dest" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access to bucket
resource "aws_s3_bucket_public_access_block" "firehose_dest" {
  bucket                  = aws_s3_bucket.firehose_dest.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption for bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_dest" {
  bucket = aws_s3_bucket.firehose_dest.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# IAM role for Firehose
resource "aws_iam_role" "firehose_role" {
  name = "${local.project_name}-role-${random_id.suffix.hex}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# IAM policy for Firehose S3 access (least-privilege)
resource "aws_iam_policy" "firehose_s3_policy" {
  name   = "${local.project_name}-s3-policy-${random_id.suffix.hex}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          local.bucket_arn,
          "${local.bucket_arn}/*"
        ]
      }
    ]
  })
}

# Attach policy to role (fixed: use `role` not `resource`)
resource "aws_iam_role_policy_attachment" "firehose_s3" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_s3_policy.arn
}

# Kinesis Firehose Delivery Stream with extended S3 destination and dynamic partitioning
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = local.stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_role.arn
    bucket_arn          = aws_s3_bucket.firehose_dest.arn
    buffering_size      = 64   # 64 MB
    buffering_interval  = 300  # 300 seconds
    compression_format   = "GZIP"
    prefix              = "data/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/"
    error_output_prefix = "error/!{timestamp:yyyy}/!{timestamp:MM}/!{timestamp:dd}/!{timestamp:HH}/!{firehose:error-output-type}/"

    dynamic_partitioning_configuration {
      enabled        = true
      retry_duration = 300
    }
    # No processing_configuration block – dynamic partitioning does not require a Lambda processor.
  }

  depends_on = [
    aws_iam_role_policy_attachment.firehose_s3,
    aws_s3_bucket_public_access_block.firehose_dest,
    aws_s3_bucket_server_side_encryption_configuration.firehose_dest
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

locals {
  name_prefix = "firehose-redshift"
  common_tags = {
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
  vpc_cidr = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-${count.index}" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-subnet-${count.index}" })
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip" })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags          = merge(local.common_tags, { Name = "${local.name_prefix}-nat" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

data "aws_region" "current" {}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = [aws_route_table.private.id]
  tags            = merge(local.common_tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id
  tags        = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "redshift_ingress" {
  type              = "ingress"
  from_port         = 5439
  to_port           = 5439
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.redshift.id
}

resource "aws_security_group_rule" "redshift_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.redshift.id
}

resource "aws_redshift_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-subnet-group" })
}

resource "random_password" "redshift_master" {
  length  = 16
  special = false
}

resource "aws_secretsmanager_secret" "redshift" {
  name = "${local.name_prefix}-redshift-master-password"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id     = aws_secretsmanager_secret.redshift.id
  secret_string = random_password.redshift_master.result
}

resource "aws_kms_key" "main" {
  description             = "KMS CMK for Redshift and S3 encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  policy                  = <<POLICY
{
  "Version": "2012-10-17",
  "Id": "key-default-1",
  "Statement": [
    {
      "Sid": "Enable IAM User Permissions",
      "Effect": "Allow",
      "Principal": {"AWS": "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"},
      "Action": "kms:*",
      "Resource": "*"
    },
    {
      "Sid": "Allow S3 Service",
      "Effect": "Allow",
      "Principal": {"Service": "s3.amazonaws.com"},
      "Action": [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ],
      "Resource": "*",
      "Condition": {
        "StringEquals": {
          "kms:ViaService": "s3.${data.aws_region.current.name}.amazonaws.com"
        }
      }
    },
    {
      "Sid": "Allow Redshift Service",
      "Effect": "Allow",
      "Principal": {"Service": "redshift.amazonaws.com"},
      "Action": [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ],
      "Resource": "*",
      "Condition": {
        "ArnLike": {
          "kms:EncryptionContext:aws:redshift:cluster-name": "*"
        }
      }
    }
  ]
}
POLICY
  tags = local.common_tags
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "firehose_staging" {
  bucket = "${local.name_prefix}-staging-${random_string.suffix.result}"
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-staging" })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.firehose_staging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.firehose_staging.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "staging" {
  bucket = aws_s3_bucket.firehose_staging.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "firehose_error" {
  bucket = "${local.name_prefix}-error-${random_string.suffix.result}"
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-error" })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "error" {
  bucket = aws_s3_bucket.firehose_error.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "error" {
  bucket = aws_s3_bucket.firehose_error.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "error" {
  bucket = aws_s3_bucket.firehose_error.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  database_name             = "firehose_db"
  master_username           = "admin"
  master_password           = aws_secretsmanager_secret_version.redshift.secret_string
  node_type                 = "dc2.large"
  number_of_nodes           = 1
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids   = [aws_security_group.redshift.id]
  publicly_accessible       = false
  encrypted                 = true
  kms_key_id                = aws_kms_key.main.arn
  skip_final_snapshot       = false
  tags                      = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "firehose" {
  name = "${local.name_prefix}-firehose-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_iam_role_policy" "firehose" {
  name = "${local.name_prefix}-firehose-policy"
  role = aws_iam_role.firehose.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:AbortMultipartUpload"
        ]
        Resource = [
          aws_s3_bucket.firehose_staging.arn,
          "${aws_s3_bucket.firehose_staging.arn}/*",
          aws_s3_bucket.firehose_error.arn,
          "${aws_s3_bucket.firehose_error.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "redshift:DescribeClusters"
        ]
        Resource = aws_redshift_cluster.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.main.arn
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "redshift" {
  name        = "${local.name_prefix}-delivery-stream"
  destination = "redshift"

  redshift_configuration {
    role_arn            = aws_iam_role.firehose.arn
    cluster_jdbcurl     = "jdbc:redshift://${aws_redshift_cluster.main.endpoint}/${aws_redshift_cluster.main.database_name}"
    username            = aws_redshift_cluster.main.master_username
    password            = aws_redshift_cluster.main.master_password
    retry_duration      = 3600
    copy_options        = "json 'auto'"
    data_table_name     = "firehose_table"
    s3_backup_mode      = "FailedDataOnly"
    s3_backup_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.firehose_error.arn
      prefix              = "backup/"
      buffer_size         = 5
      buffer_interval     = 300
      compression_format  = "GZIP"
      encryption_configuration {
        kms_encryption_config {
          awskms_key_arn = aws_kms_key.main.arn
        }
      }
    }
    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.firehose_staging.arn
      prefix              = "staging/"
      buffer_size         = 5
      buffer_interval     = 300
      compression_format  = "GZIP"
      encryption_configuration {
        kms_encryption_config {
          awskms_key_arn = aws_kms_key.main.arn
        }
      }
    }
  }
  tags = local.common_tags
  depends_on = [
    aws_redshift_cluster.main,
    aws_s3_bucket.firehose_staging,
    aws_s3_bucket.firehose_error,
    aws_iam_role.firehose,
    aws_kms_key.main
  ]
}

# Variables
variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Environment = var.environment
  }
}

# Private subnets (two AZs)
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)  # 10.0.1.0/24, 10.0.2.0/24
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Environment = var.environment
    Name        = "private-${count.index + 1}"
  }
}

# Security group for OpenSearch
resource "aws_security_group" "opensearch" {
  name        = "opensearch-sg"
  description = "Allow HTTPS from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.environment
  }
}

# S3 bucket for Firehose backup / failed documents
resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-backup-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  tags = {
    Environment = var.environment
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for Firehose
resource "aws_iam_role" "firehose" {
  name = "firehose-elasticsearch-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Environment = var.environment
  }
}

# IAM policy for Firehose role
data "aws_iam_policy_document" "firehose_policy" {
  statement {
    sid    = "S3Actions"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.firehose_backup.arn,
      "${aws_s3_bucket.firehose_backup.arn}/*"
    ]
  }
  statement {
    sid    = "ESActions"
    effect = "Allow"
    actions = [
      "es:ESHttpPut",
      "es:ESHttpGet"
    ]
    resources = [
      "${aws_opensearch_domain.main.arn}/*"
    ]
  }
}

resource "aws_iam_role_policy" "firehose" {
  name   = "firehose-elasticsearch-policy"
  role   = aws_iam_role.firehose.name
  policy = data.aws_iam_policy_document.firehose_policy.json
}

# OpenSearch domain (Elasticsearch 7.10)
resource "aws_opensearch_domain" "main" {
  domain_name    = "firehose-es-domain"
  engine_version = "Elasticsearch_7.10"

  cluster_config {
    instance_type  = "t3.small.search"
    instance_count = 1
  }

  vpc_options {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.opensearch.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
    volume_type = "gp3"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action = [
          "es:ESHttpPut",
          "es:ESHttpGet"
        ]
        Resource = "arn:aws:es:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:domain/${aws_opensearch_domain.main.domain_name}/*"
      }
    ]
  })

  tags = {
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "firehose-es-stream"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn           = aws_opensearch_domain.main.arn
    role_arn             = aws_iam_role.firehose.arn
    index_name           = "logs"
    index_rotation_period = "OneDay"
    type_name            = "log"  # deprecated but required for ES 7.10
    buffering_interval   = 60
    buffering_size       = 5
    retry_duration       = 300

    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      bucket_arn          = aws_s3_bucket.firehose_backup.arn
      role_arn            = aws_iam_role.firehose.arn
      prefix              = "firehose-failed/!{timestamp:yyyy/MM/dd}/"
      error_output_prefix = "firehose-errors/!{timestamp:yyyy/MM/dd}/"
      buffering_interval  = 60
      buffering_size      = 5
      compression_format  = "GZIP"
    }
  }

  tags = {
    Environment = var.environment
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.95.0"
    }
  }
}

# Variables
variable "environment" {
  description = "Environment name for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "Terraform"
    Purpose     = "Firehose to OpenSearch"
  }
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}

# Local values
locals {
  account_id  = data.aws_caller_identity.current.account_id
  name_prefix = "firehose-opensearch-${var.environment}"
}

# ------------------------------------------------------------------------------
# S3 Bucket for Firehose backup / failed documents
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "backup" {
  bucket = "firehose-backup-${local.account_id}-${var.environment}"

  tags = merge(var.tags, { Name = "${local.name_prefix}-backup" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# IAM Role for Firehose to write to S3 and OpenSearch
# ------------------------------------------------------------------------------
resource "aws_iam_role" "firehose" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "${local.name_prefix}-role" })
}

data "aws_iam_policy_document" "firehose" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.backup.arn,
      "${aws_s3_bucket.backup.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "es:ESHttpPut",
      "es:ESHttpPost"
    ]
    resources = [
      "${aws_opensearch_domain.main.arn}/*"
    ]
  }
}

resource "aws_iam_policy" "firehose" {
  name   = "${local.name_prefix}-policy"
  policy = data.aws_iam_policy_document.firehose.json
}

resource "aws_iam_role_policy_attachment" "firehose" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose.arn
}

# ------------------------------------------------------------------------------
# Amazon OpenSearch Service Domain
# ------------------------------------------------------------------------------
resource "aws_opensearch_domain" "main" {
  domain_name    = "${local.name_prefix}-domain"
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type  = "t3.small.search"
    instance_count = 1
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  # Public endpoint access policy – allow Firehose IAM role
  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action = "es:ESHttp*"
        Resource = aws_opensearch_domain.main.arn
      }
    ]
  })

  tags = merge(var.tags,{ Name = "${local.name_prefix}-domain" })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Kinesis Firehose Delivery Stream (OpenSearch destination)
#------------------------------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "opensearch" {
  name        = "${local.name_prefix}-stream"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = aws_opensearch_domain.main.arn
    index_name = "logs"
    role_arn   = aws_iam_role.firehose.arn

    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      bucket_arn         = aws_s3_bucket.backup.arn
      role_arn          = aws_iam_role.firehose.arn
      buffering_size      = 5
      buffering_interval  = 60
      compression_format  = "GZIP"
      prefix              = "failed-documents/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/"
      error_output_prefix = "errors/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-stream" })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.75.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "environment_name" {
  description = "Environment name for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "splunk_hec_endpoint" {
  description = "Splunk HTTP Event Collector endpoint"
  type        = string
  sensitive   = true
}

variable "splunk_hec_token" {
  description = "Splunk HTTP Event Collector token"
  type        = string
  sensitive   = true
}

# Local values
locals {
  common_tags = {
    Environment = var.environment_name
    ManagedBy   = "Terraform"
  }
  name_prefix = "firehose-${var.environment_name}-"
}

# Random suffix for global uniqueness
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# Backup S3 bucket
resource "aws_s3_bucket" "backup" {
  bucket        = "firehose-backup-${random_id.bucket_suffix.hex}"
  force_destroy = false
  tags = merge(local.common_tags, { Name = "Firehose Backup Bucket" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# IAM role for Firehose to write to S3
resource "aws_iam_role" "firehose_s3" {
  name = "${local.name_prefix}firehose-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "firehose_s3_write" {
  name = "${local.name_prefix}firehose-s3-write-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "s3:PutObject"
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.backup.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3" {
  role       = aws_iam_role.firehose_s3.name
  policy_arn = aws_iam_policy.firehose_s3_write.arn
}

# Secrets Manager for Splunk HEC credentials
resource "aws_secretsmanager_secret" "splunk" {
  name        = "${local.name_prefix}splunk-hec-credentials"
  description = "Splunk HEC endpoint and token for Firehose delivery stream"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "splunk" {
  secret_id = aws_secretsmanager_secret.splunk.id

  secret_string = jsonencode({
    endpoint = var.splunk_hec_endpoint
    token    = var.splunk_hec_token
  })
}

# Kinesis Firehose Delivery Stream with Splunk destination
resource "aws_kinesis_firehose_delivery_stream" "splunk" {
  name        = "${local.name_prefix}splunk-stream"
  destination = "splunk"

  splunk_configuration {
    hec_endpoint               = jsondecode(aws_secretsmanager_secret_version.splunk.secret_string)["endpoint"]
    hec_token                   = jsondecode(aws_secretsmanager_secret_version.splunk.secret_string)["token"]
    hec_acknowledgment_timeout = 600

    # Backup all documents to S3
    s3_backup_mode = "AllDocuments"

    s3_configuration {
      bucket_arn           = aws_s3_bucket.backup.arn
      role_arn             = aws_iam_role.firehose_s3.arn
      prefix               = "firehose/{{timestamp}}/"
      error_output_prefix  = "firehose-errors/"
      buffering_interval   = 60
      buffering_size       = 5
    }
  }

  tags = local.common_tags
}

variable "environment" {
  description = "Environment name used for resource naming"
  type        = string
  default     = "dev"
}

# KMS key for OpenSearch Serverless encryption
resource "aws_kms_key" "opensearch" {
  description             = "KMS key for OpenSearch Serverless collection"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

# OpenSearch Serverless collection
resource "aws_opensearchserverless_collection" "main" {
  name = "firehose-collection-${var.environment}"
  type = "SEARCH"

  lifecycle {
    prevent_destroy = true
  }
}

# Network security policy to allow public access with IAM authorization
resource "aws_opensearchserverless_security_policy" "network" {
  name        = "firehose-network-policy-${var.environment}"
  type        = "network"
  description = "Allow public access with IAM authorization"

  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${aws_opensearchserverless_collection.main.name}"]
      }
    ]
    AllowFromPublic = true
  })
}

# Encryption security policy using customer-managed KMS key
resource "aws_opensearchserverless_security_policy" "encryption" {
  name        = "firehose-encryption-policy-${var.environment}"
  type        = "encryption"
  description = "Use customer-managed KMS key"

  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${aws_opensearchserverless_collection.main.name}"]
      }
    ]
    AWSOwnedKey = false
    KmsARN      = aws_kms_key.opensearch.arn
  })
}

# Opensearch Serverless access policy for Firehose to write to the collection
resource "aws_opensearchserverless_access_policy" "firehose_write" {
  name        = "firehose-access-policy-${var.environment}"
  type        = "data"
  description = "Allow Firehose to write to the collection"

  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "index"
          Resource     = ["index/*"]
          Permission   = ["aoss:WriteDocument", "aoss:ReadDocument", "aoss:DescribeIndex"]
        }
      ]
      Principal = [aws_iam_role.firehose.arn]
    }
  ])
}

# IAM role for Firehose
resource "aws_iam_role" "firehose" {
  name = "firehose-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for Firehose to interact with OpenSearch Serverless
resource "aws_iam_policy" "firehose_opensearch" {
  name        = "firehose-opensearch-policy-${var.environment}"
  description = "Least-privilege policy for Firehose to write to OpenSearch Serverless"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["firehose:DescribeDeliveryStream"]
        Resource = [aws_kinesis_firehose_delivery_stream.opensearch_serverless.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "aoss:*",
          "es:ESHttpPut",
          "es:ESHttpPost"
        ]
        Resource = [aws_opensearchserverless_collection.main.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_opensearch" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_opensearch.arn
}

# S3 bucket for failed document backup
resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-backup-${var.environment}-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Kinesis Firehose Delivery Stream to OpenSearch Serverless
resource "aws_kinesis_firehose_delivery_stream" "opensearch_serverless" {
  name        = "firehose-opensearch-serverless-${var.environment}"
  destination = "opensearchserverless"

  opensearchserverless_configuration {
    index_name                 = "firehose-index" # default index name
    s3_backup_mode             = "FailedDocumentsOnly"
    buffering_size             = 10   # MB
    buffering_interval         = 400  # seconds
    role_arn                   = aws_iam_role.firehose.arn
    collection_endpoint        = aws_opensearchserverless_collection.main.collection_endpoint

    s3_configuration {
      bucket_arn = aws_s3_bucket.firehose_backup.arn
      role_arn   = aws_iam_role.firehose.arn
    }
  }
}

# Data source for current AWS account ID (used in bucket naming)
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.1.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  common_tags = {
    Environment = "dev"
    Project     = "firehose-es"
  }
  backup_bucket_name = "firehose-backup-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "firehose-es-vpc" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, { Name = "firehose-private-subnet-${count.index}" })
}

resource "aws_security_group" "firehose" {
  name        = "firehose-vpc-endpoint-sg"
  description = "Security group for Firehose VPC endpoints"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.common_tags, { Name = "firehose-sg" })
}

resource "aws_security_group" "opensearch" {
  name        = "opensearch-sg"
  description = "Security group for OpenSearch domain"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.common_tags, { Name = "opensearch-sg" })
}

resource "aws_security_group_rule" "firehose_egress_opensearch" {
  type      = "egress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"
  security_group_id        = aws_security_group.firehose.id
  source_security_group_id = aws_security_group.opensearch.id
}

resource "aws_security_group_rule" "opensearch_ingress_firehose" {
  type      = "ingress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"
  security_group_id        = aws_security_group.opensearch.id
  source_security_group_id = aws_security_group.firehose.id
}

resource "aws_opensearch_domain" "this" {
  domain_name    = "fh-es-domain"
  engine_version = "Elasticsearch_7.10"

  cluster_config {
    instance_type = "t3.small.search"
  }

  vpc_options {
    subnet_ids         = [aws_subnet.private[0].id]
    security_group_ids = [aws_security_group.opensearch.id]
  }

  encrypt_at_rest {
    enabled = true
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  advanced_security_options {
    enabled = false
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action   = "es:ESHttpPut"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "firehose-es-domain" })
}

resource "aws_iam_role" "firehose" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

data "aws_iam_policy_document" "firehose_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeVpcs",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:CreateNetworkInterfacePermission"
    ]
    resources = ["*"]
  }

  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.backup.arn}/*"]
  }

  statement {
    effect    = "Allow"
    actions   = ["es:ESHttpPut"]
    resources = [aws_opensearch_domain.this.arn]
  }
}

resource "aws_iam_role_policy" "firehose" {
  name   = "firehose-permissions"
  role   = aws_iam_role.firehose.id
  policy = data.aws_iam_policy_document.firehose_permissions.json
}

resource "aws_s3_bucket" "backup" {
  bucket = local.backup_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "firehose-backup-bucket" })
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "s3_backup_policy" {
  statement {
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.backup.arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "backup" {
  bucket = aws_s3_bucket.backup.id
  policy = data.aws_iam_policy_document.s3_backup_policy.json
}

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = "firehose-es-stream"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn = aws_opensearch_domain.this.arn
    role_arn   = aws_iam_role.firehose.arn
    index_name = "firehose-index"
    type_name  = "_doc"

    s3_backup_mode = "FailedDocumentsOnly"
    s3_configuration {
      bucket_arn = aws_s3_bucket.backup.arn
      role_arn   = aws_iam_role.firehose.arn
    }

    vpc_config {
      subnet_ids         = aws_subnet.private[*].id
      security_group_ids = [aws_security_group.firehose.id]
      role_arn           = aws_iam_role.firehose.arn
    }
  }

  tags = local.common_tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
  required_version = ">= 1.0"
}

variable "new_relic_endpoint_url" {
  type        = string
  default     = "https://aws-api.newrelic.com/aws/v1/"
  description = "New Relic HTTP endpoint URL"
}

variable "new_relic_api_key" {
  type        = string
  default     = "placeholder"
  sensitive   = true
  description = "New Relic API key"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_kms_key" "firehose" {
  description             = "KMS key for Firehose delivery stream encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "firehose-kms-key-policy"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowFirehoseToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "firehose" {
  name          = "alias/firehose-new-relic-key"
  target_key_id = aws_kms_key.firehose.id
}

resource "aws_s3_bucket" "firehose_failed_records" {
  bucket = "firehose-failed-records-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_failed_records" {
  bucket                  = aws_s3_bucket.firehose_failed_records.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_failed_records" {
  bucket = aws_s3_bucket.firehose_failed_records.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_secretsmanager_secret" "new_relic_api_key" {
  name        = "new-relic-api-key"
  description = "New Relic API key used by Firehose HTTP endpoint"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "new_relic_api_key" {
  secret_id     = aws_secretsmanager_secret.new_relic_api_key.id
  secret_string = var.new_relic_api_key
}

resource "aws_iam_role" "firehose" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesis-firehose/new-relic"
  retention_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_stream" "firehose" {
  name           = "new-relic-delivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

resource "aws_iam_role_policy" "firehose" {
  name = "firehose-delivery-policy"
  role = aws_iam_role.firehose.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Delivery"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_failed_records.arn,
          "${aws_s3_bucket.firehose_failed_records.arn}/*"
        ]
      },
      {
        Sid    = "KMSEncryption"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.firehose.arn
      },
      {
        Sid      = "SecretsManagerGetSecret"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.new_relic_api_key.arn
      },
      {
        Sid    = "CloudWatchLogsGroup"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.firehose.arn
      },
      {
        Sid      = "CloudWatchLogsStream"
        Effect   = "Allow"
        Action   = "logs:PutLogEvents"
        Resource = aws_cloudwatch_log_stream.firehose.arn
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "new_relic" {
  name        = "new-relic-firehose"
  destination = "http_endpoint"

  server_side_encryption {
    enabled  = true
    key_arn  = aws_kms_key.firehose.arn
    key_type = "CUSTOMER_MANAGED_CMK"
  }

  http_endpoint_configuration {
    url                = var.new_relic_endpoint_url
    name               = "New Relic"
    role_arn           = aws_iam_role.firehose.arn
    s3_backup_mode     = "FailedDocumentsOnly"
    buffering_size     = 5
    buffering_interval = 60
    retry_duration     = 300

    secrets_manager_configuration {
      enabled    = true
      role_arn   = aws_iam_role.firehose.arn
      secret_arn = aws_secretsmanager_secret.new_relic_api_key.arn
    }

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.firehose.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose.arn
      bucket_arn         = aws_s3_bucket.firehose_failed_records.arn
      buffering_size     = 10
      buffering_interval = 60
      compression_format = "GZIP"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for naming and tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  environment        = lower(var.environment)
  name_prefix        = "firehose-opensearch-${local.environment}"
  domain_name        = "firehose-logs-${local.environment}"
  domain_arn         = "arn:${data.aws_partition.current.partition}:es:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:domain/${local.domain_name}"
  backup_bucket_name = "firehose-opensearch-backup-${data.aws_region.current.name}-${data.aws_caller_identity.current.account_id}-${local.environment}"
  common_tags = {
    Environment = local.environment
    Name        = local.name_prefix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_security_group" "opensearch" {
  name_prefix = "${local.name_prefix}-opensearch-sg-"
  description = "Security group for OpenSearch domain and Firehose VPC access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "OpenSearch node-to-node communication"
    from_port   = 9300
    to_port     = 9300
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-opensearch-sg" })
}

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = "es.amazonaws.com"
  description      = "Service-linked role for Amazon OpenSearch Service"
}

resource "aws_iam_role" "firehose" {
  name = "${local.name_prefix}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesis-firehose/${local.name_prefix}"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "firehose" {
  name           = "opensearch-destination"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

resource "aws_s3_bucket" "backup" {
  bucket        = local.backup_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket                  = aws_s3_bucket.backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "backup" {
  bucket = aws_s3_bucket.backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseWrite"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.backup.arn,
          "${aws_s3_bucket.backup.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_opensearch_domain" "main" {
  domain_name    = local.domain_name
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type          = "t3.medium.search"
    instance_count         = 2
    zone_awareness_enabled = true

    zone_awareness_config {
      availability_zone_count = 2
    }
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
    volume_type = "gp3"
  }

  vpc_options {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.opensearch.id]
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseOpenSearchAccess"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action = [
          "es:ESHttpPut",
          "es:ESHttpPost"
        ]
        Resource = "${local.domain_arn}/*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = local.domain_name })

  depends_on = [aws_iam_service_linked_role.opensearch]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "firehose" {
  name = "firehose-opensearch-policy"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowOpenSearchDiscovery"
        Effect = "Allow"
        Action = [
          "es:DescribeDomain",
          "es:DescribeDomains",
          "es:DescribeDomainConfig"
        ]
        Resource = aws_opensearch_domain.main.arn
      },
      {
        Sid    = "AllowOpenSearchWrite"
        Effect = "Allow"
        Action = [
          "es:ESHttpPut",
          "es:ESHttpPost"
        ]
        Resource = "${aws_opensearch_domain.main.arn}/*"
      },
      {
        Sid    = "AllowS3Backup"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.backup.arn,
          "${aws_s3_bucket.backup.arn}/*"
        ]
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.firehose.arn
      },
      {
        Sid    = "AllowFirehoseVPCManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:ModifyNetworkInterfaceAttribute"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "${local.name_prefix}-stream"
  destination = "opensearch"
  tags        = local.common_tags

  opensearch_configuration {
    domain_arn            = aws_opensearch_domain.main.arn
    index_name            = "firehose-logs"
    role_arn              = aws_iam_role.firehose.arn
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_interval    = 300
    buffering_size        = 5
    index_rotation_period = "OneDay"
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.firehose.name
    }

    vpc_config {
      subnet_ids         = aws_subnet.private[*].id
      security_group_ids = [aws_security_group.opensearch.id]
      role_arn           = aws_iam_role.firehose.arn
    }

    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.backup.arn
      prefix              = "firehose/backup/"
      error_output_prefix = "firehose/error/"
      buffering_interval  = 300
      buffering_size      = 5
      compression_format  = "GZIP"
    }
  }

  depends_on = [
    aws_iam_role_policy.firehose,
    aws_s3_bucket_policy.backup
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "stream_name" {
  type        = string
  default     = "example-video-stream"
  description = "Name of the Kinesis Video Stream."
}

resource "aws_kinesis_video_stream" "main" {
  name                    = var.stream_name
  data_retention_in_hours = 24

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "stream_name" {
  type    = string
  default = "my-kinesis-stream"
}

variable "consumer_name" {
  type    = string
  default = "my-consumer"
}

locals {
  default_tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_kinesis_stream" "main" {
  name             = var.stream_name
  retention_period = 24
  shard_count      = 1
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"
  tags             = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream_consumer" "main" {
  name       = var.consumer_name
  stream_arn = aws_kinesis_stream.main.arn
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  firehose_log_group_arn = replace(aws_cloudwatch_log_group.firehose_delivery.arn, ":*", "")
}

resource "aws_s3_bucket" "destination" {
  bucket_prefix = "firehose-s3-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "destination" {
  bucket = aws_s3_bucket.destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "destination" {
  bucket = aws_s3_bucket.destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "destination" {
  bucket = aws_s3_bucket.destination.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.destination.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "destination" {
  description         = "Customer-managed KMS key for Firehose S3 destination encryption"
  enable_key_rotation = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "destination" {
  name          = "alias/firehose-s3-key"
  target_key_id = aws_kms_key.destination.key_id
}

resource "aws_iam_role" "firehose_delivery" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_s3_delivery" {
  name = "firehose-s3-delivery"
  role = aws_iam_role.firehose_delivery.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.destination.arn,
        ]
      },
      {
        Sid    = "S3ObjectLevelAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = [
          "${aws_s3_bucket.destination.arn}/*",
        ]
      },
      {
        Sid    = "FirehoseKmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = [
          aws_kms_key.destination.arn,
        ]
      },
      {
        Sid    = "FirehoseCloudWatchLogGroupAccess"
        Effect = "Allow"
        Action = [
          "logs:DescribeLogStreams",
        ]
        Resource = [
          local.firehose_log_group_arn,
        ]
      },
      {
        Sid    = "FirehoseCloudWatchLogStreamAccess"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
        ]
        Resource = [
          "${local.firehose_log_group_arn}:log-stream:${aws_cloudwatch_log_stream.firehose_s3.name}",
        ]
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "firehose_delivery" {
  name              = "/aws/kinesis-firehose/firehose-s3"
  retention_in_days = 7
}

resource "aws_cloudwatch_log_stream" "firehose_s3" {
  name           = "extended-s3-destination"
  log_group_name = aws_cloudwatch_log_group.firehose_delivery.name
}

resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "kinesis-firehose-s3"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery.arn
    bucket_arn          = aws_s3_bucket.destination.arn
    buffering_size      = 64
    buffering_interval  = 300
    compression_format  = "GZIP"
    prefix              = "data/"
    error_output_prefix = "errors/"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_s3.name
    }
  }

  server_side_encryption {
    enabled     = true
    key_arn     = aws_kms_key.destination.arn
    key_type    = "CUSTOMER_MANAGED_CMK"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Source Kinesis stream
resource "aws_kinesis_stream" "source" {
  name             = "kinesis-analytics-source-stream"
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  lifecycle {
    prevent_destroy = true
  }
}

# Destination Kinesis stream
resource "aws_kinesis_stream" "destination" {
  name             = "kinesis-analytics-destination-stream"
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for Kinesis Analytics
resource "aws_iam_role" "analytics_role" {
  name               = "kinesis-analytics-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for analytics
data "aws_iam_policy_document" "analytics_policy" {
  statement {
    effect = "Allow"
    actions = [
      "kinesis:DescribeStream",
      "kinesis:GetRecords",
      "kinesis:GetShardIterator",
      "kinesis:ListShards"
    ]
    resources = [aws_kinesis_stream.source.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "kinesis:PutRecord",
      "kinesis:PutRecords"
    ]
    resources = [aws_kinesis_stream.destination.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups"
    ]
    resources = [
      aws_cloudwatch_log_group.analytics.arn,
      "${aws_cloudwatch_log_group.analytics.arn}:*"
    ]
  }
}

resource "aws_iam_policy" "analytics_policy" {
  name        = "kinesis-analytics-policy"
  description = "Least-privilege policy for Kinesis Analytics application"
  policy      = data.aws_iam_policy_document.analytics_policy.json
}

resource "aws_iam_role_policy_attachment" "analytics" {
  role       = aws_iam_role.analytics_role.name
  policy_arn = aws_iam_policy.analytics_policy.arn
}

# CloudWatch log group and stream
resource "aws_cloudwatch_log_group" "analytics" {
  name              = "/aws/kinesis-analytics/application"
  retention_in_days = 7
}

resource "aws_cloudwatch_log_stream" "analytics" {
  name           = "kinesis-analytics-log-stream"
  log_group_name = aws_cloudwatch_log_group.analytics.name
}

# Kinesis Analytics SQL Application
resource "aws_kinesis_analytics_application" "main" {
  name        = "my-kinesis-analytics-app"
  description = "Basic Kinesis Analytics SQL application"
  runtime     = "SQL-1_0"

  code = <<EOF
SELECT STREAM event_time, event_type, payload
FROM "SOURCE_SQL_STREAM_001"
EOF

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.source.arn
      role_arn     = aws_iam_role.analytics_role.arn
    }

    parallelism {
      count = 1
    }

    starting_position_configuration {
      starting_position = "NOW"
    }

    record_format {
      record_row_path = "$"
      record_format_type = "JSON"

      mapping_parameters {
        json {
          record_row_path = "$"
        }
      }
    }

    record_columns {
      name    = "event_time"
      sql_type = "TIMESTAMP"
      mapping  = "$.event_time"
    }

    record_columns {
      name    = "event_type"
      sql_type = "VARCHAR(32)"
      mapping  = "$.event_type"
    }

    record_columns {
      name    = "payload"
      sql_type = "VARCHAR(1024)"
      mapping  = "$.payload"
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.destination.arn
      role_arn     = aws_iam_role.analytics_role.arn
    }

    schema {
      record_format_type = "JSON"
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.analytics.arn
    role_arn       = aws_iam_role.analytics_role.arn
  }

  start_application = true

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.80.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  name_prefix = "kinesis-analytics-${var.environment}"
  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# KMS key for encrypting Kinesis Analytics application data (kept for future use or other services)
resource "aws_kms_key" "analytics" {
  description             = "KMS key for Kinesis Analytics application ${var.environment}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Kinesis Analytics Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "analytics" {
  name          = "alias/kinesis-analytics-key"
  target_key_id = aws_kms_key.analytics.key_id
}

# IAM role for Kinesis Analytics
resource "aws_iam_role" "analytics" {
  name = "kinesis-analytics-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

# Custom IAM policy for minimal permissions
resource "aws_iam_policy" "analytics" {
  name        = "kinesis-analytics-policy"
  description = "Minimal permissions for Kinesis Analytics SQL application"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsPermissions"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogGroup",
          "logs:CreateLogStream"
        ]
        Resource = "arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:log-group:/aws/kinesis-analytics/*"
      },
      {
        Sid    = "KMSDecryptPermission"
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = aws_kms_key.analytics.arn
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "analytics" {
  role       = aws_iam_role.analytics.name
  policy_arn = aws_iam_policy.analytics.arn
}

# Kinesis Analytics V2 SQL application
resource "aws_kinesisanalyticsv2_application" "sql_application" {
  name                   = local.name_prefix
  runtime_environment    = "SQL-1_0"
  service_execution_role = aws_iam_role.analytics.arn

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = "CREATE STREAM example_stream (col1 INT, col2 VARCHAR(100));"
      }
      code_content_type = "PLAINTEXT"
    }

    environment_properties {
      property_group {
        property_group_id = "SQLRuntimeProperties"
        property_map = {
          "OutputKinesisStreamARN" = "arn:aws:kinesis:us-east-1:${data.aws_caller_identity.current.account_id}:stream/example-output"
        }
      }
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Name        = "kinesis-analytics-app"
  }
}

locals {
  name_prefix = "kinesis-analytics-demo"
}

# CloudWatch Log Group for Kinesis Analytics application logs
resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = "/aws/kinesis-analytics/${local.name_prefix}"
  retention_in_days = 7
  tags              = var.tags
}

# Log stream inside the log group
resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = "kinesis-analytics-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# IAM role for Kinesis Analytics to write logs to CloudWatch
resource "aws_iam_role" "kinesis_analytics" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# IAM policy with least-privilege permissions for CloudWatch logs
resource "aws_iam_policy" "kinesis_analytics_cloudwatch_logs" {
  name        = "${local.name_prefix}-cloudwatch-logs-policy"
  description = "Policy allows Kinesis Analytics to write logs to CloudWatch"
  tags        = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.kinesis_analytics.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_cloudwatch_logs" {
  role       = aws_iam_role.kinesis_analytics.name
  policy_arn = aws_iam_policy.kinesis_analytics_cloudwatch_logs.arn
}

# Kinesis Stream as input source
resource "aws_kinesis_stream" "input" {
  name              = "${local.name_prefix}-input-stream"
  shard_count       = 1
  retention_period  = 24
  tags              = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Kinesis Analytics Application (SQL runtime)
resource "aws_kinesis_analytics_application" "main" {
  name        = "${local.name_prefix}-app"
  description = "Basic Kinesis Analytics application with CloudWatch log stream"

  # CloudWatch logging
  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input.arn
      role_arn     = aws_iam_role.kinesis_analytics.arn
    }

    parallelism {
      count = 1
    }

    schema {
      record_columns {
        name     = "COLUMN1"
        sql_type = "INTEGER"
      }
      record_format {
        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
    ignore_changes = [
      inputs[0].schema,
      inputs[0].kinesis_stream,
    ]
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "kendra-proxy-ds"
  vpc_cidr    = "10.0.0.0/16"
  azs         = data.aws_availability_zones.available.names
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "proxy" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-${count.index}"
  }
}

resource "aws_security_group" "proxy" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Kendra data source proxy configuration"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

resource "aws_secretsmanager_secret" "proxy_credentials" {
  name_prefix = "${local.name_prefix}-creds-"
  description = "Proxy credentials for Kendra data source"
  kms_key_id  = "alias/aws/secretsmanager"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "proxy_credentials" {
  secret_id = aws_secretsmanager_secret.proxy_credentials.id
  secret_string = jsonencode({
    username = "proxyuser"
    password = "proxypass123!"
  })
}

resource "aws_iam_role" "kendra_index" {
  name = "${local.name_prefix}-index-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_index_fullaccess" {
  role       = aws_iam_role.kendra_index.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKendraFullAccess"
}

resource "aws_iam_role" "kendra_data_source" {
  name = "${local.name_prefix}-ds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_data_source_fullaccess" {
  role       = aws_iam_role.kendra_data_source.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKendraFullAccess"
}

resource "aws_kendra_index" "main" {
  name     = "${local.name_prefix}-index"
  role_arn = aws_iam_role.kendra_index.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kendra_data_source" "main" {
  index_id = aws_kendra_index.main.id
  name     = "${local.name_prefix}-source"
  role_arn = aws_iam_role.kendra_data_source.arn
  type     = "WEBCRAWLER"

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }

      proxy_configuration {
        credentials = aws_secretsmanager_secret.proxy_credentials.arn
        host        = "proxy.example.com"
        port        = 3128
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
  required_version = ">= 1.0"
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = local.common_tags
  }
}

locals {
  env = "dev"
  common_tags = {
    Environment = local.env
    ManagedBy   = "terraform"
  }
  kendra_index_name       = "kendra-index-${local.env}"
  kendra_data_source_name = "kendra-web-crawler-${local.env}"
}

data "aws_iam_policy_document" "kendra_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kendra.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "kendra_index" {
  name               = "kendra-index-${local.env}"
  description        = "IAM role used by Amazon Kendra to access CloudWatch logs and metrics"
  assume_role_policy = data.aws_iam_policy_document.kendra_assume_role.json
}

resource "aws_iam_role" "kendra_data_source" {
  name               = "kendra-data-source-${local.env}"
  description        = "IAM role used by the Amazon Kendra Web Crawler data source"
  assume_role_policy = data.aws_iam_policy_document.kendra_assume_role.json
}

data "aws_iam_policy_document" "kendra_cloudwatch" {
  statement {
    actions = [
      "cloudwatch:PutMetricData",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "kendra_cloudwatch" {
  name        = "kendra-cloudwatch-${local.env}"
  description = "IAM policy granting Amazon Kendra minimal CloudWatch Logs and metrics access"
  policy      = data.aws_iam_policy_document.kendra_cloudwatch.json
}

resource "aws_iam_role_policy_attachment" "kendra_cloudwatch" {
  role       = aws_iam_role.kendra_index.name
  policy_arn = aws_iam_policy.kendra_cloudwatch.arn
}

resource "aws_kendra_index" "this" {
  name        = local.kendra_index_name
  description = "Amazon Kendra index for web crawler data"
  edition     = "DEVELOPER_EDITION"
  role_arn    = aws_iam_role.kendra_index.arn

  capacity_units {
    query_capacity_units   = 1
    storage_capacity_units = 1
  }

  depends_on = [aws_iam_role_policy_attachment.kendra_cloudwatch]

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kendra_web_crawler" {
  statement {
    actions = [
      "kendra:DescribeDataSource",
      "kendra:ListDataSourceSyncJobs",
      "kendra:StartDataSourceSyncJob",
      "kendra:StopDataSourceSyncJob",
    ]

    resources = ["${aws_kendra_index.this.arn}/data-source/*"]
  }
}

resource "aws_iam_policy" "kendra_web_crawler" {
  name        = "kendra-web-crawler-${local.env}"
  description = "Least-privilege IAM policy for the Amazon Kendra Web Crawler data source"
  policy      = data.aws_iam_policy_document.kendra_web_crawler.json
}

resource "aws_iam_role_policy_attachment" "kendra_web_crawler" {
  role       = aws_iam_role.kendra_data_source.name
  policy_arn = aws_iam_policy.kendra_web_crawler.arn
}

resource "aws_kendra_data_source" "this" {
  index_id    = aws_kendra_index.this.id
  name        = local.kendra_data_source_name
  description = "Amazon Kendra Web Crawler data source with URL inclusion and exclusion patterns"
  type        = "WEBCRAWLER"
  role_arn    = aws_iam_role.kendra_data_source.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }

      url_inclusion_patterns = ["^https://example\\.com/(blog|docs)/.*"]
      url_exclusion_patterns = ["^https://example\\.com/(admin|private|secure)/.*"]
      crawl_depth                      = 2
      max_links_per_page               = 100
      max_urls_per_minute_crawl_rate   = 300
      max_content_size_per_page_in_mega_bytes = 50
    }
  }

  depends_on = [aws_iam_role_policy_attachment.kendra_web_crawler]

  lifecycle {
    prevent_destroy = true
  }
}

