terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 5.100.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for naming and tagging all resources"
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "kendra-index-${var.environment}"
}

resource "aws_cloudwatch_log_group" "kendra_index" {
  name              = "/aws/kendra/index-${var.environment}"
  retention_in_days = 7

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_role" "kendra_index" {
  name        = "${local.name_prefix}-role"
  description = "IAM role assumed by Amazon Kendra to manage the index and write error logs to CloudWatch Logs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_policy" "kendra_index" {
  name        = "${local.name_prefix}-policy"
  description = "Least-privilege permissions for the Amazon Kendra index role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:DescribeLogGroups",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.kendra_index.arn
      },
      {
        Sid    = "IdentityCenterUserGroupResolution"
        Effect = "Allow"
        Action = [
          "sso:DescribeDirectory",
          "sso:DescribeUser",
          "sso:ListDirectoryAssociations",
          "sso:ListGroupMemberships",
          "sso:ListGroups"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "kendra_index" {
  role       = aws_iam_role.kendra_index.name
  policy_arn = aws_iam_policy.kendra_index.arn
}

resource "aws_kendra_index" "main" {
  name        = local.name_prefix
  description = "Amazon Kendra index with user group resolution through AWS IAM Identity Center"
  edition     = "DEVELOPER_EDITION"
  role_arn    = aws_iam_role.kendra_index.arn

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }

  depends_on = [
    aws_iam_role_policy_attachment.kendra_index
  ]

  tags = {
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "zone_name" {
