      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
  required_version = ">= 1.0"
}

variable "record_name" {
  type    = string
  default = "www"
}

variable "record_value" {
  type    = string
  default = "10.0.0.10"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main"
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "internal.example53.com"

  vpc {
    vpc_id     = aws_vpc.main.id
    vpc_region = "us-east-1"
  }
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.private_zone.id
  name    = var.record_name
  type    = "A"
  ttl     = 300
  records = [var.record_value]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Domain name for the Route53 hosted zone"
  type        = string
  default     = "example.com"
}

variable "primary_endpoint_ip" {
  description = "IP address of the primary endpoint"
  type        = string
  default     = "203.0.113.1"
}

variable "secondary_endpoint_ip" {
  description = "IP address of the secondary endpoint"
  type        = string
  default     = "203.0.113.2"
}

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = {
    Environment = "primary-health-check-test"
  }
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = aws_route53_zone.primary.name
  port              = 443
  type              = "HTTPS"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = false

  tags = {
    Environment = "primary-health-check-test"
  }
}

resource "aws_route53_record" "primary_failover" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  set_identifier = "primary"

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.primary_health_check.id

  records = [var.primary_endpoint_ip]
}

resource "aws_route53_record" "secondary_failover" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  set_identifier = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }

  records = [var.secondary_endpoint_ip]
}

variable "domain_name" {
  description = "DNS domain name for the Route 53 hosted zone"
  type        = string
  default     = "example.com"
}

variable "primary_fqdn" {
  description = "FQDN used by the primary health check"
  type        = string
  default     = "primary.example.com"
}

variable "secondary_fqdn" {
  description = "FQDN used by the secondary health check"
  type        = string
  default     = "secondary.example.com"
}

variable "primary_ip_address" {
  description = "IPv4 address of the primary endpoint"
  type        = string
  default     = "203.0.113.10"
}

variable "secondary_ip_address" {
  description = "IPv4 address of the secondary endpoint"
  type        = string
  default     = "203.0.113.20"
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = var.primary_fqdn
  port              = 443
  type              = "HTTPS"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn              = var.secondary_fqdn
  port              = 443
  type              = "HTTPS"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

resource "aws_route53_record" "primary" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = var.domain_name
  type            = "A"
  ttl             = 60
  records         = [var.primary_ip_address]
  set_identifier  = "primary"
  health_check_id = aws_route53_health_check.primary_health_check.id

  weighted_routing_policy {
    weight = 1
  }
}

resource "aws_route53_record" "secondary" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = var.domain_name
  type            = "A"
  ttl             = 60
  records         = [var.secondary_ip_address]
  set_identifier  = "secondary"
  health_check_id = aws_route53_health_check.secondary_health_check.id

  weighted_routing_policy {
    weight = 1
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
  }
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = "foobar"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 80
  alarm_description   = "This metric monitors EC2 CPU utilization"
}

resource "aws_route53_health_check" "foobar" {
  type                            = "CLOUDWATCH_METRIC"
  cloudwatch_alarm_name           = aws_cloudwatch_metric_alarm.foobar.alarm_name
  cloudwatch_alarm_region         = "us-east-1"
  insufficient_data_health_status = "Healthy"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu_central_1"
  region = "eu-central-1"
}

variable "domain_name" {
  description = "Domain name for the Route 53 hosted zone"
  type        = string
  default     = "example.com"
}

data "aws_availability_zones" "us_east_1" {
  provider = aws
  state    = "available"
}

data "aws_availability_zones" "eu_central_1" {
  provider = aws.eu_central_1
  state    = "available"
}

locals {
  azs_us = slice(data.aws_availability_zones.us_east_1.names, 0, 2)
  azs_eu = slice(data.aws_availability_zones.eu_central_1.names, 0, 2)
}

resource "aws_route53_zone" "primary" {
  name = var.domain_name
}

resource "aws_vpc" "us_east_1" {
  cidr_block = "10.0.0.0/16"
  tags = { Name = "us-east-1" }
}

resource "aws_vpc" "eu_central_1" {
  provider   = aws.eu_central_1
  cidr_block = "10.1.0.0/16"
  tags = { Name = "eu-central-1" }
}

resource "aws_internet_gateway" "us_east_1" {
  vpc_id = aws_vpc.us_east_1.id
  tags = { Name = "us-east-1" }
}

resource "aws_internet_gateway" "eu_central_1" {
  provider = aws.eu_central_1
  vpc_id   = aws_vpc.eu_central_1.id
  tags = { Name = "eu-central-1" }
}

resource "aws_route_table" "us_east_1" {
  vpc_id = aws_vpc.us_east_1.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us_east_1.id
  }
  tags = { Name = "us-east-1" }
}

resource "aws_route_table" "eu_central_1" {
  provider = aws.eu_central_1
  vpc_id   = aws_vpc.eu_central_1.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eu_central_1.id
  }
  tags = { Name = "eu-central-1" }
}

resource "aws_subnet" "us_east_1" {
  count             = length(local.azs_us)
  vpc_id            = aws_vpc.us_east_1.id
  cidr_block        = cidrsubnet(aws_vpc.us_east_1.cidr_block, 8, count.index)
  availability_zone = local.azs_us[count.index]
  map_public_ip_on_launch = true
  tags = { Name = "us-east-1-${count.index}" }
}

resource "aws_subnet" "eu_central_1" {
  provider          = aws.eu_central_1
  count             = length(local.azs_eu)
  vpc_id            = aws_vpc.eu_central_1.id
  cidr_block        = cidrsubnet(aws_vpc.eu_central_1.cidr_block, 8, count.index)
  availability_zone = local.azs_eu[count.index]
  map_public_ip_on_launch = true
  tags = { Name = "eu-central-1-${count.index}" }
}

resource "aws_route_table_association" "us_east_1" {
  count          = length(local.azs_us)
  subnet_id      = aws_subnet.us_east_1[count.index].id
  route_table_id = aws_route_table.us_east_1.id
}

resource "aws_route_table_association" "eu_central_1" {
  provider       = aws.eu_central_1
  count          = length(local.azs_eu)
  subnet_id      = aws_subnet.eu_central_1[count.index].id
  route_table_id = aws_route_table.eu_central_1.id
}

resource "aws_security_group" "alb_us_east_1" {
  name        = "alb-sg"
  description = "Allow HTTP and HTTPS inbound for ALB"
  vpc_id      = aws_vpc.us_east_1.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "alb-us-east-1" }
}

resource "aws_security_group" "alb_eu_central_1" {
  provider    = aws.eu_central_1
  name        = "alb-sg"
  description = "Allow HTTP and HTTPS inbound for ALB"
  vpc_id      = aws_vpc.eu_central_1.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "alb-eu-central-1" }
}

resource "aws_security_group" "instance_us_east_1" {
  name        = "instance-sg"
  description = "Allow traffic from ALB to instances"
  vpc_id      = aws_vpc.us_east_1.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_us_east_1.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "instance-us-east-1" }
}

resource "aws_security_group" "instance_eu_central_1" {
  provider    = aws.eu_central_1
  name        = "instance-sg"
  description = "Allow traffic from ALB to instances"
  vpc_id      = aws_vpc.eu_central_1.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_eu_central_1.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = { Name = "instance-eu-central-1" }
}

data "aws_ami" "amazon_linux_2_us_east_1" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

data "aws_ami" "amazon_linux_2_eu_central_1" {
  provider    = aws.eu_central_1
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "us_east_1" {
  ami                    = data.aws_ami.amazon_linux_2_us_east_1.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.us_east_1[0].id
  vpc_security_group_ids = [aws_security_group.instance_us_east_1.id]
  user_data              = <<-EOF
#!/bin/bash
yum update -y
yum install -y httpd
systemctl start httpd
systemctl enable httpd
echo "Hello from us-east-1" > /var/www/html/index.html
EOF
  tags = { Name = "web-us-east-1" }
}

resource "aws_instance" "eu_central_1" {
  provider               = aws.eu_central_1
  ami                    = data.aws_ami.amazon_linux_2_eu_central_1.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.eu_central_1[0].id
  vpc_security_group_ids = [aws_security_group.instance_eu_central_1.id]
  user_data              = <<-EOF
#!/bin/bash
yum update -y
yum install -y httpd
systemctl start httpd
systemctl enable httpd
echo "Hello from eu-central-1" > /var/www/html/index.html
EOF
  tags = { Name = "web-eu-central-1" }
}

resource "aws_lb" "us_east_1" {
  name               = "alb-us-east-1"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_us_east_1.id]
  subnets            = aws_subnet.us_east_1[*].id
  tags = { Name = "alb-us-east-1" }
}

resource "aws_lb" "eu_central_1" {
  provider           = aws.eu_central_1
  name               = "alb-eu-central-1"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_eu_central_1.id]
  subnets            = aws_subnet.eu_central_1[*].id
  tags = { Name = "alb-eu-central-1" }
}

resource "aws_lb_target_group" "us_east_1" {
  name        = "tg-us-east-1"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.us_east_1.id
  target_type = "instance"

  health_check {
    path = "/"
    port = 80
  }
}

resource "aws_lb_target_group" "eu_central_1" {
  provider    = aws.eu_central_1
  name        = "tg-eu-central-1"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.eu_central_1.id
  target_type = "instance"

  health_check {
    path = "/"
    port = 80
  }
}

resource "aws_lb_target_group_attachment" "us_east_1" {
  target_group_arn = aws_lb_target_group.us_east_1.arn
  target_id        = aws_instance.us_east_1.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "eu_central_1" {
  provider         = aws.eu_central_1
  target_group_arn = aws_lb_target_group.eu_central_1.arn
  target_id        = aws_instance.eu_central_1.id
  port             = 80
}

resource "aws_lb_listener" "us_east_1" {
  load_balancer_arn = aws_lb.us_east_1.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.us_east_1.arn
  }
}

resource "aws_lb_listener" "eu_central_1" {
  provider          = aws.eu_central_1
  load_balancer_arn = aws_lb.eu_central_1.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.eu_central_1.arn
  }
}

resource "aws_route53_health_check" "us_east_1" {
  fqdn              = aws_lb.us_east_1.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 30
  tags = { Name = "hc-us-east-1" }
}

resource "aws_route53_health_check" "eu_central_1" {
  fqdn              = aws_lb.eu_central_1.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 30
  tags = { Name = "hc-eu-central-1" }
}

resource "aws_route53_record" "us_east_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name
  type    = "A"
  set_identifier = "us-east-1"

  latency_routing_policy {
    region = "us-east-1"
  }

  alias {
    name                   = aws_lb.us_east_1.dns_name
    zone_id                = aws_lb.us_east_1.zone_id
    evaluate_target_health = true
  }

  health_check_id = aws_route53_health_check.us_east_1.id
}

resource "aws_route53_record" "eu_central_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name
  type    = "A"
  set_identifier = "eu-central-1"

  latency_routing_policy {
    region = "eu-central-1"
  }

  alias {
    name                   = aws_lb.eu_central_1.dns_name
    zone_id                = aws_lb.eu_central_1.zone_id
    evaluate_target_health = true
  }

  health_check_id = aws_route53_health_check.eu_central_1.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80, != 5.100.0"
    }
  }
}

variable "primary_domain_name" {
  description = "The domain name for the Route53 hosted zone"
  type        = string
  default     = "example.com"
}

resource "aws_route53_zone" "primary" {
  name = var.primary_domain_name

  tags = {
    Name = "primary"
  }
}

resource "aws_eip" "us" {
  domain = "vpc"

  tags = {
    Name = "us-endpoint"
  }
}

resource "aws_eip" "eu" {
  domain = "vpc"

  tags = {
    Name = "eu-endpoint"
  }
}

resource "aws_eip" "default" {
  domain = "vpc"

  tags = {
    Name = "default-endpoint"
  }
}

resource "aws_route53_record" "us" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 300

  set_identifier = "us-record"

  geolocation_routing_policy {
    country = "US"
  }

  records = [aws_eip.us.public_ip]
}

resource "aws_route53_record" "eu" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 300

  set_identifier = "eu-record"

  geolocation_routing_policy {
    continent = "EU"
  }

  records = [aws_eip.eu.public_ip]
}

resource "aws_route53_record" "default" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 300

  set_identifier = "default-record"

  geolocation_routing_policy {
    country = "*"
  }

  records = [aws_eip.default.public_ip]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

variable "domain_name" {
  description = "The domain name for the Route53 hosted zone"
  type        = string
  default     = "example.com"
}

locals {
  traffic_policy_document = jsonencode({
    AWSPolicyFormatVersion = "2015-10-01"
    RecordType             = "A"
    Endpoints = [
      {
        Type  = "value"
        Id    = "endpoint-1"
        Value = "203.0.113.1"
      }
    ]
    StartEndpoint = "endpoint-1"
  })
}

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_traffic_policy" "example" {
  name     = "example-policy"
  document = local.traffic_policy_document
  comment  = "Simple A record traffic policy"
}

resource "aws_route53_traffic_policy_instance" "example" {
  hosted_zone_id         = aws_route53_zone.main.id
  name                   = "www"
  traffic_policy_id      = aws_route53_traffic_policy.example.id
  traffic_policy_version = aws_route53_traffic_policy.example.version
  ttl                    = 60
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-eks-cluster"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                              = "${var.cluster_name}-public-${count.index}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                   = "1"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                              = "${var.cluster_name}-private-${count.index}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"           = "1"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {    Name = "${var.cluster_name}-nat-eip"  }}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
