  description = "Allowed HTTP Referer header value for S3 object access"
  type        = string
  default     = "https://example.com"
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGetObjectFromReferer"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringLike = {
            "aws:Referer" = var.allowed_referer
          }
        }
      }
    ]
  })
}

