locals {
  topic_name = "s3-event-notification-topic"
}

# SNS Topic
resource "aws_sns_topic" "s3_event_notification_topic" {
  name = local.topic_name
}

# IAM Policy Document for SNS topic to allow S3 service to publish
data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    actions = ["SNS:Publish"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    resources = [aws_sns_topic.s3_event_notification_topic.arn]
    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.log_bucket.arn]
    }
  }
}

# Attach policy to SNS topic
resource "aws_sns_topic_policy" "s3_event_notification_topic" {
  arn    = aws_sns_topic.s3_event_notification_topic.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# S3 Bucket with versioning, encryption, and public access block
resource "aws_s3_bucket" "log_bucket" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# S3 Bucket Notification to SNS topic for object created events with .log suffix
resource "aws_s3_bucket_notification" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  topic {
    topic_arn     = aws_sns_topic.s3_event_notification_topic.arn
    events        = ["s3:ObjectCreated:*"]
    filter_suffix = ".log"
  }

  depends_on = [
    aws_sns_topic_policy.s3_event_notification_topic,
    aws_s3_bucket.log_bucket
  ]
}

