# Variables to allow user customization
variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "your_bucket_name"
}

variable "object_key" {
  description = "Key (path) for the S3 object"
  type        = string
  default     = "new_object_key"
}

variable "source_file_path" {
  description = "Local path to the source file to be uploaded"
  type        = string
  default     = "path/to/file"
}

# S3 bucket resource
resource "aws_s3_bucket" "main" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable default SSE-S3 encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Local file to ensure the source file exists (self-contained)
resource "local_file" "source" {
  filename        = var.source_file_path
  content         = "placeholder content"
  file_permission = "0644"
}

# S3 object (modern resource)
resource "aws_s3_object" "main" {
  bucket = aws_s3_bucket.main.id
  key    = var.object_key
  source = local_file.source.filename
  etag   = filemd5(local_file.source.filename)
}

