# Generate a secure password for the ElastiCache user – never hardcoded
resource "random_password" "app_user" {
  length           = 32
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

# ElastiCache user – stateful identity, therefore prevent_destroy
resource "aws_elasticache_user" "app_user" {
  user_id       = "appuser"
  user_name     = "appuser"
  access_string = "on ~* +@all"
  engine        = "REDIS"

  authentication_mode {
    type      = "password"
    passwords = [random_password.app_user.result]
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache user group – stateful group, therefore prevent_destroy
resource "aws_elasticache_user_group" "app_group" {
  user_group_id = "appgroup"
  engine        = "REDIS"

  lifecycle {
    prevent_destroy = true
  }
}

# Association linking the user to the user group
resource "aws_elasticache_user_group_association" "app" {
  user_group_id = aws_elasticache_user_group.app_group.user_group_id
  user_id       = aws_elasticache_user.app_user.user_id
}

