locals {
  prefix = "redshift"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  # for public subnet
  availability_zone       = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "${local.prefix}-public-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "${local.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "redshift" {
  name        = "${local.prefix}-sg"
  description = "Secrurity group for Redshift clister"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.prefix}-sg"
  }
}

resource "aws_redshift_subnet_group" "redshift" {
  name        = "${local.prefix}-subnet-group"
  subnet_ids   = [aws_subnet.public.id]
  tags = {
    Name = "${local.prefix}-subnet-group"
  }
}

resource "random_password" "master" {
  length  = 16
  special = false
}

resource "aws_secretsmanager_secret" "master" {
  name        = "${local.prefix}-master-password"
  description = "Master password for Redshift clister"
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id     = aws_secretsmanager_secret.master.id
  secret_string = random_password.master.result
}

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift clister encryption"
  key_usage              = "ENCRYPT_DECRYPT"
  enable_key_rotation    = true
  tags = {
    Name = "${local.prefix}-kms"
  }
}

resource "aws_iam_role" "redshift" {
  name = "${local.prefix}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "stm:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "${local.prefix}-role"
  }
}

# No policy attached – default deny (least privilege)

resource "aws_redshift_parameter_group" "redshift" {
  name        = "${local.prefix}-param-group"
  family      = "redshift-1.0"  # adjust if newer family is needed
  description = "Parameter group for Redshift clister"
  parameter {
    name  = "concurrency_scaling_limit"
    value = "60"
  }
  tags = {
    Name = "${local.prefix}-param-group"
  }
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "${local.prefix}-clister"
  node_type                 = "dc2.large"  # adjust as needed
  number_of_nodes          = 2
  master_username          = "admin"
  master_password          = random_password.master.result
  encrypted                = true
  kms_key_id               = aws_kms_key.redshift.arn
  iam_roles                = [aws_iam_role.redshift.arn]
  cluster_parameter_group_name = aws_redshift_parameter_group.redshift.name
  cluster_subnet_group_name    = aws_redshift_subnet_group.redshift.name
  vpc_security_group_ids      = [aws_security_group.redshift.id]
  publicly_accessible         = true
  skip_final_snapshot         = false
  final_snapshot_identifier   = "${local.prefix}-final-snapshot-${formatdate("YYYYMMDDhhmmss", timestamp())}"

  tags = {
    Name = "${local.prefix}-clister"
  }

  lifecycle {
    prevent_destroy = true
  }
}

