  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Private subnets in each AZ
resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-private-b"
  })
}

# Route tables for private subnets
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-private"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# VPC Gateway Endpoint for S3
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-endpoint"
  })
}

# Redshift subnet group
resource "aws_redshift_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

# Security group for Redshift
resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# IAM role for Redshift to access S3
resource "aws_iam_role" "redshift_s3" {
  name = "${local.name_prefix}-redshift-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "redshift_s3_readonly" {
  role       = aws_iam_role.redshift_s3.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# KMS key for Redshift encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

# Random password for master user
resource "random_password" "master_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store master password in Secrets Manager
resource "aws_secretsmanager_secret" "redshift_master_password" {
  name = "${local.name_prefix}-master-password"

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = jsonencode({
    username = "admin"
    password = random_password.master_password.result
  })
}

# Redshift cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  database_name             = "mydb"
  master_username           = "admin"
  master_password           = random_password.master_password.result
  node_type                 = "dc2.large"
  cluster_type              = "multi-node"
  number_of_nodes           = 2
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids   = [aws_security_group.redshift.id]
  iam_roles                 = [aws_iam_role.redshift_s3.arn]
  encrypted                 = true
  kms_key_id                = aws_kms_key.redshift.arn
  publicly_accessible       = false
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

# Data source for current region (used in VPC endpoint)
data "aws_region" "current" {}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.95.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  alias  = "us_east_2"
  region = "us-east-2"
}

# ---------------------------------------------------------------------------
# Data sources (static lookups only)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Networking (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "redshift" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "redshift-subnet-${count.index}"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.redshift[*].id
  tags = {
    Name = "redshift-subnet-group"
  }
}

resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# ---------------------------------------------------------------------------
# KMS Keys
# ---------------------------------------------------------------------------
resource "aws_kms_key" "us_east_1" {
  description             = "KMS key for Redshift cluster in us-east-1"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "us_east_2" {
  provider                = aws.us_east_2
  description             = "KMS key for cross-region snapshot copy in us-east-2"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Secrets Manager – Master Password
# ---------------------------------------------------------------------------
resource "random_password" "redshift_master" {
  length           = 16
  special          = false
  override_special = ""
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name                    = "redshift-master-password"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    password = random_password.redshift_master.result
  })
}

# ---------------------------------------------------------------------------
# IAM Role for Cross-Region Snapshot Copy
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "redshift_copy" {
  statement {
    sid    = "AllowKMSDecryptInUsEast1"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:CreateGrant",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.us_east_1.arn]
  }

  statement {
    sid    = "AllowKMSDecryptInUsEast2"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:CreateGrant",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.us_east_2.arn]
  }
}

resource "aws_iam_role" "redshift_copy" {
  name               = "redshift-cross-region-copy-role"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json
}

resource "aws_iam_policy" "redshift_copy" {
  name   = "redshift-cross-region-copy-policy"
  policy = data.aws_iam_policy_document.redshift_copy.json
}

resource "aws_iam_role_policy_attachment" "redshift_copy" {
  role       = aws_iam_role.redshift_copy.name
  policy_arn = aws_iam_policy.redshift_copy.arn
}

# ---------------------------------------------------------------------------
# Snapshot Copy Grant (us-east-2)
# ---------------------------------------------------------------------------
resource "aws_redshift_snapshot_copy_grant" "us_east_2" {
  provider                 = aws.us_east_2
  snapshot_copy_grant_name = "redshift-copy-grant-us-east-2"
  kms_key_id               = aws_kms_key.us_east_2.arn
}

# ---------------------------------------------------------------------------
# Redshift Cluster (us-east-1)
# ---------------------------------------------------------------------------
resource "random_id" "final_snapshot" {
  byte_length = 4
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = "redshift-cluster-primary"
  node_type                           = "dc2.large"
  number_of_nodes                     = 2
  master_username                     = "admin"
  master_password                     = jsondecode(aws_secretsmanager_secret_version.redshift_master.secret_string)["password"]
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  encrypted                           = true
  kms_key_id                          = aws_kms_key.us_east_1.arn
  automated_snapshot_retention_period = 7
  publicly_accessible                 = false
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "redshift-final-${random_id.final_snapshot.hex}"
  iam_roles                           = [aws_iam_role.redshift_copy.arn]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-cluster-primary"
  }
}

# ---------------------------------------------------------------------------
# Cross-Region Snapshot Copy Configuration
# ---------------------------------------------------------------------------
resource "aws_redshift_snapshot_copy" "main" {
  cluster_identifier       = aws_redshift_cluster.main.cluster_identifier
  destination_region       = "us-east-2"
  snapshot_copy_grant_name = aws_redshift_snapshot_copy_grant.us_east_2.snapshot_copy_grant_name
}

resource "random_password" "master_password" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name = "redshift-master-password"
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master_password.result
}

resource "aws_iam_role" "redshift_assume_role" {
  name = "redshift_assume_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "redshift-private-${count.index + 1}"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-cluster"
  node_type          = "dc2.large"
  number_of_nodes    = 1
  master_username    = "admin"
  master_password    = random_password.master_password.result
  encrypted          = true
  skip_final_snapshot = true

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift_sg.id]

  iam_roles = [aws_iam_role.redshift_assume_role.arn]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.80.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "= 3.0.0"
    }
  }
}

locals {
  common_tags = {
    Environment = "dev"
    ManagedBy   = "Terraform"
    Project     = "redshift-cluster"
  }
  vpc_cidr = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "random_password" "master_password" {
  length  = 16
  special = true
  # Exclude ambiguous characters to avoid issues
  override_special = "!@#$%^&*()_+-=[]{}|;':\",./<>?`~"
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "redshift-vpc"
  })
}

# Private subnets in two AZs
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 1)  # 10.0.1.0/24, 10.0.2.0/24
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, {
    Name = "redshift-private-${count.index + 1}"
  })
}

# Redshift subnet group
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.common_tags
}

# Security group
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id
  tags        = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "redshift_inbound" {
  security_group_id = aws_security_group.redshift.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 5439
  to_port           = 5439
  ip_protocol       = "tcp"
  description       = "Allow Redshift access from VPC"
}

resource "aws_vpc_security_group_egress_rule" "redshift_outbound" {
  security_group_id = aws_security_group.redshift.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
  description       = "Allow all outbound traffic"
}

# IAM role for Redshift
resource "aws_iam_role" "redshift" {
  name = "redshift-s3-readonly-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "redshift_s3_readonly" {
  name = "redshift-s3-readonly-policy"
  role = aws_iam_role.redshift.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:Get*",
          "s3:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Secrets Manager secret for master password
resource "aws_secretsmanager_secret" "redshift_master_password" {
  name = "redshift-master-password"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master_password.result
}

# Redshift cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "redshift-cluster"
  database_name             = "dev"
  master_username           = "admin"
  master_password           = random_password.master_password.result
  node_type                 = "dc2.large"
  number_of_nodes           = 2
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  iam_roles                 = [aws_iam_role.redshift.arn]
  publicly_accessible       = false
  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-final-snapshot"
  tags                      = local.common_tags
}

# Redshift resource policy
data "aws_iam_policy_document" "redshift_resource_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.account_id]
    }
    actions = [
      "redshift:DescribeClusters",
      "redshift:ModifyCluster"
    ]
    resources = [aws_redshift_cluster.main.arn]
  }
}

resource "aws_redshift_resource_policy" "main" {
  resource_arn = aws_redshift_cluster.main.cluster_namespace_arn
  policy       = data.aws_iam_policy_document.redshift_resource_policy.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "redshift-vpc"
  }
}

# Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Private Subnets
resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "redshift-private-subnet-${count.index + 1}"
  }
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "redshift-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Redshift Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = {
    Name = "redshift-subnet-group"
  }
}

# Security Group for Redshift Cluster
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# KMS Key for Redshift Encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift Service"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Random Password for Redshift Master
resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!@#$%^&*()-_=+[]{}|;:,.<>?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

# Secrets Manager Secret for Master Password
resource "aws_secretsmanager_secret" "master_password" {
  name = "redshift-master-password"
  tags = {
    Name = "redshift-master-password"
  }
}

resource "aws_secretsmanager_secret_version" "master_password" {
  secret_id     = aws_secretsmanager_secret.master_password.id
  secret_string = random_password.master.result
}

# IAM Role for Redshift
resource "aws_iam_role" "redshift" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Minimal IAM Policy for Redshift (placeholder - adjust as needed)
resource "aws_iam_policy" "redshift_minimal" {
  name        = "redshift-minimal-policy"
  description = "Minimal policy for Redshift cluster operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "redshift:DescribeClusters"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift" {
  role       = aws_iam_role.redshift.name
  policy_arn = aws_iam_policy.redshift_minimal.arn
}

# Random ID for Final Snapshot
resource "random_id" "final_snapshot" {
  byte_length = 4
}

# Redshift Cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "redshift-cluster"
  cluster_type              = "multi-node"
  number_of_nodes           = 2
  node_type                 = "ra3.xlplus"
  database_name             = "dev"
  master_username           = "awsuser"
  master_password           = random_password.master.result
  encrypted                 = true
  kms_key_id                = aws_kms_key.redshift.arn
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  iam_roles                 = [aws_iam_role.redshift.arn]
  port                      = 5439
  publicly_accessible       = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot       = false
  final_snapshot_identifier  = "redshift-final-snapshot-${random_id.final_snapshot.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-cluster"
  }
}

# VPC Endpoint Service for Redshift
data "aws_vpc_endpoint_service" "redshift" {
  service = "redshift"
}

# Security Group for VPC Endpoint
resource "aws_security_group" "endpoint" {
  name        = "redshift-endpoint-sg"
  description = "Security group for Redshift VPC endpoint"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "redshift-endpoint-sg"
  }
}

# VPC Endpoint for Redshift (Interface)
resource "aws_vpc_endpoint" "redshift" {
  vpc_id              = aws_vpc.main.id
  service_name        = data.aws_vpc_endpoint_service.redshift.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoint.id]
  private_dns_enabled = true

  tags = {
    Name = "redshift-endpoint"
  }
}

