locals {
  region      = "us-east-1"
  function_name = "dynamodb-stream-processor"
  handler_code = <<-EOT
import json
import base64

def lambda_handler(event, context):
    for record in event['Records']:
        print(f"Received record: {json.dumps(record)}")
        dynamodb_record = record.get('dynamodb', {})
        event_name = record.get('eventName', 'UNKNOWN')
        keys = dynamodb_record.get('Keys', {})
        new_image = dynamodb_record.get('NewImage', {})
        old_image = dynamodb_record.get('OldImage', {})
        print(f"Event: {event_name}, Keys: {keys}, NewImage: {new_image}, OldImage: {old_image}")
    return {'statusCode': 200}
EOT
}

# DynamoDB table with stream enabled
resource "aws_dynamodb_table" "this" {
  name         = "StreamTable"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  lifecycle {
    prevent_destroy = true
  }
}

