}

# Custom policy for DynamoDB Stream actions
resource "aws_iam_policy" "dynamodb_stream" {
  name        = "lambda-dynamodb-stream-policy"
  description = "Allow Lambda to read from DynamoDB Stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:DescribeStream",
          "dynamodb:ListStreams"
        ]
        Resource = aws_dynamodb_table.this.stream_arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dynamodb_stream" {
  role       = aws_iam_role.lambda.name
  policy_arn = aws_iam_policy.dynamodb_stream.arn
}

