resource "aws_cloudwatch_metric_alarm" "alpha" {
  alarm_name          = "alarm-alpha"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 80
  alarm_description   = "Example metric alarm alpha"
}

resource "aws_cloudwatch_metric_alarm" "beta" {
  alarm_name          = "alarm-beta"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 90
  alarm_description   = "Example metric alarm beta"
}

resource "aws_cloudwatch_composite_alarm" "main" {
  alarm_name        = "composite_alarm_example"
  alarm_rule        = "ALARM(\"${aws_cloudwatch_metric_alarm.alpha.alarm_name}\") OR ALARM(\"${aws_cloudwatch_metric_alarm.beta.alarm_name}\")"
  alarm_description = "Composite alarm triggered when either alpha or beta is in ALARM state"
}

