terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

variable "table_name" {
  description = "Name of the DynamoDB table"
  type        = string
  default     = "my-table"
}

variable "stream_name" {
  description = "Name of the Kinesis data stream"
  type        = string
  default     = "my-stream"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

locals {
  common_tags = var.tags
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Allow DynamoDB to use the key for Kinesis streaming"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["dynamodb.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Allow Kinesis to use the key for stream encryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["kinesis.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Allow root account access to manage key"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow DynamoDB Kinesis role to use the key"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.dynamodb_kinesis.arn]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "main" {
  description             = "KMS key for Kinesis stream encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name           = var.table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  stream_enabled = false

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream" "main" {
  name             = var.stream_name
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = aws_kms_key.main.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "dynamodb_kinesis" {
  name = "dynamodb-kinesis-streaming-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

data "aws_iam_policy_document" "kinesis_put_policy" {
  statement {
    effect = "Allow"
    actions = [
      "kinesis:PutRecord",
      "kinesis:PutRecords"
    ]
    resources = [aws_kinesis_stream.main.arn]
  }
}

resource "aws_iam_policy" "kinesis_put" {
  name   = "dynamodb-kinesis-put-policy"
  policy = data.aws_iam_policy_document.kinesis_put_policy.json
}

resource "aws_iam_role_policy_attachment" "kinesis_put" {
  role       = aws_iam_role.dynamodb_kinesis.name
  policy_arn = aws_iam_policy.kinesis_put.arn
}

resource "aws_dynamodb_kinesis_streaming_destination" "main" {
  table_name                        = aws_dynamodb_table.main.name
  stream_arn                        = aws_kinesis_stream.main.arn
  approximate_creation_date_time_precision = "MICROSECOND"
}

