  description = "Security group for SageMaker Domain"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.environment_name}-sagemaker-sg"
  })
}

resource "aws_iam_role" "sagemaker_execution" {
  name_prefix = "${var.environment_name}-sagemaker-execution-"
  description = "SageMaker execution role for the domain"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "sagemaker_execution" {
  name_prefix = "${var.environment_name}-sagemaker-execution-policy-"
  description = "Least-privilege policy for SageMaker domain execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerActions"
        Effect = "Allow"
        Action = [
          "sagemaker:CreateApp",
          "sagemaker:DescribeDomain",
          "sagemaker:ListApps"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.sagemaker_artifacts.arn
      },
      {
        Sid    = "S3ObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.sagemaker_artifacts.arn}/*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.sagemaker.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_execution" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_execution.arn
}

resource "aws_kms_key" "sagemaker" {
  description             = "KMS key for SageMaker Domain encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SageMaker Service"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Execution Role"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.sagemaker_execution.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/${var.environment_name}-sagemaker-key"
  target_key_id = aws_kms_key.sagemaker.key_id
}

resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket_prefix = "${var.environment_name}-artifacts-"
  force_destroy = false

  tags = merge(var.tags, {
    Name = "${var.environment_name}-sagemaker-artifacts"
  })
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_sagemaker_domain" "main" {
  domain_name = var.environment_name
  auth_mode   = "IAM"
  vpc_id      = aws_vpc.main.id
  subnet_ids  = aws_subnet.private[*].id
  kms_key_id  = aws_kms_key.sagemaker.arn

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

data "aws_caller_identity" "current" {}

