locals {
  name_prefix = "sagemaker-demo"
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24"]
  common_tags = {
    Environment = "sagemaker-demo"
    ManagedBy   = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_id" "suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "sagemaker" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

# ------------------------------------------------------------------------------
# Public Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "sagemaker" {
  count = 2

  vpc_id                  = aws_vpc.sagemaker.id
  cidr_block              = local.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-${count.index}" })
}

# ------------------------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "sagemaker" {
  vpc_id = aws_vpc.sagemaker.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# ------------------------------------------------------------------------------
# Route Table and Associations
# ------------------------------------------------------------------------------
resource "aws_route_table" "sagemaker" {
  vpc_id = aws_vpc.sagemaker.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.sagemaker.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rtb" })
}

resource "aws_route_table_association" "sagemaker" {
  count = 2

  subnet_id      = aws_subnet.sagemaker[count.index].id
  route_table_id = aws_route_table.sagemaker.id
}

# ------------------------------------------------------------------------------
# Security Group for SageMaker Studio
# ------------------------------------------------------------------------------
resource "aws_security_group" "sagemaker_studio" {
  name        = "${local.name_prefix}-studio-sg"
  description = "Security group for SageMaker Studio"
  vpc_id      = aws_vpc.sagemaker.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.sagemaker.cidr_block]
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-studio-sg" })
}

# ------------------------------------------------------------------------------
# IAM Role and Policies
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name               = "${local.name_prefix}-execution-role"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "sagemaker_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.sagemaker_artifacts.arn,
      "${aws_s3_bucket.sagemaker_artifacts.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "sagemaker:DescribeDomain",
      "sagemaker:DescribeUserProfile",
      "sagemaker:DescribeSpace",
      "sagemaker:ListDomains",
      "sagemaker:ListUserProfiles",
      "sagemaker:ListSpaces",
      "sagemaker:CreatePresignedDomainUrl",
      "sagemaker:CreateApp",
      "sagemaker:DeleteApp",
      "sagemaker:DescribeApp",
      "sagemaker:ListApps",
      "sagemaker:AddTags",
      "sagemaker:ListTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "sagemaker_execution" {
  name        = "${local.name_prefix}-execution-policy"
  description = "Least-privilege policy for SageMaker execution role"
  policy      = data.aws_iam_policy_document.sagemaker_permissions.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_execution" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_execution.arn
}

# ------------------------------------------------------------------------------
# S3 Bucket for SageMaker Artifacts
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket = "sagemaker-artifacts-${random_id.suffix.hex}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# SageMaker Domain
# ------------------------------------------------------------------------------
resource "aws_sagemaker_domain" "main" {
  domain_name = "${local.name_prefix}-domain"
  auth_mode   = "IAM"
  vpc_id      = aws_vpc.sagemaker.id
  subnet_ids  = aws_subnet.sagemaker[*].id

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# SageMaker User Profile
# ------------------------------------------------------------------------------
resource "aws_sagemaker_user_profile" "main" {
  domain_id         = aws_sagemaker_domain.main.id
  user_profile_name = "${local.name_prefix}-user"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# SageMaker Space
# ------------------------------------------------------------------------------
resource "aws_sagemaker_space" "main" {
  domain_id  = aws_sagemaker_domain.main.id
  space_name = "${local.name_prefix}-space"

  ownership_settings {
    owner_user_profile_name = aws_sagemaker_user_profile.main.user_profile_name
  }

  space_sharing_settings {
    sharing_type = "Private"
  }

  space_settings {
    app_type = "JupyterLab"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

