provider "aws" {
  region = "us-east-1"
}

variable "code_repository_name" {
  description = "Name for the SageMaker Code Repository"
  type        = string
  default     = "terraform-provider-aws"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "dev"
}

resource "aws_sagemaker_code_repository" "main" {
  code_repository_name = var.code_repository_name

  git_config {
    repository_url = "https://github.com/hashicorp/terraform-provider-aws.git"
    branch         = "main"
  }

  tags = {
    Environment = var.environment
  }
}

variable "sagemaker_image_name" {
  description = "Name of the SageMaker image"
  type        = string
  default     = "my-sagemaker-image"
}

resource "aws_iam_role" "sagemaker_image" {
  name = "sagemaker-image-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_image_ecr" {
  name        = "sagemaker-image-ecr-policy"
  description = "Least-privilege policy for SageMaker to pull container images from ECR"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetAuthorizationToken"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_image" {
  role       = aws_iam_role.sagemaker_image.name
  policy_arn = aws_iam_policy.sagemaker_image_ecr.arn
}

resource "aws_sagemaker_image" "this" {
  image_name  = var.sagemaker_image_name
  role_arn    = aws_iam_role.sagemaker_image.arn

  lifecycle {
    prevent_destroy = true
  }
}

