resource "aws_iam_role" "sagemaker_exec" {
  name = "sagemaker-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "sagemaker_policy" {
  name = "sagemaker-exec-policy"
  role = aws_iam_role.sagemaker_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.model_artifacts.id}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = "ecr:GetDownloadUrlForLayer"
        Resource = "arn:aws:ecr:${data.aws_region.current.name}:${data.aws_sagemaker_prebuilt_ecr_image.kmeans.registry_id}:repository/kmeans"
      }
    ]
  })
}

resource "aws_sagemaker_model" "kmeans" {
  name             = "kmeans-model"
  execution_role_arn = aws_iam_role.sagemaker_exec.arn

  primary_container {
    image          = data.aws_sagemaker_prebuilt_ecr_image.kmeans.registry_path
    model_data_url = "s3://${aws_s3_bucket.model_artifacts.id}/${aws_s3_object.model_artifact.key}"
  }
}

terraform {
