locals {
  common_tags = {
    Environment = "dev"
  }
  name_prefix = "sagemaker-notebook"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "sagemaker" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for SageMaker notebook instance"
  vpc_id      = aws_vpc.main.id

  # No inbound rules
  ingress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    cidr_blocks     = []
    description     = "No inbound traffic allowed"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_iam_role" "sagemaker" {
  name = "${local.name_prefix}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "sagemaker_custom" {
  name        = "${local.name_prefix}-policy"
  description = "Least-privilege policy for SageMaker notebook instance"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerPermissions"
        Effect = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:DescribeNotebookInstance",
          "sagemaker:ListTags",
          "sagemaker:AddTags",
          "sagemaker:DeleteTags"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:sagemaker:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:notebook-instance/*"
      },
      {
        Sid    = "CloudWatchLogsPermissions"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"
      },
      {
        Sid    = "KMSPermissions"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.notebook.arn
      },
      {
        Sid    = "S3Permissions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::aws-glue-*",
          "arn:${data.aws_partition.current.partition}:s3:::sagemaker-*",
          "arn:${data.aws_partition.current.partition}:s3:::${data.aws_region.current.name}-${data.aws_caller_identity.current.account_id}-*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_custom" {
  role       = aws_iam_role.sagemaker.name
  policy_arn = aws_iam_policy.sagemaker_custom.arn
}

resource "aws_kms_key" "notebook" {
  description             = "KMS key for SageMaker notebook EBS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "notebook" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.notebook.key_id
}

resource "aws_sagemaker_notebook_instance" "main" {
  name                   = "${local.name_prefix}-instance"
  role_arn               = aws_iam_role.sagemaker.arn
  instance_type          = "ml.t2.medium"
  subnet_id              = aws_subnet.public[0].id
  security_groups        = [aws_security_group.sagemaker.id]
  kms_key_id             = aws_kms_key.notebook.arn
  direct_internet_access = "Enabled"
  platform_identifier    = "notebook-al2-v2"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# main.tf

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.17.0"
    }
  }
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Local values
locals {
  bucket_name           = "sagemaker-artifacts-${data.aws_caller_identity.current.account_id}"
  pipeline_name         = "my-pipeline"
  pipeline_display_name = "my-xgboost-pipeline"
  region                = data.aws_region.current.name
  account_id            = data.aws_caller_identity.current.account_id
  bucket_arn            = "arn:aws:s3:::${local.bucket_name}"
  log_group_arn_prefix  = "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws/sagemaker/*"
}

# Data source for prebuilt XGBoost image (specific version)
data "aws_sagemaker_prebuilt_ecr_image" "xgboost" {
  repository_name = "sagemaker-xgboost"
  image_tag       = "1.0-1"
}

# S3 bucket for artifacts
resource "aws_s3_bucket" "artifacts" {
  bucket = local.bucket_name
  tags = {
    Name        = "SageMaker Artifacts"
    Environment = "dev"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role for pipeline management
resource "aws_iam_role" "pipeline_management" {
  name               = "sagemaker-pipeline-management-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Environment = "dev"
  }
}

resource "aws_iam_policy" "pipeline_management" {
  name        = "sagemaker-pipeline-management-policy"
  description = "Minimal permissions for SageMaker pipeline management"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sagemaker:CreatePipeline",
          "sagemaker:UpdatePipeline",
          "sagemaker:DescribePipeline",
          "sagemaker:DeletePipeline",
          "sagemaker:ListPipelines"
        ]
        Resource = "arn:aws:sagemaker:${local.region}:${local.account_id}:pipeline/*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.step_execution.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          local.bucket_arn,
          "${local.bucket_arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "pipeline_management" {
  role       = aws_iam_role.pipeline_management.name
  policy_arn = aws_iam_policy.pipeline_management.arn
}

# IAM role for step execution
resource "aws_iam_role" "step_execution" {
  name               = "sagemaker-step-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Environment = "dev"
  }
}

resource "aws_iam_policy" "step_execution" {
  name        = "sagemaker-step-execution-policy"
  description = "Minimal permissions for SageMaker pipeline steps"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sagemaker:CreateTrainingJob",
          "sagemaker:CreateProcessingJob",
          "sagemaker:DescribeTrainingJob",
          "sagemaker:DescribeProcessingJob"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          local.bucket_arn,
          "${local.bucket_arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.log_group_arn_prefix
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_execution" {
  role       = aws_iam_role.step_execution.name
  policy_arn = aws_iam_policy.step_execution.arn
}

# Pipeline definition
locals {
  pipeline_definition = {
    Version = "2020-12-01"
    Metadata = {}
    PipelineExperimentConfig = {
      ExperimentName = "my-experiment"
      TrialName      = "my-trial"
    }
    Steps = [
      {
        Name         = "XGBoostTraining"
        Type         = "Training"
        Description  = "Train XGBoost model"
        Arguments = {
          AlgorithmSpecification = {
            TrainingImage     = data.aws_sagemaker_prebuilt_ecr_image.xgboost.registry_path
            TrainingInputMode = "File"
          }
          InputDataConfig = [
            {
              ChannelName = "train"
              DataSource = {
                S3DataSource = {
                  S3DataType = "S3Prefix"
                  S3Uri      = "s3://${local.bucket_name}/input/train"
                  S3DataDistributionType = "FullyReplicated"
                }
              }
              ContentType = "text/csv"
            }
          ]
          OutputDataConfig = {
            S3OutputPath = "s3://${local.bucket_name}/output"
          }
          ResourceConfig = {
            InstanceType  = "ml.m5.large"
            InstanceCount = 1
            VolumeSizeInGB = 30
          }
          StoppingCondition = {
            MaxRuntimeInSeconds = 86400
          }
          RoleArn = aws_iam_role.step_execution.arn
        }
      }
    ]
  }
}

# SageMaker Pipeline resource
resource "aws_sagemaker_pipeline" "main" {
  pipeline_name        = local.pipeline_name
  pipeline_display_name = local.pipeline_display_name
  role_arn             = aws_iam_role.pipeline_management.arn
  pipeline_definition  = jsonencode(local.pipeline_definition)
  tags = {
    Environment = "dev"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.20.0"
    }
  }
}

variable "human_task_ui_name" {
  description = "Name for the SageMaker Human Task UI"
  type        = string
  default     = "test-human-task-ui"
}

locals {
  common_tags = {
    Environment = "dev"
    Project     = "sagemaker-demo"
  }
}

resource "aws_sagemaker_human_task_ui" "test_ui" {
  human_task_ui_name = var.human_task_ui_name

  ui_template {
    content = <<-HTML
    <h1>TEST</h1>
    HTML
  }

  tags = local.common_tags
}

locals {
  common_tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
  bucket_name = "sagemaker-model-artifacts-${data.aws_caller_identity.current.account_id}"
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "model_artifacts" {
  bucket        = local.bucket_name
  force_destroy = false

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
  bucket                  = aws_s3_bucket.model_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    id     = "prevent-destroy"
    status = "Enabled"
    filter {
      prefix = ""
    }
    noncurrent_version_expiration {
      noncurrent_days = 1
    }
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name = "sagemaker-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "sagemaker_execution" {
  name = "sagemaker-execution-policy"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.model_artifacts.arn,
          "${aws_s3_bucket.model_artifacts.arn}/*"
        ]
      }
    ]
  })
}

data "aws_sagemaker_prebuilt_ecr_image" "scikit_learn" {
  repository_name = "sagemaker-scikit-learn"
  image_tag       = "latest"
}

resource "aws_sagemaker_model" "main" {
  name               = "sagemaker-model-${data.aws_caller_identity.current.account_id}"
  execution_role_arn = aws_iam_role.sagemaker_execution.arn

  primary_container {
    image          = data.aws_sagemaker_prebuilt_ecr_image.scikit_learn.registry_path
    model_data_url = "s3://${aws_s3_bucket.model_artifacts.bucket}/model.tar.gz"
  }

  tags = local.common_tags
}

resource "aws_sagemaker_endpoint_configuration" "main" {
  name = "sagemaker-endpoint-config-${data.aws_caller_identity.current.account_id}"

  production_variants {
    variant_name           = "variant-1"
    model_name             = aws_sagemaker_model.main.name
    instance_type          = "ml.t2.medium"
    initial_instance_count = 1
  }

  data_capture_config {
    enable_capture              = true
    initial_sampling_percentage = 100
    destination_s3_uri          = "s3://${aws_s3_bucket.model_artifacts.bucket}/data-capture/"

    capture_options {
      capture_mode = "Input"
    }
    capture_options {
      capture_mode = "Output"
    }
  }

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  model_bucket_name = aws_s3_bucket.model_artifacts.bucket
  model_data_url    = "s3://${local.model_bucket_name}/model.tar.gz"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "sagemaker_execution" {
  statement {
    actions   = ["s3:GetObject"]
    resources = ["arn:aws:s3:::${aws_s3_bucket.model_artifacts.bucket}/*"]
  }
  statement {
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["arn:aws:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"]
  }
}

data "aws_sagemaker_prebuilt_ecr_image" "xgboost" {
  repository_name = "sagemaker-xgboost"
  image_tag       = "latest"
}

resource "aws_s3_bucket" "model_artifacts" {
  bucket = "sagemaker-model-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
