}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "fleet-example"
  }
}

# Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Public subnet (first AZ)
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true
  tags = {
    Name = "fleet-example-public"
  }
}

# Private subnet (second AZ)
resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false
  tags = {
    Name = "fleet-example-private"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "fleet-example"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "fleet-example-public"
  }
}

# Public route table association
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table (no default route)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "fleet-example-private"
  }
}

# Private route table association
resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Security group for EC2 instances
resource "aws_security_group" "ec2" {
  name        = "fleet-example-ec2-sg"
  description = "Allow inbound traffic from VPC CIDR and all outbound"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "fleet-example"
  }
}

# AMI - latest Amazon Linux 2
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# Launch template
resource "aws_launch_template" "fleet" {
  name          = "fleet-example-launch-template"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t2.micro"

  network_interfaces {
    delete_on_termination = true
    security_groups       = [aws_security_group.ec2.id]
  }

  tags = {
    Name = "fleet-example"
  }
}

# IAM role for EC2 Fleet
resource "aws_iam_role" "fleet_role" {
  name = "fleet-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "fleet-example"
  }
}

# Attach managed policy for EC2 Fleet
resource "aws_iam_role_policy_attachment" "fleet_policy" {
  role       = aws_iam_role.fleet_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2FleetServiceRolePolicy"
}

# EC2 Fleet
resource "aws_ec2_fleet" "example" {
  type = "instant"

  target_capacity_specification {
    total_target_capacity       = 9
    default_target_capacity_type = "on-demand"
    on_demand_target_capacity   = 5
    spot_target_capacity        = 4
  }

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.fleet.id
      version            = aws_launch_template.fleet.latest_version
    }

    override {
      subnet_id = aws_subnet.public.id
    }

    override {
      subnet_id = aws_subnet.private.id
    }
  }

  spot_options {
    allocation_strategy = "lowestPrice"
  }

  tags = {
    Name = "fleet-example"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
  required_version = ">= 1.0"
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name prefix for resource tags"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

# Private subnets (2)
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment}-private-${count.index}"
  }
}

# Public subnet (1)
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[0]

  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-0"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.environment}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${var.environment}-nat-gw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.environment}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# KMS Key
resource "aws_kms_key" "app" {
  description             = "KMS key for EFS and EBS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = aws_kms_key.app.arn
      },
      {
        Sid    = "AllowEFSAndEC2Use"
        Effect = "Allow"
        Principal = {
          Service = ["elasticfilesystem.amazonaws.com", "ec2.amazonaws.com"]
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = aws_kms_key.app.arn
        Condition = {
          StringEquals = {
            "kms:ViaService" = [
              "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com",
              "ec2.${data.aws_region.current.name}.amazonaws.com"
            ]
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.environment}-kms"
  }
}

# Need data for region (used in KMS policy)
data "aws_region" "current" {}

# EFS File System
resource "aws_efs_file_system" "app" {
  creation_token   = "${var.environment}-efs"
  encrypted        = true
  kms_key_id       = aws_kms_key.app.arn
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.environment}-efs"
  }
}

# EFS Mount Targets (one per private subnet)
resource "aws_efs_mount_target" "app" {
  count = 2

  file_system_id  = aws_efs_file_system.app.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs_sg.id]
}

# EFS Security Group (no inline rules referencing instance_sg)
resource "aws_security_group" "efs_sg" {
  name        = "${var.environment}-efs-sg"
  description = "Security group for EFS"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.environment}-efs-sg"
  }
}

# Instance Security Group (no inline rules referencing efs_sg)
resource "aws_security_group" "instance_sg" {
  name        = "${var.environment}-instance-sg"
  description = "Security group for EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS to VPC"
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS TCP to VPC"
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS outbound"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP outbound"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-instance-sg"
  }
}

# Security group rules to establish cross-SG references (break cycle)
resource "aws_security_group_rule" "efs_ingress_nfs" {
  type                     = "ingress"
  security_group_id        = aws_security_group.efs_sg.id
  source_security_group_id = aws_security_group.instance_sg.id
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  description              = "NFS from instance SG"
}

resource "aws_security_group_rule" "instance_egress_nfs" {
  type                     = "egress"
  security_group_id        = aws_security_group.instance_sg.id
  source_security_group_id = aws_security_group.efs_sg.id
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  description              = "NFS to EFS SG"
}

resource "aws_security_group_rule" "efs_egress_nfs" {
  type                     = "egress"
  security_group_id        = aws_security_group.efs_sg.id
  source_security_group_id = aws_security_group.instance_sg.id
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  description              = "NFS to instance SG"
}

# EC2 Instances
resource "aws_instance" "app" {
  count = 2

  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  associate_public_ip_address = false

  root_block_device {
    encrypted   = true
    kms_key_id  = aws_kms_key.app.arn
    volume_type = "gp3"
    volume_size = 20
  }

  user_data = base64encode(<<-EOF
#!/bin/bash
set -e

# Retry for up to 5 minutes
max_attempts=10
delay=30

for attempt in $(seq 1 $max_attempts); do
  if dnf install -y nfs-utils 2>/dev/null; then
    break
  fi
  if [ $attempt -eq $max_attempts ]; then
    echo "Failed to install nfs-utils after $max_attempts attempts" >&2
    exit 1
  fi
  sleep $delay
done

# Mount EFS
mkdir -p /mnt/efs
mount -t nfs4 -o nfsvers=4.1,hard,timeo=600,retrans=2,noresvport ${aws_efs_file_system.app.dns_name}:/ /mnt/efs

# Add to fstab for persistence
echo "${aws_efs_file_system.app.dns_name}:/ /mnt/efs nfs4 nfsvers=4.1,hard,timeo=600,retrans=2,noresvport,_netdev 0 0" >> /etc/fstab
EOF
  )

  tags = {
    Name = "${var.environment}-instance-${count.index}"
  }

  depends_on = [aws_efs_mount_target.app]
}

# Default EBS encryption
resource "aws_ebs_encryption_by_default" "enabled" {
  enabled = true
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed for SSH access to EC2 instances"
  type        = string
  default     = "10.0.0.0/8"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "public"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "gw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "public"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2_sg"
  description = "Security group for EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2_sg"
  }
}

resource "aws_placement_group" "cluster" {
  name     = "cluster"
  strategy = "cluster"
}

resource "tls_private_key" "ec2_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "ec2" {
  key_name   = "ec2-key"
  public_key = tls_private_key.ec2_key.public_key_openssh
}

resource "aws_instance" "app" {
  count = 3

  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.public.id
  key_name               = aws_key_pair.ec2.key_name
  placement_group        = aws_placement_group.cluster.id
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]
  associate_public_ip_address = true

  tags = {
    Name = "app-${count.index + 1}"
  }
}

locals {
  common_tags = {
    Environment = var.environment
    Purpose     = "Cache Layer to reduce Database Vector calls"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "cache-vpc"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "cache-private-subnet-${count.index + 1}"
  })
}

resource "aws_elasticache_subnet_group" "cache" {
  name       = "${var.environment}-cache-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "aws_security_group" "cache" {
  name        = "${var.environment}-cache-sg"
  description = "Security group for ElastiCache Redis"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_elasticache_replication_group" "cache" {
  replication_group_id       = "${var.environment}-cache-redis"
  description                = "Redis replication group for ${var.environment} environment"
  node_type                  = var.instance_type
  engine                     = "redis"
  engine_version             = "7.1"
  port                       = 6379
  parameter_group_name       = "default.redis7"
  subnet_group_name          = aws_elasticache_subnet_group.cache.name
  security_group_ids         = [aws_security_group.cache.id]
  automatic_failover_enabled = true
  multi_az_enabled           = true
  num_cache_clusters         = 2
  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  snapshot_retention_limit   = 0

  tags = merge(local.common_tags, {
    Name = "${var.environment}-cache-redis"
  })

  lifecycle {
    prevent_destroy = true
  }
}

variable "environment" {
  description = "Environment name for tagging and naming"
  type        = string
  default     = "production"
}

variable "instance_type" {
  description = "ElastiCache node type"
  type        = string
  default     = "cache.t3.micro"
}

# ------------------------------------------------------------------------------
# VPC and Subnets
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "elasticache-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "elasticache-private-${count.index}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "elasticache-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# ElastiCache Subnet Group
# ------------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "redis-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = {
    Name = "redis-subnet-group"
  }
}

# ------------------------------------------------------------------------------
# Security Group
# ------------------------------------------------------------------------------
resource "aws_security_group" "redis" {
  name        = "redis-sg"
  description = "Security group for ElastiCache Redis"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redis-sg"
  }
}

# ------------------------------------------------------------------------------
# Secrets Manager – store Redis user password
# ------------------------------------------------------------------------------
resource "random_password" "redis_password" {
  length  = 20
  special = false
}

resource "aws_secretsmanager_secret" "redis_password" {
  name = "elasticache-redis-password"
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "elasticache-redis-password"
  }
}

resource "aws_secretsmanager_secret_version" "redis_password" {
  secret_id     = aws_secretsmanager_secret.redis_password.id
  secret_string = random_password.redis_password.result
}

# ------------------------------------------------------------------------------
# ElastiCache User and User Group
# ------------------------------------------------------------------------------
resource "aws_elasticache_user" "redis_auth" {
  user_id       = "redis-auth-user"
  user_name     = "default"
  engine        = "REDIS"
  passwords     = [random_password.redis_password.result]
  access_string = "on ~* +@all"
}

resource "aws_elasticache_user_group" "redis_auth" {
  user_group_id = "redis-auth-group"
  engine        = "REDIS"
  user_ids      = [aws_elasticache_user.redis_auth.user_id]
}

# ------------------------------------------------------------------------------
# ElastiCache Replication Group (Redis)
# ------------------------------------------------------------------------------
resource "aws_elasticache_replication_group" "main" {
  replication_group_id          = "redis-replication-group"
  description                   = "Redis replication group with authentication"
  engine                        = "redis"
  engine_version                = "7.1"
  node_type                     = "cache.t3.micro"
  num_cache_clusters            = 1
  subnet_group_name             = aws_elasticache_subnet_group.main.name
  security_group_ids            = [aws_security_group.redis.id]
  user_group_ids                = [aws_elasticache_user_group.redis_auth.user_group_id]
  transit_encryption_enabled    = true
  at_rest_encryption_enabled    = true
  automatic_failover_enabled    = false
  multi_az_enabled              = false
  parameter_group_name          = "default.redis7"
  port                          = 6379
  apply_immediately             = true
  auto_minor_version_upgrade    = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redis-replication-group"
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# Locals
locals {
  vpc_cidr        = "10.0.0.0/16"
  subnet_cidrs    = ["10.0.1.0/24", "10.0.2.0/24"]
  azs             = slice(data.aws_availability_zones.available.names, 0, 2)
  cluster_name    = "iam-auth-cluster"
  user_group_name = "iam-auth-user-group"
  user_name       = "iam-auth-user"
  role_name       = "app-elasticache-connect-role"
  policy_name     = "elasticache-connect-policy"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "elasticache-vpc"
  }
}

# Subnets (private)
resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]
  tags = {
    Name = "elasticache-subnet-${count.index}"
  }
}

# ElastiCache Subnet Group
resource "aws_elasticache_subnet_group" "main" {
  name       = "elasticache-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

# Security Group for ElastiCache
resource "aws_security_group" "elasticache" {
  name        = "elasticache-sg"
  description = "Security group for ElastiCache replication group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow Redis from VPC CIDR"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "elasticache-sg"
  }
}

# ElastiCache User (IAM type)
resource "aws_elasticache_user" "iam_auth" {
  user_id       = local.user_name
  user_name     = local.user_name
  access_string = "on ~* +@all"
  engine        = "REDIS"
  authentication_mode {
    type = "iam"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache User Group
resource "aws_elasticache_user_group" "main" {
  user_group_id = local.user_group_name
  engine        = "REDIS"
  user_ids      = [aws_elasticache_user.iam_auth.user_id]

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache Replication Group
resource "aws_elasticache_replication_group" "main" {
  replication_group_id          = local.cluster_name
  description                   = "ElastiCache replication group with IAM authentication"
  engine                        = "redis"
  engine_version                = "7.1"
  node_type                     = "cache.t4g.micro"
  num_cache_clusters            = 2
  automatic_failover_enabled    = true
  port                          = 6379
  subnet_group_name             = aws_elasticache_subnet_group.main.name
  security_group_ids            = [aws_security_group.elasticache.id]
  transit_encryption_enabled    = true
  at_rest_encryption_enabled    = true
  user_group_ids                = [aws_elasticache_user_group.main.user_group_id]
  multi_az_enabled              = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.cluster_name
  }
}

# IAM Policy for ElastiCache Connect
resource "aws_iam_policy" "elasticache_connect" {
  name        = local.policy_name
  description = "Policy to allow elasticache:Connect on the replication group"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "elasticache:Connect"
        Resource = aws_elasticache_replication_group.main.arn
      }
    ]
  })
}

# IAM Role that can be assumed by EC2
resource "aws_iam_role" "app_connect" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "connect_policy" {
  role       = aws_iam_role.app_connect.name
  policy_arn = aws_iam_policy.elasticache_connect.arn
}

# IAM User (optional) that can assume the role
resource "aws_iam_user" "app_user" {
  name = "elasticache-app-user"
}

resource "aws_iam_user_policy" "assume_role" {
  name = "assume-connect-role"
  user = aws_iam_user.app_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = aws_iam_role.app_connect.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.70.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# DATA SOURCES – only static provider metadata
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# NETWORKING – VPC, Subnets, Security Group
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "elasticache-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "elasticache-private-${count.index + 1}"
  }
}

resource "aws_security_group" "redis" {
  name        = "elasticache-redis-sg"
  description = "Allow Redis inbound from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "elasticache-redis-sg"
  }
}

# ------------------------------------------------------------------------------
# ELASTICACHE SUBNET GROUP
# ------------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "elasticache-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

# ------------------------------------------------------------------------------
# KMS KEY – for at‑rest encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "redis" {
  description             = "KMS key for ElastiCache at‑rest encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "redis" {
  name          = "alias/elasticache-redis"
  target_key_id = aws_kms_key.redis.key_id
}

# ------------------------------------------------------------------------------
# PASSWORD GENERATION & SECRETS MANAGER
# ------------------------------------------------------------------------------
resource "random_password" "redis_user" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "redis_user" {
  name                    = "elasticache-redis-user-password"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "redis_user" {
  secret_id     = aws_secretsmanager_secret.redis_user.id
  secret_string = random_password.redis_user.result
}

# ------------------------------------------------------------------------------
# ELASTICACHE USER & USER GROUP (RBAC)
# ------------------------------------------------------------------------------
resource "aws_elasticache_user" "app" {
  user_id       = "appuser"
  user_name     = "appuser"
  engine        = "REDIS"
  passwords     = [random_password.redis_user.result]
  access_string = "on ~* +@all"
}

resource "aws_elasticache_user_group" "main" {
  engine        = "REDIS"
  user_group_id = "app-group"
  user_ids      = [aws_elasticache_user.app.user_id]
}

# ------------------------------------------------------------------------------
# ELASTICACHE REPLICATION GROUP
# ------------------------------------------------------------------------------
resource "aws_elasticache_replication_group" "main" {
  replication_group_id          = "app-redis"
  description                   = "ElastiCache Redis replication group with RBAC and encryption"
  engine                        = "redis"
  engine_version                = "7.0"
  node_type                     = "cache.t3.micro"
  num_cache_clusters            = 1
  port                          = 6379
  parameter_group_name          = "default.redis7"
  subnet_group_name             = aws_elasticache_subnet_group.main.name
  security_group_ids            = [aws_security_group.redis.id]
  transit_encryption_enabled    = true
  at_rest_encryption_enabled    = true
  kms_key_id                    = aws_kms_key.redis.arn
  automatic_failover_enabled    = false
  multi_az_enabled              = false
  user_group_ids                = [aws_elasticache_user_group.main.user_group_id]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "app-redis"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random passwords for each user
resource "random_password" "password_1" {
  length           = 20
  special          = true
  override_special = "!@#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "password_2" {
  length           = 20
  special          = true
  override_special = "!@#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "password_3" {
  length           = 20
  special          = true
  override_special = "!@#$%&*()-_=+[]{}<>:?"
}

# Secrets to store the passwords
resource "aws_secretsmanager_secret" "secret_1" {
  name = "elasticache-user-1"
}

resource "aws_secretsmanager_secret_version" "secret_version_1" {
  secret_id     = aws_secretsmanager_secret.secret_1.id
  secret_string = random_password.password_1.result
}

resource "aws_secretsmanager_secret" "secret_2" {
  name = "elasticache-user-2"
}

resource "aws_secretsmanager_secret_version" "secret_version_2" {
  secret_id     = aws_secretsmanager_secret.secret_2.id
  secret_string = random_password.password_2.result
}

resource "aws_secretsmanager_secret" "secret_3" {
  name = "elasticache-user-3"
}

resource "aws_secretsmanager_secret_version" "secret_version_3" {
  secret_id     = aws_secretsmanager_secret.secret_3.id
  secret_string = random_password.password_3.result
}

# ElastiCache users
resource "aws_elasticache_user" "user_1" {
  user_id    = "user-1"
  user_name  = "user1"
  engine     = "redis"
  access_string = "on ~* +@all"
  authentication_mode {
    type      = "password"
    passwords = [random_password.password_1.result]
  }
}

resource "aws_elasticache_user" "user_2" {
  user_id    = "user-2"
  user_name  = "user2"
  engine     = "redis"
  access_string = "on ~* +@all"
  authentication_mode {
    type      = "password"
    passwords = [random_password.password_2.result]
  }
}

resource "aws_elasticache_user" "user_3" {
  user_id    = "user-3"
  user_name  = "user3"
  engine     = "redis"
  access_string = "on ~* +@all"
  authentication_mode {
    type      = "password"
    passwords = [random_password.password_3.result]
  }
}

# ElastiCache user group
resource "aws_elasticache_user_group" "main" {
  user_group_id = "main-user-group"
  engine        = "redis"
  user_ids = [
    aws_elasticache_user.user_1.user_id,
    aws_elasticache_user.user_2.user_id,
    aws_elasticache_user.user_3.user_id,
  ]
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

resource "aws_dynamodb_table" "example" {
  name           = "ExampleTableName"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_contributor_insights" "example" {
  table_name = aws_dynamodb_table.example.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
  required_version = ">= 1.0"
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dax-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  map_public_ip_on_launch = false

  tags = {
    Name = "dax-subnet-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  map_public_ip_on_launch = false

  tags = {
    Name = "dax-subnet-b"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dax-private-rt"
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.us-east-1.dynamodb"
  vpc_endpoint_type = "Gateway"

  route_table_ids = [aws_route_table.private.id]

  tags = {
    Name = "dax-dynamodb-vpce"
  }
}

resource "aws_dax_subnet_group" "main" {
  name       = "dax-subnet-group"
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id
  ]
}

resource "aws_security_group" "dax" {
  name        = "dax-sg"
  description = "Security group for DAX cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "dax-sg"
  }
}

resource "aws_security_group_rule" "dax_ingress_tcp_8111" {
  type              = "ingress"
  from_port         = 8111
  to_port           = 8111
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.dax.id
}

resource "aws_security_group_rule" "dax_ingress_self" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.dax.id
}

resource "aws_security_group_rule" "dax_egress_dynamodb" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  prefix_list_ids   = [aws_vpc_endpoint.dynamodb.prefix_list_id]
  security_group_id = aws_security_group.dax.id
}

resource "aws_iam_role" "dax" {
  name = "dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "dax-role"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "dax-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"

  attribute {
    name = "PK"
    type = "S"
  }

  tags = {
    Name = "dax-table"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "dax_dynamodb" {
  name        = "dax-dynamodb-policy"
  description = "Least privilege policy for DAX to access DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem"
        ]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.main.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dax_dynamodb" {
  role       = aws_iam_role.dax.name
  policy_arn = aws_iam_policy.dax_dynamodb.arn
}

resource "aws_dax_cluster" "main" {
  cluster_name       = "dax-cluster"
  node_type          = "dax.r4.large"
  replication_factor = 1
  iam_role_arn       = aws_iam_role.dax.arn
  subnet_group_name  = aws_dax_subnet_group.main.name
  security_group_ids = [aws_security_group.dax.id]

  server_side_encryption {
    enabled = true
  }

  cluster_endpoint_encryption_type = "TLS"

  tags = {
    Name = "dax-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  tags = {
    Environment = "production"
    Project     = "msk-cluster"
  }
  name_prefix = "msk-demo"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_security_group" "msk" {
  name        = "${local.name_prefix}-msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MSK TLS and IAM authentication"
    from_port   = 9094
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Self-referencing all traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-msk-sg" })
}

resource "aws_iam_role" "msk_broker" {
  name = "${local.name_prefix}-msk-broker-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "msk_logging" {
  name = "${local.name_prefix}-msk-logging-policy"
  role = aws_iam_role.msk_broker.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = aws_cloudwatch_log_group.msk_broker.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.msk_logs.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket" "msk_logs" {
  bucket = "${local.name_prefix}-logs-${random_id.suffix.hex}"

  # versioning block removed - replaced by aws_s3_bucket_versioning resource

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-logs" })
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    id     = "expire-logs"
    status = "Enabled"

    expiration {
      days = 30
    }

    filter {
      prefix = ""
    }
  }
}

resource "aws_cloudwatch_log_group" "msk_broker" {
  name              = "${local.name_prefix}-msk-broker-logs"
  retention_in_days = 30

  tags = local.tags
}

resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow MSK to use the key"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = local.tags
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-msk-key"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_msk_configuration" "main" {
  kafka_versions = ["3.5.1"]
  name           = "${local.name_prefix}-configuration"

  server_properties = <<-EOF
auto.create.topics.enable = false
default.replication.factor = 3
min.insync.replicas = 2
num.io.threads = 8
num.network.threads = 5
log.retention.hours = 168
EOF

  # tags argument removed - not supported by this resource
}

resource "aws_msk_cluster" "main" {
  cluster_name = "${local.name_prefix}-cluster"
  kafka_version = "3.5.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.t3.small"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  configuration_info {
    arn      = aws_msk_configuration.main.arn
    revision = aws_msk_configuration.main.latest_revision
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk-logs"
      }
    }
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# VPC and Networking
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Environment = "development"
    Name        = "main-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Environment = "development"
    Name        = "public-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Environment = "development"
    Name        = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Environment = "development"
    Name        = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security Group
# ------------------------------------------------------------------------------
resource "aws_security_group" "msk" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "ZooKeeper"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Plaintext Kafka"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "TLS Kafka"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = "development"
    Name        = "msk-sg"
  }
}

# ------------------------------------------------------------------------------
# MSK Cluster
# ------------------------------------------------------------------------------
resource "aws_msk_cluster" "main" {
  cluster_name  = "main-msk-cluster"
  kafka_version = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.t3.small"
    client_subnets  = aws_subnet.public[*].id
    security_groups = [aws_security_group.msk.id]
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }

  tags = {
    Environment = "development"
    Name        = "main-msk-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

