terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Data source for availability zones in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 2)
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-serverless-vpc"
  }
}

# Private subnets for MSK (no NAT required)
resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "msk-serverless-subnet-${count.index}"
  }
}

# Security group for MSK cluster
resource "aws_security_group" "msk" {
  name        = "msk-serverless-sg"
  description = "Security group for MSK Serverless cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
    description = "Allow Kafka IAM-authenticated traffic from VPC"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = {
    Name = "msk-serverless-sg"
  }
}

# MSK Serverless Cluster
resource "aws_msk_serverless_cluster" "this" {
  cluster_name = "example-msk-serverless"

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.msk.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Terraform configuration for MSK cluster with logging to CloudWatch, S3, and Kinesis Firehose

# Data sources for static metadata
data "aws_availability_zones" "available" {
  state = "available"
}

# Random suffix for globally unique bucket names
resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  vpc_cidr      = "10.0.0.0/16"
  subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  azs           = data.aws_availability_zones.available.names
  cluster_name  = "msk-cluster"
  log_group_name = "/aws/msk/${local.cluster_name}/broker"
  msk_logs_bucket_name = "msk-broker-logs-${random_id.suffix.hex}"
  firehose_bucket_name = "msk-firehose-output-${random_id.suffix.hex}"
}

# ------------------------------------------------------------------------------
# NETWORKING
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = length(local.subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags = {
    Name = "msk-public-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "msk-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "msk-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# SECURITY GROUP FOR MSK
# ------------------------------------------------------------------------------
resource "aws_security_group" "msk" {
  name        = "msk-security-group"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "msk-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "msk_plaintext" {
  security_group_id = aws_security_group.msk.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 9092
  to_port           = 9092
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "msk_tls" {
  security_group_id = aws_security_group.msk.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 9094
  to_port           = 9094
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "msk_zookeeper" {
  security_group_id = aws_security_group.msk.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 2181
  to_port           = 2181
  ip_protocol       = "tcp"
}

# ------------------------------------------------------------------------------
# KMS KEY FOR MSK ENCRYPTION AT REST
# ------------------------------------------------------------------------------
resource "aws_kms_key" "msk" {
  description             = "MSK encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-encryption-key"
  target_key_id = aws_kms_key.msk.key_id
}

# ------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP AND IAM ROLE FOR MSK -> CLOUDWATCH
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "msk_broker" {
  name              = local.log_group_name
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "msk_cloudwatch" {
  name = "msk-cloudwatch-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_cloudwatch" {
  name = "msk-cloudwatch-logs-policy"
  role = aws_iam_role.msk_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.msk_broker.arn}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# S3 BUCKET FOR MSK BROKER LOGS AND IAM ROLE
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "msk_logs" {
  bucket        = local.msk_logs_bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket                  = aws_s3_bucket.msk_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "msk_s3" {
  name = "msk-s3-logs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_s3" {
  name = "msk-s3-logs-policy"
  role = aws_iam_role.msk_s3.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.msk_logs.arn}",
          "${aws_s3_bucket.msk_logs.arn}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# S3 BUCKET FOR FIREHOSE OUTPUT
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "firehose_output" {
  bucket        = local.firehose_bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "firehose_output" {
  bucket = aws_s3_bucket.firehose_output.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_output" {
  bucket = aws_s3_bucket.firehose_output.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_output" {
  bucket                  = aws_s3_bucket.firehose_output.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR FIREHOSE TO WRITE TO S3
# ------------------------------------------------------------------------------
resource "aws_iam_role" "firehose_s3" {
  name = "firehose-s3-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_s3" {
  name = "firehose-s3-policy"
  role = aws_iam_role.firehose_s3.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_output.arn,
          "${aws_s3_bucket.firehose_output.arn}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR MSK -> FIREHOSE
# ------------------------------------------------------------------------------
resource "aws_iam_role" "msk_firehose" {
  name = "msk-firehose-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_firehose" {
  name = "msk-firehose-policy"
  role = aws_iam_role.msk_firehose.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Resource = aws_kinesis_firehose_delivery_stream.msk.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# KINESIS FIREHOSE DELIVERY STREAM
# ------------------------------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "msk" {
  name        = "msk-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_s3.arn
    bucket_arn = aws_s3_bucket.firehose_output.arn
    prefix     = "msk-logs/"
    error_output_prefix = "msk-logs-errors/"

    buffering_size     = 5
    buffering_interval = 60

    compression_format = "GZIP"
  }

  tags = {
    Name = "msk-firehose-stream"
  }
}

# ------------------------------------------------------------------------------
# MSK CLUSTER
# ------------------------------------------------------------------------------
resource "aws_msk_cluster" "main" {
  cluster_name  = local.cluster_name
  kafka_version = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.public[*].id
    security_groups = [aws_security_group.msk.id]
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk-logs/"
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk.name
      }
    }
  }

  tags = {
    Name = local.cluster_name
  }

  # IAM roles are referenced via ARN; need to ensure they exist
  depends_on = [
    aws_iam_role_policy.msk_cloudwatch,
    aws_iam_role_policy.msk_s3,
    aws_iam_role_policy.msk_firehose
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

locals {
  name_prefix = "msk-connect-demo"
  common_tags = {
    Environment = "dev"
    Project     = "msk-connect"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_id" "suffix" {
  byte_length = 4
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

# Public subnet for NAT Gateway
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public" })
}

# Private subnets for MSK brokers
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index}" })
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip" })
}

# NAT Gateway
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  tags          = merge(local.common_tags, { Name = "${local.name_prefix}-nat" })
}

# Route table for public subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Route table for private subnets (NAT for egress)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group for MSK brokers
resource "aws_security_group" "msk_broker" {
  name        = "${local.name_prefix}-msk-broker-sg"
  description = "Security group for MSK broker nodes"
  vpc_id      = aws_vpc.main.id
  tags        = merge(local.common_tags, { Name = "${local.name_prefix}-msk-broker-sg" })
}

resource "aws_vpc_security_group_ingress_rule" "msk_broker_from_connect_9092" {
  security_group_id            = aws_security_group.msk_broker.id
  referenced_security_group_id = aws_security_group.msk_connect.id
  from_port                    = 9092
  to_port                      = 9092
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "msk_broker_from_connect_9094" {
  security_group_id            = aws_security_group.msk_broker.id
  referenced_security_group_id = aws_security_group.msk_connect.id
  from_port                    = 9094
  to_port                      = 9094
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "msk_broker_all" {
  security_group_id = aws_security_group.msk_broker.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

# Security group for MSK Connect workers
resource "aws_security_group" "msk_connect" {
  name        = "${local.name_prefix}-msk-connect-sg"
  description = "Security group for MSK Connect workers"
  vpc_id      = aws_vpc.main.id
  tags        = merge(local.common_tags, { Name = "${local.name_prefix}-msk-connect-sg" })
}

resource "aws_vpc_security_group_egress_rule" "msk_connect_all" {
  security_group_id = aws_security_group.msk_connect.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

# S3 bucket for plugins
resource "aws_s3_bucket" "plugin" {
  bucket = "msk-connect-plugins-${random_id.suffix.hex}"
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-plugin-bucket" })
}

resource "aws_s3_bucket_public_access_block" "plugin" {
  bucket                  = aws_s3_bucket.plugin.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "plugin" {
  bucket = aws_s3_bucket.plugin.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "plugin" {
  bucket = aws_s3_bucket.plugin.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "debezium" {
  bucket = aws_s3_bucket.plugin.bucket
  key    = "debezium.zip"
  source = "debezium.zip"
}

# CloudWatch log group for MSK Connect worker logs
resource "aws_cloudwatch_log_group" "msk_connect" {
  name              = "/aws/msk-connect/${local.name_prefix}"
  retention_in_days = 7
  tags              = local.common_tags
}

# IAM role for MSK Connect
resource "aws_iam_role" "msk_connect" {
  name = "${local.name_prefix}-msk-connect-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafkaconnect.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "msk_connect" {
  name        = "${local.name_prefix}-msk-connect-policy"
  description = "Least-privilege policy for MSK Connect workers"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = [
          "${aws_s3_bucket.plugin.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.msk_connect.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          aws_secretsmanager_secret.database_credentials.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_connect" {
  role       = aws_iam_role.msk_connect.name
  policy_arn = aws_iam_policy.msk_connect.arn
}

# Secrets Manager secret for Debezium database credentials
resource "aws_secretsmanager_secret" "database_credentials" {
  name = "${local.name_prefix}-db-credentials"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "database_credentials" {
  secret_id = aws_secretsmanager_secret.database_credentials.id
  secret_string = jsonencode({
    username = "db_user"
    password = "example-password-placeholder"
  })
}

# MSK Cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.5.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk_broker.id]
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "PLAINTEXT"
      in_cluster    = false
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-msk-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# MSK Connect Custom Plugin
resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "${local.name_prefix}-debezium-plugin"
  content_type = "ZIP"
  location {
    s3 {
      bucket_arn = aws_s3_bucket.plugin.arn
      file_key   = aws_s3_object.debezium.key
    }
  }
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# MSK Connect Connector
resource "aws_mskconnect_connector" "main" {
  name = "${local.name_prefix}-connector"
  kafkaconnect_version = "2.8.1"

  capacity {
    provisioned_capacity {
      worker_count = 1
      mcu_count    = 1
    }
  }

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.main.bootstrap_brokers
      vpc {
        security_groups = [aws_security_group.msk_connect.id]
        subnets         = aws_subnet.private[*].id
      }
    }
  }

  kafka_cluster_client_authentication {
    authentication_type = "NONE"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "PLAINTEXT"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_connect.name
      }
    }
  }

  service_execution_role_arn = aws_iam_role.msk_connect.arn

  connector_configuration = {
    "connector.class"     = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max"           = "1"
    "key.converter"       = "org.apache.kafka.connect.json.JsonConverter"
    "value.converter"     = "org.apache.kafka.connect.json.JsonConverter"
    "key.converter.schemas.enable"   = "false"
    "value.converter.schemas.enable" = "false"
    "database.hostname"   = "example-db-host"
    "database.port"       = "3306"
    "database.user"       = "${aws_secretsmanager_secret.database_credentials.name}"
    "database.password"   = "$${secret:${aws_secretsmanager_secret.database_credentials.arn}:password}"
    "database.server.name" = "my-connector"
    "database.include.list" = "inventory"
    "database.history.kafka.bootstrap.servers" = aws_msk_cluster.main.bootstrap_brokers
    "database.history.kafka.topic" = "schema-changes.inventory"
    "include.schema.changes" = "true"
  }

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Random suffix for unique resource names
resource "random_pet" "suffix" {
  length = 2
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "msk-vpc"
  }
}

# Private subnets for MSK (two AZs)
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "msk-private-${count.index}"
  }
}

# Security group for MSK cluster
resource "aws_security_group" "msk" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security group for MSK Connect
resource "aws_security_group" "msk_connect" {
  name        = "msk-connect-sg"
  description = "Security group for MSK Connect workers"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 8083
    to_port     = 8083
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

# Security group rules to break cycle (ingress on MSK from MSK Connect)
resource "aws_security_group_rule" "msk_ingress_9092" {
  type                     = "ingress"
  from_port                = 9092
  to_port                  = 9092
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.msk_connect.id
  security_group_id        = aws_security_group.msk.id
}

resource "aws_security_group_rule" "msk_ingress_9094" {
  type                     = "ingress"
  from_port                = 9094
  to_port                  = 9094
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.msk_connect.id
  security_group_id        = aws_security_group.msk.id
}

resource "aws_security_group_rule" "msk_ingress_2181" {
  type                     = "ingress"
  from_port                = 2181
  to_port                  = 2181
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.msk_connect.id
  security_group_id        = aws_security_group.msk.id
}

resource "aws_security_group_rule" "msk_ingress_11001" {
  type                     = "ingress"
  from_port                = 11001
  to_port                  = 11001
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.msk_connect.id
  security_group_id        = aws_security_group.msk.id
}

# KMS key for MSK encryption at rest
resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for MSK to deliver logs
resource "aws_iam_role" "msk_log_delivery" {
  name = "msk-log-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for MSK log delivery
resource "aws_iam_policy" "msk_log_delivery" {
  name        = "msk-log-delivery-policy"
  description = "Policy for MSK to deliver logs to CloudWatch, S3, and Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.msk_broker_logs.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "firehose:PutRecord"
        ]
        Resource = [
          aws_kinesis_firehose_delivery_stream.msk_logs.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.msk.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_log_delivery" {
  role       = aws_iam_role.msk_log_delivery.name
  policy_arn = aws_iam_policy.msk_log_delivery.arn
}

# CloudWatch log group for MSK broker logs
resource "aws_cloudwatch_log_group" "msk" {
  name              = "/aws/msk/example"
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

# S3 bucket for MSK broker logs
resource "aws_s3_bucket" "msk_broker_logs" {
  bucket = "msk-broker-logs-${random_pet.suffix.id}"
}

resource "aws_s3_bucket_public_access_block" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket for Firehose destination (MSK logs via Firehose)
resource "aws_s3_bucket" "msk_firehose_destination" {
  bucket = "msk-firehose-destination-${random_pet.suffix.id}"
}

resource "aws_s3_bucket_public_access_block" "msk_firehose_destination" {
  bucket = aws_s3_bucket.msk_firehose_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_firehose_destination" {
  bucket = aws_s3_bucket.msk_firehose_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# IAM role for Firehose to write to S3
resource "aws_iam_role" "firehose" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "firehose" {
  name        = "msk-firehose-policy"
  description = "Policy for Firehose to write to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.msk_firehose_destination.arn,
          "${aws_s3_bucket.msk_firehose_destination.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose.arn
}

# Kinesis Firehose delivery stream for MSK logs
resource "aws_kinesis_firehose_delivery_stream" "msk_logs" {
  name        = "msk-logs-firehose"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose.arn
    bucket_arn = aws_s3_bucket.msk_firehose_destination.arn

    buffering_size = 5
    buffering_interval = 60

    cloudwatch_logging_options {
      enabled = false
    }
  }
}

# MSK Cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = "example-msk-cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.t3.small"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_broker_logs.id
        prefix  = ""
      }
    }
  }
}

# S3 bucket for MSK Connect custom plugin artifacts
resource "aws_s3_bucket" "msk_connect_plugins" {
  bucket = "msk-connect-plugins-${random_pet.suffix.id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Upload debezium.zip to plugin bucket
resource "aws_s3_object" "debezium" {
  bucket = aws_s3_bucket.msk_connect_plugins.id
  key    = "plugins/debezium.zip"
  source = "./debezium.zip"
}

# MSK Connect custom plugin
resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "debezium-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = aws_s3_bucket.msk_connect_plugins.arn
      file_key   = aws_s3_object.debezium.key
    }
  }
}

# IAM role for MSK Connect
resource "aws_iam_role" "msk_connect" {
  name = "msk-connect-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafkaconnect.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for MSK Connect
resource "aws_iam_policy" "msk_connect" {
  name        = "msk-connect-policy"
  description = "Policy for MSK Connect workers"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:DescribeClusterV2"
        ]
        Resource = aws_msk_cluster.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kafkaconnect:DescribeConnector",
          "kafkaconnect:ListConnectors"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_connect" {
  role       = aws_iam_role.msk_connect.name
  policy_arn = aws_iam_policy.msk_connect.arn
}

# Worker configuration for MSK Connect
resource "aws_mskconnect_worker_configuration" "default" {
  name                    = "default-worker-config"
  properties_file_content = <<EOF
key.converter=org.apache.kafka.connect.storage.StringConverter
value.converter=org.apache.kafka.connect.storage.StringConverter
offset.storage.file.filename=/tmp/connect.offsets
EOF
}

# MSK Connect connector
resource "aws_mskconnect_connector" "debezium" {
  name = "debezium-connector"

  kafkaconnect_version = "2.7.3"

  connector_configuration = {
    "connector.class"                         = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max"                               = "1"
    "database.hostname"                       = "example-db-host"
    "database.port"                           = "3306"
    "database.user"                           = "example-user"
    "database.password"                       = "example-password"
    "database.server.name"                    = "example-server"
    "database.include.list"                   = "example-db"
    "database.history.kafka.bootstrap.servers" = aws_msk_cluster.main.bootstrap_brokers_tls
    "database.history.kafka.topic"            = "schema-changes.example"
  }

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.main.bootstrap_brokers_tls
      vpc {
        subnets         = aws_subnet.private[*].id
        security_groups = [aws_security_group.msk_connect.id]
      }
    }
  }

  kafka_cluster_client_authentication {
    authentication_type = "NONE"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  service_execution_role_arn = aws_iam_role.msk_connect.arn

  worker_configuration {
    arn      = aws_mskconnect_worker_configuration.default.arn
    revision = aws_mskconnect_worker_configuration.default.latest_revision
  }

  capacity {
    autoscaling {
      max_worker_count = 2
      min_worker_count = 1
      scale_in_policy {
        cpu_utilization_percentage = 20
      }
      scale_out_policy {
        cpu_utilization_percentage = 80
      }
    }
  }

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "engine_version" {
  description = "Aurora MySQL engine version"
  type        = string
  default     = "8.0.mysql_aurora.3.02.0"
}

variable "instance_class" {
  description = "Instance class for Aurora cluster instances"
  type        = string
  default     = "db.r5.large"
}

locals {
  name_prefix = "aurora"
}

# VPC
resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = cidrsubnet(aws_vpc.aurora_vpc.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "aurora" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.name_prefix}-subnet-group"
  }
}

# Security Group
resource "aws_security_group" "aurora_sg" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Aurora MySQL cluster"
  vpc_id      = aws_vpc.aurora_vpc.id

  ingress {
    description = "MySQL from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.aurora_vpc.cidr_block]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

# KMS Key for Aurora Encryption
resource "aws_kms_key" "aurora" {
  description             = "KMS key for Aurora cluster storage encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow RDS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-kms"
  }
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/${local.name_prefix}-kms"
  target_key_id = aws_kms_key.aurora.key_id
}

# Random password for master user
resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!@#$%^&*()-_=+[]{}|;:,.<>?"
}

# Secrets Manager Secret
resource "aws_secretsmanager_secret" "master" {
  name = "${local.name_prefix}-master-password"
  tags = {
    Name = "${local.name_prefix}-master-password"
  }
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id     = aws_secretsmanager_secret.master.id
  secret_string = random_password.master.result
}

# Cluster Parameter Group
resource "aws_rds_cluster_parameter_group" "aurora" {
  name        = "${local.name_prefix}-cluster-params"
  family      = "aurora-mysql8.0"
  description = "Cluster parameter group for Aurora MySQL 8.0"

  parameter {
    name  = "time_zone"
    value = "UTC"
  }

  tags = {
    Name = "${local.name_prefix}-cluster-params"
  }
}

# Aurora Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier              = "${local.name_prefix}-cluster"
  engine                         = "aurora-mysql"
  engine_version                 = var.engine_version
  master_username                 = "admin"
  master_password                 = aws_secretsmanager_secret_version.master.secret_string
  db_subnet_group_name            = aws_db_subnet_group.aurora.name
  vpc_security_group_ids          = [aws_security_group.aurora_sg.id]
  backup_retention_period         = 7
  preferred_backup_window         = "03:00-04:00"
  preferred_maintenance_window    = "Sun:04:00-Sun:05:00"
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.aurora.arn
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora.name
  iam_database_authentication_enabled = true
  enabled_cloudwatch_logs_exports = ["error", "slowquery", "audit"]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-cluster"
  }
}

# Writer Instance
resource "aws_rds_cluster_instance" "writer" {
  identifier              = "${local.name_prefix}-writer"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = var.instance_class
  engine                  = aws_rds_cluster.aurora.engine
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  promotion_tier          = 0

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-writer"
  }
}

# Reader Instance
resource "aws_rds_cluster_instance" "reader" {
  identifier              = "${local.name_prefix}-reader"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = var.instance_class
  engine                  = aws_rds_cluster.aurora.engine
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  promotion_tier          = 1

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-reader"
  }
}

# Data source for current account ID (used in KMS policy)
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.95.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "master" {
  length  = 20
  special = false
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "aurora-vpc"
  }
}

resource "aws_subnet" "aurora_subnet_a" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "aurora-subnet-a"
  }
}

resource "aws_subnet" "aurora_subnet_b" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = {
    Name = "aurora-subnet-b"
  }
}

resource "aws_db_subnet_group" "aurora_db_subnet_group" {
  name       = "aurora-db-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_a.id, aws_subnet.aurora_subnet_b.id]
  tags = {
    Name = "aurora-db-subnet-group"
  }
}

resource "aws_security_group" "aurora_sg" {
  name        = "aurora-sg"
  description = "Security group for Aurora PostgreSQL cluster"
  vpc_id      = aws_vpc.aurora_vpc.id

  ingress {
    description = "PostgreSQL from VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.aurora_vpc.cidr_block]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-sg"
  }
}

resource "aws_kms_key" "aurora_encryption" {
  description             = "KMS key for Aurora PostgreSQL encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow RDS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "aurora_encryption" {
  name          = "alias/aurora-encryption-key"
  target_key_id = aws_kms_key.aurora_encryption.key_id
}

resource "aws_rds_cluster_parameter_group" "aurora_postgres" {
  name        = "aurora-postgresql14-params"
  family      = "aurora-postgresql14"
  description = "Parameter group for Aurora PostgreSQL 14"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }
}

resource "aws_secretsmanager_secret" "master_password" {
  name = "aurora-master-password-${random_id.suffix.hex}"
}

resource "aws_secretsmanager_secret_version" "master_password" {
  secret_id     = aws_secretsmanager_secret.master_password.id
  secret_string = random_password.master.result
}

resource "aws_rds_cluster" "aurora_postgres_cluster" {
  cluster_identifier              = "aurora-postgres-cluster"
  engine                          = "aurora-postgresql"
  engine_version                  = "14.10"
  master_username                 = "dbadmin"
  master_password                 = aws_secretsmanager_secret_version.master_password.secret_string
  kms_key_id                      = aws_kms_key.aurora_encryption.arn
  db_subnet_group_name            = aws_db_subnet_group.aurora_db_subnet_group.name
  vpc_security_group_ids          = [aws_security_group.aurora_sg.id]
  storage_encrypted               = true
  backup_retention_period         = 7
  skip_final_snapshot             = false
  final_snapshot_identifier       = "aurora-postgres-cluster-final-${random_id.suffix.hex}"
  deletion_protection             = true
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora_postgres.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "aurora_instance_1" {
  identifier         = "aurora-instance-1"
  cluster_identifier = aws_rds_cluster.aurora_postgres_cluster.id
  instance_class     = "db.r6g.large"
  engine             = aws_rds_cluster.aurora_postgres_cluster.engine
  engine_version     = aws_rds_cluster.aurora_postgres_cluster.engine_version
  publicly_accessible = false
  db_subnet_group_name = aws_db_subnet_group.aurora_db_subnet_group.name
}

resource "aws_iam_role" "rds_enhanced_monitoring_role" {
  name = "rds-enhanced-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

locals {
  vpc_cidr       = "10.0.0.0/16"
  subnet_cidrs   = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  db_name        = "mysql-cluster"
