  assume_role_policy = data.aws_iam_policy_document.enhanced_monitoring_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy" "enhanced_monitoring" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

resource "aws_iam_role_policy_attachment" "enhanced_monitoring" {
  role       = aws_iam_role.enhanced_monitoring.name
  policy_arn = data.aws_iam_policy.enhanced_monitoring.arn
}

data "aws_partition" "current" {}

resource "aws_db_instance" "primary" {
  identifier     = "${local.name_prefix}-primary"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 100
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn
  storage_type          = "gp3"

  db_name  = "mydb"
  username = "admin"
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  availability_zone = data.aws_availability_zones.available.names[0]

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  skip_final_snapshot     = false
  final_snapshot_identifier = "${local.name_prefix}-primary-final-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.enhanced_monitoring.arn

  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "random_password" "master" {
  length  = 16
  special = false
}

resource "aws_db_instance" "replica" {
  identifier = "${local.name_prefix}-replica-us-east-1c"
  replicate_source_db = aws_db_instance.primary.identifier

  instance_class = aws_db_instance.primary.instance_class
  allocated_storage = 100
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn
  storage_type      = "gp3"

  availability_zone = data.aws_availability_zones.available.names[2]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = 7
  backup_window           = "05:00-06:00"
  maintenance_window      = "sun:06:00-sun:07:00"

  skip_final_snapshot     = false
  final_snapshot_identifier = "${local.name_prefix}-replica-final-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.enhanced_monitoring.arn

  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replica-us-east-1c"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

locals {
  name_prefix = "mysql"
  environment = "production"
  managed_by  = "terraform"
  common_tags = {
    Environment = local.environment
    ManagedBy   = local.managed_by
    Name        = local.name_prefix
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Private subnets (two in different AZs)
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  })
}

# DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Security group for MySQL RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL access from within VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

# Parameter group for MySQL 8.0
resource "aws_db_parameter_group" "mysql" {
  name   = "${local.name_prefix}-param-group"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8"
  }

  tags = local.common_tags
}

# MySQL RDS instance
resource "aws_db_instance" "mysql" {
  identifier     = "${local.name_prefix}-instance"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  storage_type          = "gp3"
  storage_encrypted     = true
  backup_retention_period = 7

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  # Managed master password via Secrets Manager
  manage_master_user_password = true
  username                      = "admin"
  port                          = 3306

  # Prevent deletion of stateful resource
  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "environment" {
  description = "Deployment environment name"
  type        = string
  default     = "dev"
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "db_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "16.3"
}

locals {
  name_prefix = "postgres-${var.environment}"
  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = local.name_prefix
  subnet_ids = aws_subnet.private[*].id

  tags = local.tags
}

resource "aws_security_group" "rds" {
  name_prefix = "${local.name_prefix}-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.tags
}

resource "random_password" "master" {
  length           = 20
  special          = false
  override_special = ""
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-db-master-password"
  description = "Master password for RDS PostgreSQL instance"
  tags        = local.tags
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id     = aws_secretsmanager_secret.db_master.id
  secret_string = random_password.master.result
}

resource "aws_db_instance" "postgres" {
  identifier = local.name_prefix
  engine     = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class
  allocated_storage     = 20
  storage_encrypted     = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  username               = "dbadmin"
  password               = random_password.master.result
  backup_retention_period = 7
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade = true
  deletion_protection    = true
  skip_final_snapshot    = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

