provider "aws" {
  region = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB table"
  type        = string
  default     = "my-dynamodb-table"
}

variable "tags" {
  description = "A map of tags to assign to the table"
  type        = map(string)
  default     = {}
}

resource "aws_dynamodb_table" "this" {
  name           = var.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 10
  write_capacity = 10
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

# Fetch available availability zones
data "aws_availability_zones" "available" {}

locals {
  vpc_cidr        = "10.0.0.0/16"
  az_count        = 2
  az_names        = slice(data.aws_availability_zones.available.names, 0, local.az_count)
  subnet_cidrs    = [for idx in range(local.az_count) : cidrsubnet(local.vpc_cidr, 8, idx + 1)]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dax-vpc"
  }
}

# Public subnets in different AZs
resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "dax-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dax-igw"
  }
}

# Route table with default route to IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "dax-route-table"
  }
}

# Route table associations
resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for DAX cluster
resource "aws_security_group" "dax" {
  name        = "dax-sg"
  description = "Security group for DAX cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "dax-sg"
  }
}

# DAX Subnet Group
resource "aws_dax_subnet_group" "cluster" {
  name       = "dax-subnet-group"
  subnet_ids = aws_subnet.public[*].id
}

# DAX Parameter Group
resource "aws_dax_parameter_group" "dax" {
  name = "dax-params"
}

# IAM Role for DAX
resource "aws_iam_role" "dax" {
  name = "dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "dax-role"
  }
}

# Attach AmazonDynamoDBFullAccess policy
resource "aws_iam_role_policy_attachment" "dax" {
  role       = aws_iam_role.dax.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonDynamoDBFullAccess"
}

# DAX Cluster
resource "aws_dax_cluster" "dax" {
  cluster_name                    = "my-dax-cluster"
  node_type                       = "dax.r5.large"
  replication_factor              = 3
  iam_role_arn                    = aws_iam_role.dax.arn
  subnet_group_name               = aws_dax_subnet_group.cluster.name
  security_group_ids              = [aws_security_group.dax.id]
  parameter_group_name            = aws_dax_parameter_group.dax.name
  cluster_endpoint_encryption_type = "TLS"

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Deployment environment (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "dax-param-group"
  full_name   = "${local.name_prefix}-${var.environment}"
}

resource "aws_dax_parameter_group" "main" {
  name        = local.full_name
  description = "DAX parameter group for ${var.environment} environment caching"

  parameters {
    name  = "query-ttl-min"
    value = "5"
  }

  parameters {
    name  = "record-ttl-min"
    value = "5"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Get available AZs in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

# Common tags
locals {
  environment = "dev"
  common_tags = {
    Environment = local.environment
    ManagedBy   = "Terraform"
  }
}

# VPC for DAX subnet group
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "dax-vpc"
  })
}

# Two private subnets in different AZs
resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)  # 10.0.1.0/24, 10.0.2.0/24
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "dax-private-subnet-${count.index + 1}"
  })
}

# DAX subnet group referencing the private subnets
resource "aws_dax_subnet_group" "main" {
  name        = "my-dax-subnet-group"
  description = "DAX subnet group"
  subnet_ids  = aws_subnet.private[*].id
}

