    }
  }
}

data "aws_iam_policy_document" "ttl_app_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ttl_app_policy" {
  statement {
    actions = [
      "dynamodb:UpdateTimeToLive",
      "dynamodb:DescribeTimeToLive"
    ]
    resources = [
      aws_dynamodb_table.with_ttl.arn
    ]
  }
}

resource "aws_iam_role" "ttl_app" {
  name               = "ttl-app-role"
  assume_role_policy = data.aws_iam_policy_document.ttl_app_assume_role.json
}

resource "aws_iam_policy" "ttl_app_policy" {
  name        = "ttl-app-policy"
  description = "Policy to manage TTL on DynamoDB table"
  policy      = data.aws_iam_policy_document.ttl_app_policy.json
}

resource "aws_iam_role_policy_attachment" "ttl_app_attach" {
  role       = aws_iam_role.ttl_app.name
  policy_arn = aws_iam_policy.ttl_app_policy.arn
}

resource "aws_dynamodb_table" "with_ttl" {
  name           = "with-ttl-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "expires_at"
    type = "N"
  }

  ttl {
    attribute_name = "expires_at"
    enabled        = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

