terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.46.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for naming and tagging resources"
  type        = string
  default     = "production"
}

locals {
  connector_names = ["voice-connector-a", "voice-connector-b"]
}

resource "aws_chime_voice_connector" "this" {
  for_each = toset(local.connector_names)

  name               = "${var.environment}-${each.key}"
  require_encryption = true

  tags = {
    Name        = "${var.environment}-${each.key}"
    Environment = var.environment
    Group       = "voice-connectors"
  }
}

resource "aws_chime_voice_connector" "connector_a" {
  name               = "voice-connector-a"
  require_encryption = true
}

resource "aws_chime_voice_connector" "connector_b" {
  name               = "voice-connector-b"
  require_encryption = true
}

resource "aws_chime_voice_connector_group" "main" {
  name = "voice-connector-group"

  connector {
    voice_connector_id = aws_chime_voice_connector.connector_a.id
    priority          = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.connector_b.id
    priority          = 2
  }
}

resource "aws_chime_voice_connector" "voice_connector_primary" {
  name               = "voice-connector-primary"
  require_encryption = true
}

resource "aws_chime_voice_connector" "voice_connector_secondary" {
  name               = "voice-connector-secondary"
  require_encryption = true
}

resource "aws_chime_voice_connector_group" "voice_connector_group" {
  name = "voice-connector-group"

  connector {
    voice_connector_id = aws_chime_voice_connector.voice_connector_primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.voice_connector_secondary.id
    priority           = 3
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

locals {
  tags = {
    Name        = "chime-voice-connectors"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# Primary Voice Connector
resource "aws_chime_voice_connector" "primary" {
  name               = "voice-connector-primary"
  require_encryption = true
  aws_region         = "us-east-1"

  tags = local.tags
}

# Secondary Voice Connector
resource "aws_chime_voice_connector" "secondary" {
  name               = "voice-connector-secondary"
  require_encryption = true
  aws_region         = "us-east-1"

  tags = local.tags
}

# Voice Connector Group
resource "aws_chime_voice_connector_group" "group" {
  name = "voice-connector-group"

  connector {
    voice_connector_id = aws_chime_voice_connector.primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.secondary.id
    priority           = 2
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "voice_connector_name" {
  description = "Name of the Chime Voice Connector"
  type        = string
  default     = "my-voice-connector"
}

data "aws_region" "current" {}

resource "aws_chime_voice_connector" "main" {
  name               = var.voice_connector_name
  aws_region         = data.aws_region.current.name
  require_encryption = true
}

resource "aws_chime_voice_connector_logging" "main" {
  voice_connector_id       = aws_chime_voice_connector.main.id
  enable_sip_logs          = false
  enable_media_metric_logs = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
