      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "vc_name" {
  description = "Name of the Chime Voice Connector"
  type        = string
  default     = "chime-vc"
}

variable "environment" {
  description = "Deployment environment (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Name        = var.vc_name
  }
}

resource "aws_chime_voice_connector" "main" {
  name               = var.vc_name
  require_encryption = false

  tags = local.common_tags
}

resource "aws_chime_voice_connector_logging" "media_only" {
  voice_connector_id       = aws_chime_voice_connector.main.id
  enable_media_metric_logs = true
  enable_sip_logs          = false
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

resource "aws_kms_key" "chime" {
  description             = "Symmetric KMS key for Chime Voice Connector media encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Chime Service"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "chime" {
  name          = "alias/chime-voice-connector"
  target_key_id = aws_kms_key.chime.id
}

resource "aws_chime_voice_connector" "main" {
  name               = "main-voice-connector"
  require_encryption = true
}

resource "aws_chime_voice_connector_logging" "main" {
  voice_connector_id       = aws_chime_voice_connector.main.id
  enable_sip_logs          = false
  enable_media_metric_logs = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80.0"
    }
  }
}

variable "voice_connector_name" {
  description = "Name of the Chime Voice Connector"
  type        = string
  default     = "my-voice-connector"
}

# SNS topic for streaming notifications
resource "aws_sns_topic" "chime_notifications" {
  name = "${var.voice_connector_name}-notifications"

  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic policy to allow Chime to publish
resource "aws_sns_topic_policy" "chime_notifications" {
  arn = aws_sns_topic.chime_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
        Action = "sns:Publish"
        Resource = aws_sns_topic.chime_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_chime_voice_connector.main.arn
          }
        }
      }
    ]
  })
}

# Chime Voice Connector with encryption (AWS-owned CMK is used by default)
resource "aws_chime_voice_connector" "main" {
  name               = var.voice_connector_name
  require_encryption = true
}

# Streaming configuration for the voice connector
resource "aws_chime_voice_connector_streaming" "main" {
  voice_connector_id              = aws_chime_voice_connector.main.id
  data_retention                  = 5
  streaming_notification_targets  = ["SNS"]
  # Omitting kinesis_stream_id disables streaming to Amazon Kinesis
  # disabled defaults to false, so streaming is active
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

resource "aws_chime_voice_connector" "main" {
  name               = "voice-connector-main"
  aws_region         = "us-east-1"
  require_encryption = true
}

resource "aws_kinesis_video_stream" "main" {
  name                    = "chime-media-stream-main"
  data_retention_in_hours = 24
  kms_key_id              = "alias/aws/kinesisvideo"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_streaming" "main" {
  voice_connector_id = aws_chime_voice_connector.main.id
  data_retention     = 7
  disabled           = false
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "redshift-example"
  }
}

locals {
  cluster_identifier = "redshift-cluster-example"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(var.tags, { Name = "redshift-vpc" })
}

resource "aws_subnet" "redshift_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = merge(var.tags, { Name = "redshift-subnet-1" })
}

resource "aws_subnet" "redshift_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = merge(var.tags, { Name = "redshift-subnet-2" })
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_1.id, aws_subnet.redshift_2.id]
  tags       = var.tags
}

resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id
  tags        = var.tags

  ingress {
    description = "Redshift access from VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "random_password" "master_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name = "redshift-master-password-${local.cluster_identifier}"
  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master_password.result
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier        = local.cluster_identifier
  database_name             = "dev"
  master_username           = "admin"
  master_password           = random_password.master_password.result
  node_type                 = "ra3.xlplus"
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  skip_final_snapshot       = true
  tags                      = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_redshift_endpoint_access" "main" {
  endpoint_name           = "redshift-endpoint"
  cluster_identifier      = aws_redshift_cluster.main.cluster_identifier
  subnet_group_name       = aws_redshift_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.redshift.id]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  prefix = "redshift-demo"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.prefix}-subnet-group"
  description = "Subnet group for Redshift cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name = "${local.prefix}-subnet-group"
  }
}

resource "aws_security_group" "redshift" {
  name        = "${local.prefix}-security-group"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from private subnets"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = aws_subnet.private[*].cidr_block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.prefix}-security-group"
  }
}

resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "master" {
  name = "redshift-master-password"

  tags = {
    Name = "${local.prefix}-secret"
  }
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id     = aws_secretsmanager_secret.master.id
  secret_string = random_password.master.result
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.prefix}-cluster"
  database_name      = "dev"
  master_username    = "admin"
  master_password    = random_password.master.result
  node_type          = "dc2.large"
  number_of_nodes    = 1

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.prefix}-final-snapshot"

  tags = {
    Name = "${local.prefix}-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "environment_name" {
  description = "Environment name used as prefix for resource naming"
  type        = string
  default     = "prod"
}

variable "master_username" {
  description = "Redshift master username"
  type        = string
  default     = "admin"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  name_prefix = var.environment_name
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-subnet-${count.index}"
    Type = "private"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "${local.name_prefix}-redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.name_prefix}-redshift-subnet-group"
  }
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-redshift-sg"
  }
}

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!@#$%^&*()-_=+[]{}|;:,.<>?"
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name = "${local.name_prefix}-redshift-master-password"

  tags = {
    Name = "${local.name_prefix}-redshift-master-password"
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master.result
}

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "redshift-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-redshift-kms-key"
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift-key"
  target_key_id = aws_kms_key.redshift.key_id
}

data "aws_caller_identity" "current" {}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = "${local.name_prefix}-redshift-cluster"
  cluster_type                        = "single-node"
  node_type                           = "dc2.large"
  master_username                     = var.master_username
  master_password                     = random_password.master.result
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  publicly_accessible                 = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false

  tags = {
    Name = "${local.name_prefix}-redshift-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "redshift_events" {
  name              = "${local.name_prefix}-redshift-event-topic"
  kms_master_key_id = aws_kms_key.redshift.arn

  tags = {
    Name = "${local.name_prefix}-redshift-event-topic"
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "redshift-sns-policy"
    Statement = [
      {
        Sid    = "Allow Redshift to publish events"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redshift_events.arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_redshift_cluster.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_redshift_event_subscription" "main" {
  name     = "${local.name_prefix}-redshift-event-subscription"
  enabled  = true
  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security",
    "pending"
  ]
  source_type       = "cluster"
  source_ids        = [aws_redshift_cluster.main.id]
  sns_topic_arn     = aws_sns_topic.redshift_events.arn

  tags = {
    Name = "${local.name_prefix}-redshift-event-subscription"
  }
}

output "redshift_cluster_endpoint" {
  description = "Redshift cluster endpoint"
  value       = aws_redshift_cluster.main.endpoint
}

output "sns_topic_arn" {
  description = "SNS topic ARN for Redshift events"
  value       = aws_sns_topic.redshift_events.arn
}

# Data source for available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-vpc"
  }
}

# Subnets
resource "aws_subnet" "redshift" {
  count = 2

  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  vpc_id                  = aws_vpc.main.id
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-subnet-${count.index + 1}"
  }
}

# Redshift subnet group
resource "aws_redshift_subnet_group" "main" {
  name        = "redshift-subnet-group"
  description = "Subnet group for Redshift cluster"
  subnet_ids  = aws_subnet.redshift[*].id

  tags = {
    Name = "redshift-subnet-group"
  }
}

# Security group for Redshift
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# KMS key for Redshift encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift to use the key"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-kms-key"
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/redshift-key"
  target_key_id = aws_kms_key.redshift.key_id
}

# KMS key for SNS encryption
resource "aws_kms_key" "sns" {
  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "sns-kms-key"
  }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-key"
  target_key_id = aws_kms_key.sns.key_id
}

# Random password
