  name = "redshift-master-password"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master.result
}

# Redshift cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "redshift-cluster"
  database_name             = "dev"
  master_username           = "admin"
  master_password           = random_password.master.result
  node_type                 = "dc2.large"
  cluster_type              = "single-node"
  publicly_accessible       = false
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  cluster_subnet_group_name = aws_redshift_subnet_group.main.id
  encrypted                 = true
  kms_key_id                = aws_kms_key.redshift.arn
  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-cluster"
  }
}

# SNS topic
resource "aws_sns_topic" "redshift_events" {
  name              = "redshift-events"
  kms_master_key_id = aws_kms_key.sns.arn

  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic policy allowing Redshift to publish
data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AllowRedshiftPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]
  }
}

resource "aws_sns_topic_policy" "default" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# Redshift event subscription
resource "aws_redshift_event_subscription" "main" {
  name          = "redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster"
  source_ids    = [aws_redshift_cluster.main.id]
  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security",
    "pending"
  ]
  severity                  = "INFO"
  enabled                   = true

  tags = {
    Name = "redshift-event-subscription"
  }
}

# Data source for current account ID (needed for KMS policy)
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Redshift-VPC"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-private-${count.index + 1}"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "Redshift-Subnet-Group"
  }
}

resource "aws_security_group" "redshift" {
  name   = "redshift-security-group"
  vpc_id = aws_vpc.main.id

  ingress {
    description = "Redshift access from VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Redshift-SG"
  }
}

resource "aws_redshift_parameter_group" "example" {
  name   = "example-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "max_concurrency_scaling_clusters"
    value = "1"
  }

  tags = {
    Name = "Example-Param-Group"
  }
}

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift Service"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "RedshiftKey"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "random_password" "redshift_master" {
  length           = 16
  special          = true
  override_special = "!@#$%"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name = "RedshiftMasterPassword"

  tags = {
    Name = "RedshiftMasterPassword"
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id     = aws_secretsmanager_secret.redshift_master.id
  secret_string = random_password.redshift_master.result
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier        = "example-redshift-cluster"
  database_name             = "exampledb"
  master_username           = "admin"
  master_password           = random_password.redshift_master.result
  node_type                 = "dc2.large"
  number_of_nodes           = 1
  encrypted                 = true
  kms_key_id                = aws_kms_key.redshift.arn
  cluster_parameter_group_name = aws_redshift_parameter_group.example.name
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  skip_final_snapshot       = false
  publicly_accessible       = false

  tags = {
    Name = "ExampleRedshiftCluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "redshift_events" {
  name = "RedshiftEventNotifications"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRedshiftToPublish"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "RedshiftEventTopic"
  }
}

resource "aws_redshift_event_subscription" "example" {
  name         = "example-parameter-group-events"
  source_ids   = [aws_redshift_parameter_group.example.name]
  source_type  = "cluster-parameter-group"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  severity     = "ERROR"
  enabled      = true

  tags = {
    Name = "Example-EventSubscription"
  }
}

locals {
  name_prefix = "redshift-example"
  vpc_cidr    = "10.0.0.0/16"
  redshift_port = 5439
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  }
}

# Security group
resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

resource "aws_security_group_rule" "redshift_ingress" {
  type              = "ingress"
  from_port         = local.redshift_port
  to_port           = local.redshift_port
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.redshift.id
}

resource "aws_security_group_rule" "redshift_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.redshift.id
}

# SNS topic and policy
resource "aws_sns_topic" "redshift_events" {
  name = "${local.name_prefix}-events"
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AllowRedshiftToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "default" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name        = "${local.name_prefix}-param-group"
  family      = "redshift-1.0"
  description = "Example Redshift parameter group"

  # No custom parameters; using defaults
}

# Random password and Secrets Manager secret
resource "random_password" "master_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name        = "${local.name_prefix}-master-password"
  description = "Master password for Redshift cluster"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master_password" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master_password.result
}

# Redshift subnet group
resource "aws_redshift_subnet_group" "example" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for Redshift cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name = "${local.name_prefix}-subnet-group"
  }
}

# Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  node_type                 = "dc2.large"
  number_of_nodes           = 2
  master_username           = "admin"
  master_password           = random_password.master_password.result
  cluster_parameter_group_name = aws_redshift_parameter_group.example.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  cluster_subnet_group_name = aws_redshift_subnet_group.example.name
  publicly_accessible       = false
  encrypted                 = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-cluster"
  }
}

# Redshift event subscription
resource "aws_redshift_event_subscription" "example" {
  name             = "${local.name_prefix}-event-sub"
  sns_topic_arn    = aws_sns_topic.redshift_events.arn
  source_type      = "cluster-parameter-group"
  source_ids       = [aws_redshift_parameter_group.example.name]
  severity         = "INFO"
  enabled          = true

  tags = {
    Name = "${local.name_prefix}-event-sub"
  }
}

variable "group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "basic-group"
}

variable "user_names" {
  description = "List of IAM user names"
  type        = list(string)
  default     = ["user1", "user2"]
}

resource "aws_iam_group" "basic" {
  name = var.group_name
}

resource "aws_iam_user" "basic_users" {
  for_each = toset(var.user_names)
  name     = each.key
}

resource "aws_iam_group_membership" "basic" {
  name  = "${var.group_name}-membership"
  group = aws_iam_group.basic.name
  users = values(aws_iam_user.basic_users)[*].name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_iam_policy" "readonly" {
  name = "ReadOnlyAccess"
}

resource "aws_iam_group" "example_group" {
  name = "example-group"
}

resource "aws_iam_group_policy_attachment" "example" {
  group      = aws_iam_group.example_group.name
  policy_arn = data.aws_iam_policy.readonly.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.95.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "= 4.0.0"
    }
  }
}

resource "aws_iam_user" "example" {
  name = "basic-user"
  tags = {
    Name = "basic-user"
  }
}

resource "tls_private_key" "example" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_iam_user_ssh_key" "example" {
  username   = aws_iam_user.example.name
  encoding   = "SSH"
  public_key = tls_private_key.example.public_key_openssh
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "developers"
}

variable "group_path" {
  description = "Path for the IAM group"
  type        = string
  default     = "/users/"
}

resource "aws_iam_group" "example" {
  name = var.group_name
  path = var.group_path
}

terraform {
  required_version = ">= 1.3, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.95.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "user_name" {
  description = "Name of the IAM user"
  type        = string
  default     = "example-user"
}

locals {
  common_tags = {
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

# Secret for console password (will store auto-generated password)
resource "aws_secretsmanager_secret" "console_password" {
  name = "${var.user_name}-console-password"
  tags = local.common_tags
}

# IAM user
resource "aws_iam_user" "main" {
  name = var.user_name
  tags = local.common_tags
}

# Login profile (password auto-generated by AWS)
resource "aws_iam_user_login_profile" "main" {
  user                    = aws_iam_user.main.name
  password_reset_required = true
}

# Store the auto-generated password in Secrets Manager
resource "aws_secretsmanager_secret_version" "console_password" {
  secret_id     = aws_secretsmanager_secret.console_password.id
  secret_string = aws_iam_user_login_profile.main.password
}

# Access key for programmatic access
resource "aws_iam_access_key" "main" {
  user = aws_iam_user.main.name
}

# Secret for access key secret
resource "aws_secretsmanager_secret" "access_key_secret" {
  name = "${var.user_name}-access-key-secret"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "access_key_secret" {
  secret_id     = aws_secretsmanager_secret.access_key_secret.id
  secret_string = aws_iam_access_key.main.secret
}

# Attach ReadOnlyAccess policy
resource "aws_iam_user_policy_attachment" "readonly" {
  user       = aws_iam_user.main.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# Data source for availability zones (best practice placeholder)
data "aws_availability_zones" "available" {
  state = "available"
}

# Variable for the virtual MFA device name
variable "virtual_mfa_device_name" {
  description = "Name of the IAM virtual MFA device"
  type        = string
  default     = "example-virtual-mfa"
}

# Local values for common tags
locals {
  common_tags = {
    Name        = var.virtual_mfa_device_name
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# IAM Virtual MFA Device resource
resource "aws_iam_virtual_mfa_device" "this" {
  virtual_mfa_device_name = var.virtual_mfa_device_name
  path                    = "/"

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

terraform {
  required_version = ">= 1.2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name"
  type        = string
  default     = "example-bucket"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "this" {
  bucket = "${var.bucket_name_prefix}-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.81.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "images" {
  bucket = "website-images-${random_id.bucket_suffix.hex}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "images" {
  bucket = aws_s3_bucket.images.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "images" {
  bucket = aws_s3_bucket.images.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "images" {
  bucket = aws_s3_bucket.images.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudfront_origin_access_control" "images" {
  name                              = "images-oac-${random_id.bucket_suffix.hex}"
  description                       = "OAC for website images bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

resource "aws_cloudfront_distribution" "images" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Distribution for website images"
  price_class         = "PriceClass_100"
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.images.bucket_regional_domain_name
    origin_id                = "s3-images"
    origin_access_control_id = aws_cloudfront_origin_access_control.images.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-images"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_policy" "images" {
  bucket = aws_s3_bucket.images.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipal"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.images.bucket}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.images.arn
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.95.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "mybucket"
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  bucket = aws_s3_bucket.my_bucket.id
  status = "Enabled"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
