  bucket = aws_s3_bucket.log_bucket.id
  policy = data.aws_iam_policy_document.log_bucket_policy.json
}

# main.tf - Autograder Infrastructure for CS Class using AWS CodeBuild

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

# ------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------------------------------------------
variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "github_repo_url" {
  description = "Full HTTPS URL of the GitHub repository containing student code"
  type        = string
}

variable "github_branch" {
  description = "Branch to monitor and build"
  type        = string
  default     = "main"
}

variable "github_personal_access_token" {
  description = "GitHub personal access token for CodeBuild (sensitive)"
  type        = string
  sensitive   = true
}

# ------------------------------------------------------------------------------------------------------------------
# LOCAL VALUES
# ------------------------------------------------------------------------------------------------------------------
locals {
  name_prefix = "autograder-${var.environment}"
  common_tags = {
    Environment = var.environment
    Project     = "Autograder"
    ManagedBy   = "Terraform"
  }
  log_group_name = "/aws/codebuild/${local.name_prefix}"
}

# ------------------------------------------------------------------------------------------------------------------
# S3 BUCKET FOR BUILD ARTIFACTS AND RESULTS
# ------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "results" {
  bucket        = "${local.name_prefix}-results"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket                  = aws_s3_bucket.results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "results" {
  bucket = aws_s3_bucket.results.id
  rule {
    id     = "expire-old-objects"
    status = "Enabled"
    expiration {
      days = 90
    }
  }
}

# ------------------------------------------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP
# ------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = local.log_group_name
  retention_in_days = 30
  tags              = local.common_tags
}

# ------------------------------------------------------------------------------------------------------------------
# SECRETS MANAGER – GITHUB PERSONAL ACCESS TOKEN
# ------------------------------------------------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "github_token" {
  name        = "${local.name_prefix}-github-token"
  description = "GitHub personal access token for CodeBuild autograder"
  tags        = local.common_tags
}

resource "aws_secretsmanager_secret_version" "github_token" {
  secret_id     = aws_secretsmanager_secret.github_token.id
  secret_string = var.github_personal_access_token
}

# ------------------------------------------------------------------------------------------------------------------
# IAM ROLE FOR CODEBUILD
# ------------------------------------------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name               = "${local.name_prefix}-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

# ------------------------------------------------------------------------------------------------------------------
# IAM POLICY FOR CODEBUILD (LEAST PRIVILEGE)
# ------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codebuild" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject"
    ]
    resources = [
      aws_s3_bucket.results.arn,
      "${aws_s3_bucket.results.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      aws_cloudwatch_log_group.codebuild.arn,
      "${aws_cloudwatch_log_group.codebuild.arn}:*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      aws_secretsmanager_secret.github_token.arn
    ]
  }
}

resource "aws_iam_policy" "codebuild" {
  name        = "${local.name_prefix}-codebuild-policy"
  description = "Least-privilege policy for CodeBuild autograder"
  policy      = data.aws_iam_policy_document.codebuild.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "codebuild" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.codebuild.arn
}

# ------------------------------------------------------------------------------------------------------------------
# CODEBUILD PROJECT
# ------------------------------------------------------------------------------------------------------------------
resource "aws_codebuild_project" "autograder" {
  name         = local.name_prefix
  description  = "Autograder for CS class – runs student code from GitHub"
  service_role = aws_iam_role.codebuild.arn
  tags         = local.common_tags

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/standard:7.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = false

    environment_variable {
      name  = "RESULTS_BUCKET"
      value = aws_s3_bucket.results.id
    }
  }

  source {
    type            = "GITHUB"
    location        = var.github_repo_url
    git_clone_depth = 1
    buildspec       = "buildspec.yml"  # provided in the repository
    git_submodules_config {
      fetch_submodules = false
    }
    auth {
      type     = "SECRETS_MANAGER"
      resource = aws_secretsmanager_secret.github_token.arn
    }
    report_build_status = true
  }

  source_version = var.github_branch
}

# ------------------------------------------------------------------------------------------------------------------
# CODEBUILD WEBHOOK (triggers build on pushes to the configured branch)
# ------------------------------------------------------------------------------------------------------------------
resource "aws_codebuild_webhook" "autograder" {
  project_name = aws_codebuild_project.autograder.name
  build_type   = "BUILD"
  filter_group {
    filter {
      type    = "EVENT"
      pattern = "PUSH"
    }
    filter {
      type    = "HEAD_REF"
      pattern = "^refs/heads/${var.github_branch}$"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.30.0, < 5.100.0"
    }
  }
}

variable "github_token" {
  description = "GitHub personal access token for accessing student repositories"
  type        = string
  default     = "placeholder-token"
  sensitive   = true
}

variable "repo_url" {
  description = "GitHub repository URL for the autograder build source"
  type        = string
  default     = "https://github.com/placeholder/repo.git"
}

variable "branch" {
  description = "Git branch to use for the autograder build"
  type        = string
  default     = "main"
}

locals {
  common_tags = {
    Environment = "production"
    Project     = "cs-autograder"
    ManagedBy   = "terraform"
  }
  bucket_name    = "cs-autograder-results"
  log_group_name = "/aws/codebuild/cs-autograder"
  secret_name    = "github-token-autograder"
  project_name   = "cs-autograder"
  role_name      = "codebuild-autograder-role"
}

# ------------------------------------------------------------------------------
# S3 Bucket for Autograder Results
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "results" {
  bucket = local.bucket_name
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket                  = aws_s3_bucket.results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# CloudWatch Logs
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = local.log_group_name
  retention_in_days = 30
  tags              = local.common_tags
}

# ------------------------------------------------------------------------------
# Secrets Manager – GitHub Token
# ------------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "github_token" {
  name = local.secret_name
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "github_token" {
  secret_id     = aws_secretsmanager_secret.github_token.id
  secret_string = var.github_token
}

# ------------------------------------------------------------------------------
# IAM Role and Policy for CodeBuild
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = local.role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "codebuild" {
  # S3: PutObject on results bucket
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.results.arn,
      "${aws_s3_bucket.results.arn}/*"
    ]
  }

  # CloudWatch Logs: CreateLogGroup, CreateLogStream, PutLogEvents
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      aws_cloudwatch_log_group.codebuild.arn,
      "${aws_cloudwatch_log_group.codebuild.arn}:log-stream:*"
    ]
  }

  # Secrets Manager: GetSecretValue on the GitHub token secret
  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      aws_secretsmanager_secret.github_token.arn
    ]
  }

  # CodeBuild report actions (if test reports are used)
  statement {
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  role   = aws_iam_role.codebuild.name
  policy = data.aws_iam_policy_document.codebuild.json
}

# ------------------------------------------------------------------------------
# CodeBuild Project
# ------------------------------------------------------------------------------
resource "aws_codebuild_project" "autograder" {
  name         = local.project_name
  service_role = aws_iam_role.codebuild.arn
  tags         = local.common_tags

  source {
    type            = "GITHUB"
    location        = var.repo_url
    git_clone_depth = 1
    report_build_status = true
    auth {
      type     = "PERSONAL_ACCESS_TOKEN"
      resource = aws_secretsmanager_secret.github_token.arn
    }
  }

  source_version = var.branch

  artifacts {
    type = "S3"
    location = aws_s3_bucket.results.bucket
    path     = "/"
    namespace_type = "BUILD_ID"
    name     = "output.zip"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:5.0"
    type                        = "LINUX_CONTAINER"
    privileged_mode             = false
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild.name
      stream_name = "build-log"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "environment_name" {
  type        = string
  default     = "dev"
  description = "Deployment environment name (e.g. dev, staging, prod)"
}

variable "project_name" {
  type        = string
  default     = "Autograder"
  description = "Name of the project used in resource naming and tags"
}

variable "github_repo_url" {
  type        = string
  default     = "https://github.com/example/student-repo"
  description = "URL of the student's GitHub repository to clone and test"
}

variable "github_token" {
  type        = string
  sensitive   = true
  default     = ""
  description = "GitHub Personal Access Token used by CodeBuild to access the repository"
}

variable "grader_api_key" {
  type        = string
  sensitive   = true
  default     = ""
  description = "Optional API key for an external grading service"
}

variable "student_id" {
  type        = string
  default     = "student-001"
  description = "Unique identifier for the student submitting the assignment"
}

variable "assignment_name" {
  type        = string
  default     = "assignment-01"
  description = "Name of the assignment being graded"
}

variable "log_retention_days" {
  type        = number
  default     = 30
  description = "Number of days to retain CloudWatch Logs for CodeBuild builds"
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"
  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment_name
    Project     = var.project_name
    ManagedBy   = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET FOR AUTOGRADER RESULTS
# ------------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "autograder_results" {
  bucket        = "autograder-results-${random_id.bucket_suffix.hex}"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.autograder_results.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.autograder_results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    id     = "archive_old_results"
    status = "Enabled"

    transition {
      days          = 30
      storage_class = "GLACIER"
    }

    expiration {
      days = 365
    }
  }
}

# ------------------------------------------------------------------------------
# SECRETS MANAGER – GITHUB TOKEN
# ------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "github_token" {
  name = "${local.name_prefix}-github-token"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "github_token" {
  secret_id     = aws_secretsmanager_secret.github_token.id
  secret_string = var.github_token
}

# ------------------------------------------------------------------------------
# SECRETS MANAGER – GRADER API KEY (OPTIONAL)
# ------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "grader_api_key" {
  name = "${local.name_prefix}-grader-api-key"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "grader_api_key" {
  secret_id     = aws_secretsmanager_secret.grader_api_key.id
  secret_string = var.grader_api_key
}

# ------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/${local.name_prefix}-autograder"
  retention_in_days = var.log_retention_days
  tags              = local.common_tags
}

# ------------------------------------------------------------------------------
# IAM ROLE & POLICY FOR CODEBUILD
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_policy" {
  statement {
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.github_token.arn,
      aws_secretsmanager_secret.grader_api_key.arn,
    ]
  }

  statement {
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.autograder_results.arn}/*"]
  }

  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.codebuild.arn,
      "${aws_cloudwatch_log_group.codebuild.arn}:*",
    ]
  }
}

resource "aws_iam_role" "codebuild" {
  name               = "${local.name_prefix}-codebuild-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy" "codebuild" {
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild_policy.json
}

# ------------------------------------------------------------------------------
# CODEBUILD SOURCE CREDENTIAL (GITHUB PAT)
# ------------------------------------------------------------------------------

resource "aws_codebuild_source_credential" "github" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = var.github_token
}

# ------------------------------------------------------------------------------
# CODEBUILD PROJECT
# ------------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name         = "${local.name_prefix}-autograder"
  description  = "Builds and runs the autograder for student assignments"
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.autograder_results.bucket
    path     = "build-outputs/${var.student_id}/${var.assignment_name}"
    name     = "build-output.zip"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:7.0"
    type         = "LINUX_CONTAINER"

    environment_variable {
      name  = "STUDENT_ID"
      value = var.student_id
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "ASSIGNMENT_NAME"
      value = var.assignment_name
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "GITHUB_TOKEN"
      value = aws_secretsmanager_secret.github_token.arn
      type  = "SECRETS_MANAGER"
    }

    environment_variable {
      name  = "GRADER_API_KEY"
      value = aws_secretsmanager_secret.grader_api_key.arn
      type  = "SECRETS_MANAGER"
    }
  }

  source {
    type     = "GITHUB"
    location = var.github_repo_url
  }

  logs_config {
    cloudwatch_logs {
      status     = "ENABLED"
      group_name = aws_cloudwatch_log_group.codebuild.name
    }

    s3_logs {
      status = "DISABLED"
    }
  }

  tags = local.common_tags
}

# main.tf

# Random suffix for S3 bucket
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# S3 bucket for CodeBuild artifacts
resource "aws_s3_bucket" "codebuild_output" {
  bucket = "codebuild-artifacts-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role trust policy for CodeBuild
data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

# IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name               = "codebuild-artifacts-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

# IAM policy to allow CodeBuild to write/read build artifacts to/from the S3 bucket
data "aws_iam_policy_document" "codebuild_s3" {
  statement {
    actions = [
      "s3:PutObject",
      "s3:GetObject"
    ]
    resources = ["${aws_s3_bucket.codebuild_output.arn}/*"]
  }

  statement {
    actions = [
      "s3:GetBucketLocation"
    ]
    resources = [aws_s3_bucket.codebuild_output.arn]
  }
}

resource "aws_iam_policy" "codebuild_s3" {
  name   = "codebuild-artifacts-s3-access"
  policy = data.aws_iam_policy_document.codebuild_s3.json
}

resource "aws_iam_role_policy_attachment" "codebuild_s3" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_s3.arn
}

# CodeBuild project
resource "aws_codebuild_project" "student" {
  name         = "student-codebuild"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.codebuild_output.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }
}

# Data sources for dynamic metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# Random suffix for globally unique bucket name
resource "random_id" "autograder_bucket_suffix" {
  byte_length = 4
}

# VPC without internet gateway – no route to 0.0.0.0/0
resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = false
  tags = { Name = "autograder-vpc" }
}

# Two private subnets in different AZs
resource "aws_subnet" "autograder_private_subnet" {
  count             = 2
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = { Name = "autograder-private-subnet-${count.index + 1}" }
}

# Route table – only the local route (10.0.0.0/16) exists by default
resource "aws_route_table" "autograder_private_rt" {
  vpc_id = aws_vpc.autograder_vpc.id
  # No explicit route blocks – AWS automatically adds the local route
  tags = { Name = "autograder-private-rt" }
}

# Associate each private subnet with the private route table
resource "aws_route_table_association" "autograder_private" {
  count          = 2
  subnet_id      = aws_subnet.autograder_private_subnet[count.index].id
  route_table_id = aws_route_table.autograder_private_rt.id
}

# Security group for CodeBuild – only egress to VPC CIDR
resource "aws_security_group" "autograder_codebuild_sg" {
  name        = "codebuild-autograder-sg"
  description = "Security group for CodeBuild autograder – no internet egress"
  vpc_id      = aws_vpc.autograder_vpc.id

  egress {
    description = "Allow outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.autograder_vpc.cidr_block]
  }

  tags = { Name = "codebuild-autograder-sg" }
}

# S3 bucket for results and pre‑staged code
resource "aws_s3_bucket" "autograder_results" {
  bucket = "autograder-results-${random_id.autograder_bucket_suffix.hex}"

  lifecycle { prevent_destroy = true }

  tags = { Name = "autograder-results-bucket" }
}

# Enable versioning
resource "aws_s3_bucket_versioning" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id
  versioning_configuration { status = "Enabled" }
}

# Server‑side encryption with AES256
resource "aws_s3_bucket_server_side_encryption_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })

  tags = { Name = "codebuild-autograder-role" }
}

# IAM policy with least‑privilege permissions
resource "aws_iam_policy" "autograder_codebuild_policy" {
  name        = "codebuild-autograder-policy"
  description = "Least‑privilege policy for CodeBuild autograder"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # S3 read/write for source and artifacts
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*"
        ]
      },
      # CloudWatch Logs for build output
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/autograder-project",
          "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/autograder-project:*"
        ]
      },
      # EC2 networking – needed for VPC‑enabled CodeBuild
      {
        Effect = "Allow"
        Action = ["ec2:CreateNetworkInterface"]
        Resource = [
          "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:subnet/${aws_subnet.autograder_private_subnet[0].id}",
          "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:subnet/${aws_subnet.autograder_private_subnet[1].id}",
          "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:security-group/${aws_security_group.autograder_codebuild_sg.id}"
        ]
      },
      # Read and clean up network interfaces (scope to * is reasonable here)
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the CodeBuild role
resource "aws_iam_role_policy_attachment" "autograder_codebuild_attach" {
  role       = aws_iam_role.autograder_codebuild_role.name
  policy_arn = aws_iam_policy.autograder_codebuild_policy.arn
}

# CodeBuild project – runs in VPC with no internet egress
resource "aws_codebuild_project" "autograder_project" {
  name          = "autograder-project"
  description   = "Autograder for CS class – isolated in VPC"
  service_role  = aws_iam_role.autograder_codebuild_role.arn
  build_timeout = 5 # minutes

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.autograder_results.bucket
    name     = "build-output"
    path     = "/"
    packaging = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type     = "S3"
    location = aws_s3_bucket.autograder_results.bucket

    # Inline buildspec (placeholder – adapt for real autograder logic)
    buildspec = <<BUILDSPEC
version: 0.2
phases:
  build:
    commands:
      - echo "Running autograder..."
      # Student code is assumed to be in the source zip
  post_build:
    commands:
      - echo "Collecting results..."
      # Upload results to S3 (artifacts configuration handles this)
BUILDSPEC
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = aws_subnet.autograder_private_subnet[*].id
    security_group_ids = [aws_security_group.autograder_codebuild_sg.id]
  }

  tags = { Name = "autograder-project" }
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM VERSION & PROVIDERS
# ---------------------------------------------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.95.0, < 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------
locals {
  azs      = data.aws_availability_zones.available.names
  vpc_cidr = "10.0.0.0/16"
  tags = {
    Project     = "autograder"
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (Permitted static provider lookups)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# VPC – No Internet Gateway, No NAT Gateway, No public subnets
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "autograder-vpc" })
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIVATE SUBNETS (2 AZs)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, { Name = "autograder-private-subnet-${count.index + 1}" })
}

# ---------------------------------------------------------------------------------------------------------------------
# ROUTE TABLE & ASSOCIATIONS (Private)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "autograder-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC NETWORK ACL – Blocks all internet traffic, allows internal VPC traffic only
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.main.cidr_block
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.main.cidr_block
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.tags, { Name = "autograder-private-nacl" })
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUPS
# ---------------------------------------------------------------------------------------------------------------------
# Security group for VPC Interface Endpoints
resource "aws_security_group" "endpoints" {
  name   = "autograder-endpoints-sg"
  vpc_id = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow HTTPS to VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.tags
}

