resource "aws_iam_role_policy" "fetcher_lambda" {
  name   = "autograder-fetcher-lambda-policy"
  role   = aws_iam_role.fetcher_lambda_role.id
  policy = data.aws_iam_policy_document.fetcher_lambda_policy.json
}

# ---------------------------------------------------------------------------------------------------------------------
# LAMBDA FUNCTION: github_fetcher
# Fetches student code from GitHub, uploads to S3, triggers CodeBuild.
# No VPC configuration so it has internet access to reach GitHub.
# ---------------------------------------------------------------------------------------------------------------------
resource "local_file" "lambda_index" {
  content = <<EOF
import json
import os
import boto3
import urllib.request
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

secrets_client = boto3.client('secretsmanager')
s3_client = boto3.client('s3')
codebuild_client = boto3.client('codebuild')

def handler(event, context):
    logger.info(f"Received event: {json.dumps(event)}")

    token_secret_arn = os.environ.get('GITHUB_TOKEN_SECRET_ARN')
    source_bucket = os.environ.get('SOURCE_BUCKET')
    artifact_bucket = os.environ.get('ARTIFACT_BUCKET')
    codebuild_project = os.environ.get('CODEBUILD_PROJECT')

    # Extract repository information from the event payload
    repo_url = event.get('repository', {}).get('clone_url', 'https://github.com/example/repo.git')
    repo_branch = event.get('ref', 'refs/heads/main').split('/')[-1]

    # Retrieve GitHub personal access token from Secrets Manager
    try:
        secret_response = secrets_client.get_secret_value(SecretId=token_secret_arn)
        github_token = secret_response['SecretString']
    except Exception as e:
        logger.error(f"Failed to fetch GitHub token secret: {e}")
        raise e

    # Download the repository archive from GitHub
    archive_url = f"{repo_url.rstrip('.git')}/archive/refs/heads/{repo_branch}.zip"
    logger.info(f"Fetching archive from {archive_url}")

    req = urllib.request.Request(archive_url, headers={'Authorization': f'token {github_token}'})
    try:
        with urllib.request.urlopen(req) as response:
            zip_data = response.read()
    except Exception as e:
        logger.error(f"Failed to fetch GitHub archive: {e}")
        raise e

    # Upload the archive to the source S3 bucket
    s3_key = "source.zip"
    try:
        s3_client.put_object(Bucket=source_bucket, Key=s3_key, Body=zip_data)
        logger.info(f"Uploaded source to s3://{source_bucket}/{s3_key}")
    except Exception as e:
        logger.error(f"Failed to upload source to S3: {e}")
        raise e

    # Trigger the CodeBuild project to run the autograder
    try:
        response = codebuild_client.start_build(
            projectName=codebuild_project,
            environmentVariablesOverride=[
                {'name': 'SOURCE_BUCKET', 'value': source_bucket, 'type': 'PLAINTEXT'},
                {'name': 'SOURCE_KEY', 'value': s3_key, 'type': 'PLAINTEXT'},
                {'name': 'REPO_URL', 'value': repo_url, 'type': 'PLAINTEXT'},
                {'name': 'BRANCH', 'value': repo_branch, 'type': 'PLAINTEXT'},
            ]
        )
        logger.info(f"Started CodeBuild build: {response['build']['id']}")
    except Exception as e:
        logger.error(f"Failed to start CodeBuild: {e}")
        raise e

    return {
        'statusCode': 200,
        'body': json.dumps({'buildId': response['build']['id']})
    }
EOF
  filename = "${path.module}/index.py"
}

data "archive_file" "lambda_function" {
  depends_on = [local_file.lambda_index]

  type        = "zip"
  output_path = "${path.module}/lambda_function_payload.zip"
  source_file = "${path.module}/index.py"
}

resource "aws_lambda_function" "github_fetcher" {
  filename         = data.archive_file.lambda_function.output_path
  function_name    = "github_fetcher"
  role             = aws_iam_role.fetcher_lambda_role.arn
  handler          = "index.handler"
  runtime          = "python3.12"
  source_code_hash = data.archive_file.lambda_function.output_base64sha256

  environment {
    variables = {
      GITHUB_TOKEN_SECRET_ARN = aws_secretsmanager_secret.gh-token.arn
      SOURCE_BUCKET           = aws_s3_bucket.source.id
      ARTIFACT_BUCKET         = aws_s3_bucket.artifact.id
      CODEBUILD_PROJECT       = aws_codebuild_project.autograder.name
    }
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# CODEBUILD PROJECT: autograder
# Runs student code in the isolated private VPC. No internet access.
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_codebuild_project" "autograder" {
  name           = "autograder"
  description    = "CI build that executes student code in an isolated environment"
  service_role   = aws_iam_role.codebuild_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.artifact.bucket
    name     = "build-output.zip"
    packaging = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false
  }

  source {
    type     = "S3"
    location = "${aws_s3_bucket.source.bucket}/source.zip"
  }

  vpc_config {
    vpc_id             = aws_vpc.main.id
    subnets            = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.codebuild.id]
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild.name
      stream_name = "build-log-stream"
    }
  }

  tags = local.tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_prefix_list" "s3" {
  filter {
    name   = "prefix-list-name"
    values = ["com.amazonaws.${data.aws_region.current.name}.s3"]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC AND NETWORKING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = { Name = "autograder-vpc" }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = { Name = "autograder-private-subnet" }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = { Name = "autograder-private-rt" }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = [aws_route_table.private.id]

  tags = { Name = "autograder-s3-endpoint" }
}

resource "aws_security_group" "codebuild" {
  name        = "autograder-codebuild-sg"
  description = "Security group for CodeBuild, no internet access"
  vpc_id      = aws_vpc.main.id

  tags = { Name = "autograder-codebuild-sg" }
}

resource "aws_security_group_rule" "codebuild_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.codebuild.id
  description       = "Allow all outbound traffic to VPC CIDR (covers Interface Endpoints)"
}

resource "aws_security_group_rule" "codebuild_egress_s3" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  prefix_list_ids   = [data.aws_prefix_list.s3.id]
  security_group_id = aws_security_group.codebuild.id
  description       = "Allow HTTPS outbound to S3 via VPC Gateway Endpoint"
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "autograder-vpc-endpoints-sg"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.codebuild.id]
    description     = "Allow HTTPS from CodeBuild"
  }

  tags = { Name = "autograder-vpc-endpoints-sg" }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = { Name = "autograder-ecr-api-endpoint" }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = { Name = "autograder-ecr-dkr-endpoint" }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = { Name = "autograder-logs-endpoint" }
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 BUCKET FOR SOURCE CODE AND RESULTS
# ---------------------------------------------------------------------------------------------------------------------

resource "random_pet" "bucket_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_s3_bucket" "autograder" {
  bucket = "autograder-cs-${random_pet.bucket_suffix.id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "autograder" {
  bucket = aws_s3_bucket.autograder.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "autograder" {
  bucket = aws_s3_bucket.autograder.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "autograder" {
  bucket = aws_s3_bucket.autograder.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE AND POLICY FOR CODEBUILD
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild" {
  name               = "CodeBuildAutograderRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_policy" {
  statement {
    sid = "SourceCodeRead"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.autograder.arn,
      "${aws_s3_bucket.autograder.arn}/source_code/*",
    ]
    effect = "Allow"
  }

  statement {
    sid = "ResultsWrite"
    actions = [
      "s3:PutObject",
    ]
    resources = [
      "${aws_s3_bucket.autograder.arn}/results/*",
    ]
    effect = "Allow"
  }

  statement {
    sid = "ECRImagePull"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  statement {
    sid = "VPCNetworkInterface"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeVpcs",
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  statement {
    sid = "CloudWatchLogs"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/autograder-project:*",
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/autograder-project",
    ]
    effect = "Allow"
  }
}

resource "aws_iam_role_policy" "codebuild_s3" {
  name   = "CodeBuildS3AndNetworkPolicy"
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild_policy.json
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP FOR CODEBUILD
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/autograder-project"
  retention_in_days = 30
}

# ---------------------------------------------------------------------------------------------------------------------
# CODEBUILD PROJECT
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name         = "autograder-project"
  description  = "Autograder project for CS class"
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type      = "S3"
    location  = aws_s3_bucket.autograder.bucket
    path      = "results"
    name      = "autograder-result.zip"
    packaging = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "S3_BUCKET"
      value = aws_s3_bucket.autograder.bucket
    }
  }

  source {
    type     = "S3"
    location = "${aws_s3_bucket.autograder.bucket}/source_code/"
    buildspec = <<EOF
version: 0.2

phases:
  install:
    runtime-versions:
      python: 3.11
    commands:
      - echo "Installing dependencies..."
  build:
    commands:
      - echo "Autograder started at $(date)"
      - echo "Running student code in isolated environment..."
      - python3 autograder.py
    finally:
      - echo "Autograder finished at $(date)"
  post_build:
    commands:
      - echo "Storing results to S3..."
      - mkdir -p /tmp/results
      - cp -r results/* /tmp/results/ 2>/dev/null || echo "No results directory found"
      - echo "Grade and feedback prepared."

artifacts:
  files:
    - '**/*'
  base-directory: '/tmp/results'
  discard-paths: no
EOF
  }

  vpc_config {
    vpc_id             = aws_vpc.main.id
    subnets            = [aws_subnet.private.id]
    security_group_ids = [aws_security_group.codebuild.id]
  }

  tags = {
    Name = "autograder-codebuild"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.79.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  bucket_name = "codebuild-output-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

resource "aws_s3_bucket" "codebuild_output" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "CodeBuild Output"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "CodeBuild VPC"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "CodeBuild Subnet"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

resource "aws_security_group" "codebuild" {
  name        = "codebuild-sg"
  description = "Security group for CodeBuild project with no internet access"
  vpc_id      = aws_vpc.main.id

  # No ingress rules – all inbound traffic is blocked

  # Egress restricted to the VPC CIDR to block internet access
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "CodeBuild Security Group"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

resource "aws_iam_role" "codebuild" {
  name               = "codebuild-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json

  tags = {
    Name        = "CodeBuild Service Role"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_policy" {
  # Allow CodeBuild to write artifacts to the S3 bucket
  statement {
    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.codebuild_output.arn}/*",
    ]
  }

  statement {
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.codebuild_output.arn,
    ]
  }

  # Allow CodeBuild to create and manage CloudWatch Logs
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["*"]
  }

  # Allow CodeBuild to create ENIs in the VPC
  statement {
    effect = "Allow"

    actions = [
      "ec2:CreateNetworkInterface",
    ]

    resources = [
      "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:network-interface/*",
    ]

    condition {
      test     = "ArnEquals"
      variable = "ec2:Vpc"

      values = [
        aws_vpc.main.arn,
      ]
    }
  }

  statement {
    effect = "Allow"

    actions = [
      "ec2:CreateNetworkInterfacePermission",
    ]

    resources = [
      "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:network-interface/*",
    ]
  }

  # Allow CodeBuild to describe and delete VPC resources
  statement {
    effect = "Allow"

    actions = [
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeVpcs",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  name   = "codebuild-policy"
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild_policy.json
}

resource "aws_codebuild_project" "this" {
  name          = "student-code-build"
  description   = "CodeBuild project for students"
  service_role  = aws_iam_role.codebuild.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.codebuild_output.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
