  policy_arn = aws_iam_policy.lambda_s3_logs.arn
}

# Archive files for Lambda function code (placeholder)
data "archive_file" "upload_lambda" {
  type        = "zip"
  output_path = "${path.module}/upload_lambda_payload.zip"

  source {
    content = <<EOF
import json
import boto3
import base64

s3 = boto3.client('s3')
BUCKET = '${aws_s3_bucket.cat_pictures.bucket}'

def lambda_handler(event, context):
    # Upload logic – expects base64-encoded image in body
    if 'body' not in event:
        return {'statusCode': 400, 'body': json.dumps('No image data')}
    try:
        body = json.loads(event['body'])
        data = base64.b64decode(body['image'])
        key = 'uploads/' + str(context.aws_request_id) + '.jpg'
        s3.put_object(Bucket=BUCKET, Key=key, Body=data, ContentType='image/jpeg')
        return {'statusCode': 200, 'body': json.dumps({'message': 'Uploaded', 'url': f'https://{BUCKET}.s3.amazonaws.com/{key}'})}
    except Exception as e:
        return {'statusCode': 500, 'body': json.dumps(str(e))}
EOF
    filename = "lambda_function.py"
  }
}

data "archive_file" "get_random_lambda" {
  type        = "zip"
  output_path = "${path.module}/get_random_lambda_payload.zip"

  source {
    content = <<EOF
import json
import boto3
import random

s3 = boto3.client('s3')
BUCKET = '${aws_s3_bucket.cat_pictures.bucket}'

def lambda_handler(event, context):
    try:
        # List all objects in uploads/ and pick a random one
        objs = s3.list_objects_v2(Bucket=BUCKET, Prefix='uploads/')
        if 'Contents' not in objs or len(objs['Contents']) == 0:
            return {'statusCode': 404, 'body': json.dumps('No cat pictures found')}
        keys = [obj['Key'] for obj in objs['Contents']]
        chosen = random.choice(keys)
        url = s3.generate_presigned_url('get_object',
                                        Params={'Bucket': BUCKET, 'Key': chosen},
                                        ExpiresIn=3600)
        return {'statusCode': 200, 'body': json.dumps({'url': url})}
    except Exception as e:
        return {'statusCode': 500, 'body': json.dumps(str(e))}
EOF
    filename = "lambda_function.py"
  }
}

# Lambda Functions
resource "aws_lambda_function" "upload_cat" {
  filename         = data.archive_file.upload_lambda.output_path
  source_code_hash = data.archive_file.upload_lambda.output_base64sha256
  function_name    = "upload-cat"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  timeout          = 30

  environment {
    variables = {
      BUCKET = aws_s3_bucket.cat_pictures.bucket
    }
  }
}

resource "aws_lambda_function" "get_random_cat" {
  filename         = data.archive_file.get_random_lambda.output_path
  source_code_hash = data.archive_file.get_random_lambda.output_base64sha256
  function_name    = "get-random-cat"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  timeout          = 30

  environment {
    variables = {
      BUCKET = aws_s3_bucket.cat_pictures.bucket
    }
  }
}

# API Gateway REST API
resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = "cat-picture-api"
  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# API Resources
resource "aws_api_gateway_resource" "upload" {
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "upload"
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
}

resource "aws_api_gateway_resource" "random" {
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "random"
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
}

# API Methods
resource "aws_api_gateway_method" "upload_post" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.upload.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "random_get" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.random.id
  http_method   = "GET"
  authorization = "NONE"
}

# API Gateway integrations (AWS_PROXY)
resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id = aws_api_gateway_resource.upload.id
  http_method = aws_api_gateway_method.upload_post.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.upload_cat.invoke_arn
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id = aws_api_gateway_resource.random.id
  http_method = aws_api_gateway_method.random_get.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.get_random_cat.invoke_arn
}

# Lambda permissions to allow API Gateway invocation
resource "aws_lambda_permission" "upload_cat" {
  statement_id  = "AllowAPIGatewayUpload"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload_cat.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_picture_api.execution_arn}/*/*"
}

resource "aws_lambda_permission" "get_random_cat" {
  statement_id  = "AllowAPIGatewayRandom"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.get_random_cat.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_picture_api.execution_arn}/*/*"
}

# API Gateway deployment
resource "aws_api_gateway_deployment" "prod" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_rest_api.cat_picture_api.body,
      aws_api_gateway_resource.upload.id,
      aws_api_gateway_resource.random.id,
      aws_api_gateway_method.upload_post.id,
      aws_api_gateway_method.random_get.id,
      aws_api_gateway_integration.upload_integration.id,
      aws_api_gateway_integration.random_integration.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  stage_name = "prod"
}

# Output the base URL for the API
output "api_gateway_url" {
  value = aws_api_gateway_deployment.prod.invoke_url
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.84.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

# ----------------------------------------------------------------------
# Data sources – static provider metadata only
# ----------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "environment" {
  description = "Environment label for resource tagging"
  type        = string
  default     = "dev"
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  environment        = var.environment
  name_prefix        = "cat-pics-${local.environment}"
  cat_bucket_name    = "cat-images-${data.aws_caller_identity.current.account_id}-${local.environment}"
  lambda_bucket_name = "lambda-deployment-${data.aws_caller_identity.current.account_id}-${local.environment}"

  # Lambda zip file will be created by archive_file data source
  lambda_zip_path = "${path.module}/lambda.zip"
}

# ----------------------------------------------------------------------
# Archive file for Lambda code
# ----------------------------------------------------------------------
data "archive_file" "lambda" {
  type        = "zip"
  output_path = local.lambda_zip_path

  source {
    content  = <<-EOT
      import json
      import os
      import boto3
      import base64
      import random

      s3 = boto3.client('s3')
      bucket_name = os.environ['CAT_IMAGES_BUCKET']

      def lambda_handler(event, context):
          http_method = event.get('httpMethod', '')
          if http_method == 'POST':
              # Upload cat image
              body = json.loads(event.get('body', '{}'))
              image_data = base64.b64decode(body.get('image', ''))
              key = f"cats/{random.randint(0, 999999)}.jpg"
              s3.put_object(Bucket=bucket_name, Key=key, Body=image_data)
              return {'statusCode': 200, 'body': json.dumps({'key': key})}
          elif http_method == 'GET':
              # Return random cat image URL
              response = s3.list_objects_v2(Bucket=bucket_name, Prefix='cats/')
              keys = [obj['Key'] for obj in response.get('Contents', [])]
              if not keys:
                  return {'statusCode': 404, 'body': json.dumps({'error': 'No cats found'})}
              key = random.choice(keys)
              url = s3.generate_presigned_url('get_object', Params={'Bucket': bucket_name, 'Key': key})
              return {'statusCode': 200, 'body': json.dumps({'url': url})}
          return {'statusCode': 400, 'body': json.dumps({'error': 'Unsupported method'})}
    EOT
    filename = "index.py"
  }
}

# ----------------------------------------------------------------------
# S3 bucket – Cat Images (with versioning and encryption)
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "cat_images" {
  bucket = local.cat_bucket_name
  tags = {
    Name        = local.cat_bucket_name
    Environment = local.environment
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cat_images" {
  bucket                  = aws_s3_bucket.cat_images.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cat_images" {
