  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_images" {
  bucket = aws_s3_bucket.cat_images.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ----------------------------------------------------------------------
# S3 bucket – Lambda deployment (no versioning, no prevent_destroy)
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "lambda_deployment" {
  bucket = local.lambda_bucket_name
  tags = {
    Name        = local.lambda_bucket_name
    Environment = local.environment
  }
}

resource "aws_s3_bucket_public_access_block" "lambda_deployment" {
  bucket                  = aws_s3_bucket.lambda_deployment.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lambda_deployment" {
  bucket = aws_s3_bucket.lambda_deployment.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ----------------------------------------------------------------------
# IAM Role for Lambda
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${local.name_prefix}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags = {
    Environment = local.environment
  }
}

resource "aws_iam_role_policy_attachment" "lambda_exec_basic" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# ----------------------------------------------------------------------
# Custom IAM policy for S3 access
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_s3_access" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject"
    ]
    resources = ["${aws_s3_bucket.cat_images.arn}/*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.cat_images.arn]
  }
}

resource "aws_iam_role_policy" "lambda_s3_access" {
  name   = "${local.name_prefix}-s3-access"
  role   = aws_iam_role.lambda_exec.name
  policy = data.aws_iam_policy_document.lambda_s3_access.json
}

# ----------------------------------------------------------------------
# Lambda function
# ----------------------------------------------------------------------
resource "aws_lambda_function" "cat_pics" {
  function_name = "cat-pics-${local.environment}"
  role          = aws_iam_role.lambda_exec.arn
  runtime       = "python3.12"
  handler       = "index.lambda_handler"
  timeout       = 30
  memory_size   = 128

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  environment {
    variables = {
      CAT_IMAGES_BUCKET = aws_s3_bucket.cat_images.id
    }
  }

  tags = {
    Environment = local.environment
  }
}

# ----------------------------------------------------------------------
# API Gateway – REST API
# ----------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "cat_api" {
  name        = "${local.name_prefix}-api"
  description = "Cat Pictures Upload and Random API"
  tags = {
    Environment = local.environment
  }
}

# ---- /upload resource ----
resource "aws_api_gateway_resource" "upload" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  parent_id   = aws_api_gateway_rest_api.cat_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_post" {
