        Resource = aws_dynamodb_table.cat_metadata.arn
      }
    ]
  })
}

# Lambda function source code (upload)
locals {
  upload_lambda_code = <<-EOF
import json
import uuid
import boto3
import base64
import os

s3 = boto3.client('s3')
dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])
bucket = os.environ['BUCKET_NAME']

def handler(event, context):
    try:
        if event.get('isBase64Encoded', False):
            body = base64.b64decode(event['body'])
        else:
            body = event['body'].encode()

        image_id = str(uuid.uuid4())
        s3.put_object(Bucket=bucket, Key=image_id, Body=body)
        table.put_item(Item={'id': image_id})
        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'text/plain'},
            'body': image_id
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': str(e)
        }
EOF

  random_lambda_code = <<-EOF
import json
import random
import boto3
import base64
import os

s3 = boto3.client('s3')
dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])
bucket = os.environ['BUCKET_NAME']

def handler(event, context):
    try:
        response = table.scan(Select='SPECIFIC_ATTRIBUTES', AttributesToGet=['id'])
        items = response.get('Items', [])
        if not items:
            return {'statusCode': 404, 'body': 'No cats found'}
        item = random.choice(items)
        image_id = item['id']
        obj = s3.get_object(Bucket=bucket, Key=image_id)
        image_data = obj['Body'].read()
        return {
            'statusCode': 200,
            'headers': {
                'Content-Type': 'image/jpeg',
                'Content-Length': str(len(image_data))
            },
            'body': base64.b64encode(image_data).decode('utf-8'),
            'isBase64Encoded': True
        }
    except Exception as e:
        return {'statusCode': 500, 'body': str(e)}
EOF
}

