locals {
  vpc_cidr        = "10.0.0.0/16"
  subnet_cidr     = "10.0.1.0/24"
  instance_type   = "t2.micro"
  ssh_cidr        = "0.0.0.0/0"
  project_name    = "backup-demo"
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "this" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }
}

# TLS key pair (generated, avoids file dependency)
resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# AWS key pair from the generated public key
resource "aws_key_pair" "this" {
  key_name   = "${local.project_name}-key"
  public_key = tls_private_key.this.public_key_openssh
}

# Networking
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.project_name}-vpc"
  }
}

resource "aws_subnet" "this" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true
  tags = {
    Name = "${local.project_name}-subnet"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "${local.project_name}-igw"
  }
}

resource "aws_route_table" "this" {
  vpc_id = aws_vpc.this.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }
  tags = {
    Name = "${local.project_name}-route-table"
  }
}

resource "aws_route_table_association" "this" {
  subnet_id      = aws_subnet.this.id
  route_table_id = aws_route_table.this.id
}

# Security group
resource "aws_security_group" "this" {
  name   = "${local.project_name}-sg"
  vpc_id = aws_vpc.this.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.project_name}-sg"
  }
}

# EC2 instance
resource "aws_instance" "this" {
  ami                    = data.aws_ami.this.id
  instance_type          = local.instance_type
  key_name               = aws_key_pair.this.key_name
  subnet_id              = aws_subnet.this.id
  vpc_security_group_ids = [aws_security_group.this.id]
  associate_public_ip_address = true
  tags = {
    Name = "${local.project_name}-ec2"
  }
}

# Backup vault
resource "aws_backup_vault" "this" {
  name = "${local.project_name}-backup-vault"
  tags = {
    Name = "${local.project_name}-backup-vault"
  }
}

# IAM role for Backup service
resource "aws_iam_role" "backup" {
  name = "AWSBackupServiceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup plan
resource "aws_backup_plan" "this" {
  name = "${local.project_name}-backup-plan"

  rule {
    rule_name         = "daily-midnight"
    target_vault_name = aws_backup_vault.this.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    resource_type   = "EC2"
    backup_options  = {}
  }

  tags = {
    Name = "${local.project_name}-backup-plan"
  }
}

# Backup selection – selects the EC2 instance
resource "aws_backup_selection" "this" {
  name         = "${local.project_name}-backup-selection"
  plan_id      = aws_backup_plan.this.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = [aws_instance.this.arn]
}

terraform {
  required_providers {
    archive = {
      source = "hashicorp/archive"
    }
  }
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function_payload.zip"

  source_content = <<EOF
import logging
logger = logging.getLogger()
logger.setLevel(logging.INFO)

def lambda_handler(event, context):
    logger.info("Scheduled Lambda executed successfully")
    return {"statusCode": 200, "body": "OK"}
EOF
  source_content_filename = "lambda_function.py"
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_exec_role_attach" {
  role       = aws_iam_role.lambda_exec_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "scheduled_code_runner" {
  function_name = "scheduled_code_runner"
  role          = aws_iam_role.lambda_exec_role.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"
  filename      = data.archive_file.lambda_zip.output_path
}

resource "aws_cloudwatch_event_rule" "daily_7_utc" {
  name                = "daily_7_utc"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule = aws_cloudwatch_event_rule.daily_7_utc.name
  arn  = aws_lambda_function.scheduled_code_runner.arn
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.scheduled_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_7_utc.arn
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.90.0, < 5.100.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Generate a unique suffix for the S3 bucket name
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# Create S3 bucket for Lambda deployment package
resource "aws_s3_bucket" "lambda_code" {
  bucket        = "lambda-code-bucket-${random_id.bucket_suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable server-side encryption using AES256
resource "aws_s3_bucket_server_side_encryption_configuration" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Enable versioning to protect the deployment package
resource "aws_s3_bucket_versioning" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Archive the Lambda source code
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function.zip"

  source {
    content  = <<EOF
import json
import logging

logger = logging.getLogger()
logger.setLevel(logging.INFO)

def lambda_handler(event, context):
    logger.info("Daily job executed successfully")
    return {
        'statusCode': 200,
        'body': json.dumps('Job completed')
    }
EOF
    filename = "lambda_function.py"
  }
}

# Upload the zip archive to S3
resource "aws_s3_object" "lambda_code_upload" {
  bucket = aws_s3_bucket.lambda_code.id
  key    = "lambda_function.zip"
  source = data.archive_file.lambda_zip.output_path
  etag   = filemd5(data.archive_file.lambda_zip.output_path)
}

# IAM trust policy for Lambda
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# IAM role for Lambda execution
resource "aws_iam_role" "lambda_exec" {
  name               = "lambda_exec_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

# IAM policy for basic CloudWatch Logs permissions
data "aws_iam_policy_document" "lambda_basic_exec" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["arn:aws:logs:*:*:*"]
  }
}

resource "aws_iam_policy" "lambda_basic_exec" {
  name   = "lambda_basic_exec_policy"
  policy = data.aws_iam_policy_document.lambda_basic_exec.json
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "lambda_basic_exec_attach" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_basic_exec.arn
}

# Lambda function
resource "aws_lambda_function" "daily_job" {
  function_name = "daily_job_lambda"
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"
  timeout       = 120

  s3_bucket = aws_s3_bucket.lambda_code.id
  s3_key    = aws_s3_object.lambda_code_upload.key

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_exec_attach,
    aws_s3_object.lambda_code_upload,
  ]
}

# CloudWatch Log Group for Lambda logs
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${aws_lambda_function.daily_job.function_name}"
  retention_in_days = 14

  lifecycle {
    prevent_destroy = true
  }
}

# EventBridge rule to trigger at 7 AM UTC daily
resource "aws_cloudwatch_event_rule" "daily_7am" {
  name                = "daily_7am_rule"
  schedule_expression = "cron(0 7 * * ? *)"
  state               = "ENABLED"
}

# Target the Lambda function from the EventBridge rule
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule = aws_cloudwatch_event_rule.daily_7am.name
  arn  = aws_lambda_function.daily_job.arn
}

# Grant EventBridge permission to invoke the Lambda function
resource "aws_lambda_permission" "allow_eventbridge_invoke" {
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_7am.arn
}

