      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (must be in different AZs)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access the RDS instance on port 5432"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.3"
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage in GB for the RDS instance"
  type        = number
  default     = 20
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  type        = string
  default     = "mydb"
}

variable "master_username" {
  description = "Master username for PostgreSQL"
  type        = string
  default     = "dbadmin"
}

variable "project_name" {
  description = "Project name used for resource tagging"
  type        = string
  default     = "myproject"
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "myproject"
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Local values
# ---------------------------------------------------------------------------
locals {
  # DB parameter group parameters
  pg_parameters = [
    {
      name         = "log_connections"
      value        = "1"
      apply_method = "pending-reboot"
    },
    {
      name         = "log_disconnections"
      value        = "1"
      apply_method = "pending-reboot"
    },
  ]
}

# ---------------------------------------------------------------------------
# VPC and subnets
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.project_name}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.project_name}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# KMS key for RDS encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "rds" {
  description         = "KMS key for encrypting RDS PostgreSQL instance"
  key_usage           = "ENCRYPT_DECRYPT"
  is_enabled          = true
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })

  tags = merge(var.tags, {
    Name = "${var.project_name}-rds-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.project_name}-rds-key"
  target_key_id = aws_kms_key.rds.key_id
}

# ---------------------------------------------------------------------------
# DB parameter group
# ---------------------------------------------------------------------------
resource "aws_db_parameter_group" "postgres" {
  name        = "${var.project_name}-postgres-pg"
  family      = "postgres15"
  description = "Custom parameter group for ${var.project_name} PostgreSQL instance"

  dynamic "parameter" {
    for_each = local.pg_parameters
    content {
      name         = parameter.value.name
      value        = parameter.value.value
      apply_method = parameter.value.apply_method
    }
  }

  tags = merge(var.tags, {
    Name = "${var.project_name}-postgres-pg"
  })
}

# ---------------------------------------------------------------------------
# DB subnet group
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "postgres" {
  name        = "${var.project_name}-db-subnet-group"
  description = "DB subnet group for ${var.project_name} PostgreSQL instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(var.tags, {
    Name = "${var.project_name}-db-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Security group for RDS
# ---------------------------------------------------------------------------
resource "aws_security_group" "rds" {
  name        = "${var.project_name}-rds-sg"
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL traffic from allowed CIDR blocks"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.project_name}-rds-sg"
  })
}

# ---------------------------------------------------------------------------
# Random password for master user
# ---------------------------------------------------------------------------
resource "random_password" "rds_master" {
  length      = 16
  special     = true
  upper       = true
  lower       = true
  number      = true
  override_special = "!@#$%^&*()-_=+[]{}<>?"
}

# ---------------------------------------------------------------------------
# Secrets Manager secret for master credentials
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "rds" {
  name        = "${var.project_name}-rds-master-password"
  description = "Master password for ${var.project_name} PostgreSQL instance"

  tags = merge(var.tags, {
    Name = "${var.project_name}-rds-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "rds_password" {
  secret_id = aws_secretsmanager_secret.rds.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.rds_master.result
  })
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL instance
# ---------------------------------------------------------------------------
resource "aws_db_instance" "postgres" {
  engine               = "postgres"
  engine_version       = var.engine_version
  instance_class       = var.instance_class
  allocated_storage    = var.allocated_storage
  storage_type         = "gp3"
  db_name              = var.db_name
  username             = var.master_username
  password             = random_password.rds_master.result
  multi_az             = true
  storage_encrypted    = true
  kms_key_id          = aws_kms_key.rds.arn
  backup_retention_period = 7
  deletion_protection  = true
  skip_final_snapshot  = false
  final_snapshot_identifier = "${var.project_name}-rds-final"

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  parameter_group_name   = aws_db_parameter_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = merge(var.tags, {
    Name = "${var.project_name}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

locals {
  name_prefix = "rds-postgres"
  common_tags = {
    Name        = local.name_prefix
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-subnet-${count.index}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-consolepolicy-3"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "Allow use of the key for RDS"
        Effect    = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_parameter_group" "postgres" {
  name        = "${local.name_prefix}-pg"
  family      = "postgres15"
  description = "Custom parameter group for PostgreSQL 15 with SSL enforcement"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-param-group" })
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-sg" })
}

resource "aws_db_subnet_group" "rds" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for PostgreSQL RDS instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

resource "aws_db_instance" "postgres" {
  identifier = local.name_prefix

  engine                       = "postgres"
  engine_version               = "15"
  instance_class               = "db.t3.medium"
  allocated_storage            = 50
  storage_type                 = "gp3"
  multi_az                     = true
  publicly_accessible          = false
  deletion_protection          = true
  skip_final_snapshot          = false
  backup_retention_period      = 7
  copy_tags_to_snapshot        = true

  parameter_group_name         = aws_db_parameter_group.postgres.name
  vpc_security_group_ids       = [aws_security_group.rds.id]
  db_subnet_group_name         = aws_db_subnet_group.rds.name

  username                     = "postgres"
  manage_master_user_password  = true

  kms_key_id                   = aws_kms_key.rds.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-instance" })

  lifecycle {
    prevent_destroy = true
  }
}

variable "vpc_cidr" {
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC"
}

variable "db_storage" {
  default     = 20
  description = "Allocated storage for the RDS instance (GB)"
}

variable "db_engine_version" {
  default     = "16.2"
  description = "PostgreSQL engine version"
}

variable "identifier" {
  default     = "secure-postgres"
  description = "Identifier for the RDS instance and associated resources"
}

variable "db_name" {
  default     = "appdb"
  description = "Name of the initial PostgreSQL database"
}

variable "db_username" {
  default     = "dbadmin"
  description = "Master username for the RDS instance"
}

locals {
  common_tags = {
    Environment = "production"
    Project     = "SecurePostgres"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

terraform {
  required_providers {
    random = {
      source = "hashicorp/random"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "postgres-vpc" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "private-subnet-${count.index + 1}" })
}

resource "aws_db_subnet_group" "main" {
  name       = "main-subnet-group-${var.identifier}"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.common_tags
}

resource "aws_db_parameter_group" "main" {
  name   = "pgsql-params-${var.identifier}"
  family = "postgres16"
  tags   = local.common_tags
}

resource "aws_security_group" "rds" {
  name        = "rds-sg-${var.identifier}"
  vpc_id      = aws_vpc.main.id
  description = "Security group for PostgreSQL RDS"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow RDS to use key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-${var.identifier}"
  target_key_id = aws_kms_key.rds.key_id
}

resource "random_password" "db_master_password" {
  length  = 20
  special = false
}

resource "aws_secretsmanager_secret" "db_master" {
  name = "rds-master-password-${var.identifier}"
  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id     = aws_secretsmanager_secret.db_master.id
  secret_string = random_password.db_master_password.result
}

resource "aws_db_instance" "main" {
  identifier     = var.identifier
  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = "db.t3.micro"

  allocated_storage     = var.db_storage
  storage_type          = "gp2"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn
  copy_tags_to_snapshot = true

  db_name                        = var.db_name
  username                       = var.db_username
  password                       = aws_secretsmanager_secret_version.db_master.secret_string
  db_subnet_group_name           = aws_db_subnet_group.main.name
  vpc_security_group_ids         = [aws_security_group.rds.id]
  parameter_group_name           = aws_db_parameter_group.main.name
  backup_retention_period        = 7
  backup_window                  = "03:00-04:00"
  maintenance_window             = "sun:04:00-sun:05:00"
  multi_az                       = true
  auto_minor_version_upgrade     = true
  skip_final_snapshot            = false
  final_snapshot_identifier      = "${var.identifier}-final-snapshot"
  deletion_protection            = false

  tags = merge(local.common_tags, { Name = var.identifier })

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  common_tags = {
    Environment = "Production"
    Project     = "PostgreSQL"
    ManagedBy   = "Terraform"
  }
  vpc_cidr = "10.0.0.0/16"
  azs      = data.aws_availability_zones.available.names
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow RDS to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["rds.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "random_password" "master" {
  length           = 16
  special          = false
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "master" {
  name       = "rds-master-password-${random_password.master.result}"
  tags       = local.common_tags
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id     = aws_secretsmanager_secret.master.id
  secret_string = random_password.master.result
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.common_tags, { Name = "postgresql-vpc" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone = local.azs[count.index]
  tags              = merge(local.common_tags, { Name = "private-subnet-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "private-route-table" })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS PostgreSQL encryption"
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-postgresql-key"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_parameter_group" "postgres" {
  name   = "postgresql-params"
  family = "postgres16"
  parameter {
    name  = "log_statement"
    value = "ddl"
  }
  tags = local.common_tags
}

resource "aws_security_group" "rds" {
  name        = "rds-postgresql-sg"
  description = "Security group for RDS PostgreSQL instance"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_db_subnet_group" "main" {
  name       = "postgresql-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.common_tags
}

resource "aws_db_instance" "postgres" {
  identifier                = "postgresql-db"
  engine                    = "postgres"
  engine_version            = "16.1"
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  storage_type              = "gp2"
  db_name                   = "postgresdb"
  username                  = "dbadmin"
  password                  = random_password.master.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  parameter_group_name      = aws_db_parameter_group.postgres.name
  multi_az                  = true
  storage_encrypted         = true
  kms_key_id                = aws_kms_key.rds.arn
  final_snapshot_identifier = "pgsnapshot"
  skip_final_snapshot       = false
  backup_retention_period   = 7
  backup_window             = "03:00-04:00"
  maintenance_window        = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade = true
  tags                      = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# main.tf - Airbyte Connector Test PostgreSQL RDS Instance

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "ingress_cidr_blocks" {
  description = "CIDR block(s) allowed to connect to PostgreSQL (port 5432)"
  type        = string
  default     = "0.0.0.0/0"
}

variable "project" {
  description = "Project name for tagging"
  type        = string
  default     = "airbyte-connector-test"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

locals {
  common_tags = {
    Name        = "${var.project}-rds"
    Environment = var.environment
    Project     = var.project
  }
  final_snapshot_id = "airbyte-postgresql-final-${random_id.snapshot.hex}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Random password for the RDS master user
resource "random_password" "rds" {
  length           = 16
  special          = true
  override_special = "_%@"
}

# Unique identifier for the final snapshot
resource "random_id" "snapshot" {
  byte_length = 4
}

# Secrets Manager secret to store the master credentials
resource "aws_secretsmanager_secret" "rds" {
  name_prefix             = "${var.project}-rds-password-"
  description             = "Master password for Airbyte RDS PostgreSQL instance"
  recovery_window_in_days = 0
  tags                    = local.common_tags
}

# Secret version containing username and password
resource "aws_secretsmanager_secret_version" "rds" {
  secret_id     = aws_secretsmanager_secret.rds.id
  secret_string = jsonencode({
    username = "airbyte"
    password = random_password.rds.result
  })
}

# Data source to read the secret back (as required by the specifications)
data "aws_secretsmanager_secret_version" "rds" {
  secret_id     = aws_secretsmanager_secret.rds.id
  version_stage = "AWSCURRENT"
  depends_on    = [aws_secretsmanager_secret_version.rds]
}

# VPC with DNS support
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.common_tags, { Name = "${var.project}-vpc" })
}

# Internet gateway for public subnet connectivity
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${var.project}-igw" })
}

# Public subnets in different availability zones
resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(local.common_tags, { Name = "${var.project}-public-subnet-${count.index}" })
}

# Public route table with default route to internet gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.common_tags, { Name = "${var.project}-public-rt" })
}

# Associate public subnets with the route table
resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security group allowing inbound PostgreSQL access and all outbound
resource "aws_security_group" "rds" {
  name_prefix = "${var.project}-rds-sg-"
  description = "Security group for Airbyte RDS PostgreSQL instance"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.ingress_cidr_blocks]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

# DB subnet group using the public subnets
resource "aws_db_subnet_group" "rds" {
  name_prefix = "${var.project}-rds-subnet-group-"
  subnet_ids  = aws_subnet.public[*].id
  tags        = local.common_tags
}

# DB parameter group for PostgreSQL 15 (default parameters)
resource "aws_db_parameter_group" "rds" {
  name_prefix = "${var.project}-rds-pg-"
  family      = "postgres15"
  description = "Parameter group for Airbyte PostgreSQL 15 RDS"
  tags        = local.common_tags
}

# RDS PostgreSQL 15 instance
resource "aws_db_instance" "rds" {
  identifier             = "${var.project}-postgresql"
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = var.instance_class
  allocated_storage      = var.allocated_storage
  storage_type           = "gp3"
  storage_encrypted      = true
  username               = "airbyte"
  password               = jsondecode(data.aws_secretsmanager_secret_version.rds.secret_string)["password"]
  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.rds.name
  backup_retention_period = 7
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:00-sun:05:00"
  publicly_accessible    = true
  deletion_protection    = true
  skip_final_snapshot    = false
  final_snapshot_identifier = local.final_snapshot_id
  tags                   = merge(local.common_tags, { Name = "${var.project}-postgresql" })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  db_username          = "airbyte"
  db_port              = 5432
  allowed_ingress_cidr = "10.0.0.0/16"  # Secure default; override as needed
  name_prefix          = "airbyte-rds-test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "${local.name_prefix}-db-subnet-group"
  }
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Security group for Airbyte RDS PostgreSQL instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [local.allowed_ingress_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-rds-sg"
  }
}

resource "aws_db_parameter_group" "postgres15" {
  name        = "${local.name_prefix}-postgres15-params"
  family      = "postgres15"
  description = "Custom parameter group for Airbyte PostgreSQL 15 instance"

  parameter {
    name  = "statement_timeout"
    value = "300000"
  }

  parameter {
    name  = "idle_in_transaction_session_timeout"
    value = "600000"
  }

  tags = {
    Name = "${local.name_prefix}-postgres15-params"
  }
}

resource "random_password" "master" {
  length  = 16
  special = false
}

resource "aws_secretsmanager_secret" "rds_master" {
  name        = "${local.name_prefix}-rds-master-password"
  description = "Master password for Airbyte PostgreSQL RDS instance"
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.master.result
  })
}

resource "aws_db_instance" "postgres" {
  identifier = "${local.name_prefix}-postgres"

  engine                      = "postgres"
  engine_version              = "15"
  parameter_group_name        = aws_db_parameter_group.postgres15.name
  db_subnet_group_name        = aws_db_subnet_group.main.name
  vpc_security_group_ids      = [aws_security_group.rds.id]

  username                   = local.db_username
  password                   = random_password.master.result

  instance_class             = "db.t3.micro"
  allocated_storage          = 5
  storage_type               = "gp2"
  storage_encrypted          = true
  publicly_accessible        = true
  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  deletion_protection        = true
  skip_final_snapshot        = false
  apply_immediately          = false

  tags = {
    Name = "${local.name_prefix}-postgres"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "allowed_cidr_block" {
  description = "CIDR block allowed to connect to RDS on port 5432"
