  default     = "0.0.0.0/0"
}

variable "db_name" {
  description = "Name of the database to create"
  type        = string
  default     = "airbyte"
}

variable "db_username" {
  description = "Master username for the RDS instance"
  type        = string
  default     = "airbyte"
}

# Tags
locals {
  common_tags = {
    Environment = "test"
