  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "public-access-db-subnet-group"
  }
}

resource "aws_security_group" "public_access" {
  name        = "public-access-sg"
  description = "Security group for publicly accessible MySQL RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL access from the internet"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-access-sg"
  }
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS storage encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "public-access-rds-kms-key"
  }
}

resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!@#$%"
}

resource "aws_secretsmanager_secret" "db_creds" {
  name = "public-access-rds-credentials"

  tags = {
    Name = "public-access-rds-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id = aws_secretsmanager_secret.db_creds.id

  secret_string = jsonencode({
    username = "admin"
    password = random_password.master.result
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
  })
}

resource "aws_db_instance" "main" {
  identifier = "public-access-mysql-db"

  engine         = "mysql"
  engine_version = "5.7"
  instance_class = "db.t3.micro"

  allocated_storage = 200
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  db_name  = "mydb"
  username = "admin"
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.public_access.id]

  publicly_accessible      = true
  skip_final_snapshot      = false
  final_snapshot_identifier = "${aws_db_instance.main.identifier}-final"

  backup_retention_period = 7
  deletion_protection     = true

  tags = {
    Name = "mysql-db-instance"
  }

  lifecycle {
    prevent_destroy = true
  }
}

