  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_security_group" "db" {
  name        = "db-security-group"
  description = "Security group for PostgreSQL DB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-security-group"
  }
}

resource "random_password" "db_password" {
  length  = 16
  special = true
}

resource "aws_secretsmanager_secret" "db_password" {
  name = "db-password-secret"
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db_password.result
}

resource "aws_db_instance" "postgres" {
  identifier = "postgres-db"

  engine         = "postgres"
  engine_version = "15.4"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "mydb"
  username = var.db_username
  password = random_password.db_password.result

  port = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.id
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  allow_major_version_upgrade = true
  auto_minor_version_upgrade  = true

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  multi_az                = false
  skip_final_snapshot     = false
  final_snapshot_identifier = "postgres-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "postgres-db"
  }
}

resource "aws_db_option_group" "option_group_pike" {
  name                 = "option-group-pike"
  engine_name          = "sqlserver-ee"
  major_engine_version = "11"

  option_group_description = "Option group for sqlserver-ee engine version 11"

  tags = {
    Name = "option-group-pike"
  }
}

resource "aws_db_option_group" "option_group_pike" {
  name                 = "option-group-pike"
  engine_name          = "sqlserver-ee"
  major_engine_version = "11"

  option {
    option_name = "SQLSERVER_AUDIT"
  }

  option {
    option_name = "TDE"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# IAM role for RDS to write audit logs to S3
data "aws_iam_policy_document" "rds_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "audit_logs_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.audit_logs.arn,
      "${aws_s3_bucket.audit_logs.arn}/*"
    ]
  }
}

resource "aws_iam_role" "rds_audit_role" {
  name               = "rds-sqlserver-audit-role"
  assume_role_policy = data.aws_iam_policy_document.rds_assume_role.json
}

resource "aws_iam_role_policy" "audit_logs" {
  role   = aws_iam_role.rds_audit_role.name
  policy = data.aws_iam_policy_document.audit_logs_policy.json
}

# Random suffix for the audit S3 bucket
resource "random_pet" "audit_suffix" {
  length    = 2
  separator = "-"
}

# S3 bucket for SQL Server audit logs
resource "aws_s3_bucket" "audit_logs" {
  bucket = "pike-audit-logs-${random_pet.audit_suffix.id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# RDS option group
resource "aws_db_option_group" "pike" {
  name                     = "option-group-pike"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11"
  option_group_description = "Option group for SQL Server EE with audit and TDE"

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "IAM_ROLE_ARN"
      value = aws_iam_role.rds_audit_role.arn
    }

    option_settings {
      name  = "S3_BUCKET_ARN"
      value = aws_s3_bucket.audit_logs.arn
    }
  }

  option {
    option_name = "TDE"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.70.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "env_name" {
  type    = string
  default = "dev"
}

variable "project" {
  type    = string
  default = "MyProject"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "aurora_instance_class" {
  type    = string
  default = "db.r5.large"
}

variable "db_master_username" {
  type    = string
  default = "dbadmin"
}

variable "db_cluster_identifier" {
  type    = string
  default = "my-aurora-cluster"
}

variable "engine_version" {
  type    = string
  default = "8.0.mysql_aurora.3.02.0"
}

locals {
  common_tags = {
    Environment = var.env_name
    Project     = var.project
  }
  skip_final_snapshot = var.env_name == "dev" ? true : false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${var.env_name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, {
    Name = "${var.env_name}-private-subnet-${count.index}"
  })
}

resource "aws_db_subnet_group" "aurora" {
  name       = "${var.env_name}-aurora-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = merge(local.common_tags, {
    Name = "${var.env_name}-aurora-subnet-group"
  })
}

resource "aws_security_group" "proxy" {
  name        = "${var.env_name}-rds-proxy-sg"
  description = "Security group for RDS Proxy"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${var.env_name}-rds-proxy-sg"
  })
}

resource "aws_security_group" "aurora" {
  name        = "${var.env_name}-aurora-sg"
  description = "Security group for Aurora MySQL cluster"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${var.env_name}-aurora-sg"
  })
}

resource "aws_security_group_rule" "aurora_ingress" {
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.proxy.id
  security_group_id        = aws_security_group.aurora.id
  description              = "MySQL from RDS Proxy SG"
}

resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name        = "${var.env_name}-aurora-credentials-${random_password.master.id}"
  description = "Master credentials for Aurora MySQL cluster"
  tags        = local.common_tags
}

resource "aws_iam_role" "rds_proxy" {
  name = "${var.env_name}-rds-proxy-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "rds_proxy" {
  name = "${var.env_name}-rds-proxy-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.aurora_credentials.arn
      },
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBClusters"
        ]
        Resource = aws_rds_cluster.aurora.arn
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_proxy" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy.arn
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = "aurora-mysql"
  engine_version          = var.engine_version
  database_name           = "mydb"
  master_username         = var.db_master_username
  master_password         = random_password.master.result
  backup_retention_period = 7
  preferred_backup_window = "03:00-04:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.aurora.id]
  storage_encrypted       = true
  skip_final_snapshot     = local.skip_final_snapshot
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "aurora" {
  count              = length(aws_subnet.private)
  identifier         = "${var.db_cluster_identifier}-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.aurora.id
  instance_class     = var.aurora_instance_class
  engine             = aws_rds_cluster.aurora.engine
  engine_version     = aws_rds_cluster.aurora.engine_version
  publicly_accessible = false
  db_subnet_group_name = aws_db_subnet_group.aurora.name
  tags                = local.common_tags
}

resource "aws_secretsmanager_secret_version" "aurora_credentials" {
  secret_id = aws_secretsmanager_secret.aurora_credentials.id
  secret_string = jsonencode({
    username          = var.db_master_username
    password          = random_password.master.result
    engine            = aws_rds_cluster.aurora.engine
    host              = aws_rds_cluster.aurora.endpoint
    port              = 3306
    dbClusterIdentifier = aws_rds_cluster.aurora.cluster_identifier
  })
}

resource "aws_db_proxy" "main" {
  name                   = "${var.env_name}-rds-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_subnet_ids         = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]
  debug_logging          = false
  idle_client_timeout    = 1800
  require_tls            = false

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora credentials"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
  }

  tags = local.common_tags

  depends_on = [
    aws_secretsmanager_secret_version.aurora_credentials
  ]
}

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
    init_query                   = ""
  }
}

resource "aws_db_proxy_target" "aurora" {
  db_cluster_identifier = aws_rds_cluster.aurora.cluster_identifier
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
}

resource "random_password" "master" {
  keepers = {
    environment = var.environment
  }
  length  = 30
  special = true
}

resource "aws_secretsmanager_secret" "main" {
  name = "${var.environment}-aurora-mysql-password"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "main" {
  secret_id     = aws_secretsmanager_secret.main.id
  secret_string = jsonencode({ password = random_password.master.result })
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
  name_prefix = "${var.environment}-"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count                   = length(local.azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}public-subnet-${count.index}"
    Environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.name_prefix}private-subnet-${count.index}"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
    Environment = var.environment
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}eip"
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}nat-gateway"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "proxy_sg" {
  name        = "${local.name_prefix}proxy-sg"
  description = "Security group for RDS Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}proxy-sg"
    Environment = var.environment
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${local.name_prefix}rds-sg"
  description = "Security group for Aurora RDS cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.proxy_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}rds-sg"
    Environment = var.environment
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.name_prefix}db-subnet-group"
    Environment = var.environment
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "${local.name_prefix}aurora-cluster"
  engine                  = "aurora-mysql"
  master_username         = "admin"
  master_password         = random_password.master.result
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  skip_final_snapshot     = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "cluster_instances" {
  count              = length(local.azs)
  identifier         = "${local.name_prefix}aurora-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = "db.r5.large"
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version
  db_subnet_group_name = aws_db_subnet_group.main.name
  availability_zone  = local.azs[count.index]
}

resource "aws_iam_role" "proxy_role" {
  name = "${local.name_prefix}rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "proxy_policy" {
  name   = "${local.name_prefix}rds-proxy-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "secretsmanager:GetSecretValue"
        Effect = "Allow"
        Resource = aws_secretsmanager_secret.main.arn
      },
      {
        Action = "rds-db:connect"
        Effect = "Allow"
        Resource = aws_rds_cluster.main.arn
        Condition = {
          StringEquals = {
            "rds:db-user" = "admin"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "proxy_policy_attach" {
  role       = aws_iam_role.proxy_role.name
  policy_arn = aws_iam_policy.proxy_policy.arn
}

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}aurora-proxy"
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  debug_logging          = false
  role_arn               = aws_iam_role.proxy_role.arn
  vpc_subnet_ids         = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.main.arn
  }
}

resource "aws_db_proxy_target" "main" {
  db_cluster_identifier = aws_rds_cluster.main.id
  target_group_name     = "default"
  db_proxy_name         = aws_db_proxy.main.name
}

variable "environment" {
  description = "Environment name used for resource naming"
  type        = string
  default     = "dev"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.94.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for all resources"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_class" {
  description = "Instance class for the RDS cluster instance"
  type        = string
  default     = "db.r5.large"
}

variable "db_username" {
  description = "Master username for the RDS cluster"
  type        = string
  default     = "admin"
}

variable "engine_version" {
  description = "Aurora MySQL engine version"
  type        = string
  default     = "8.0.mysql_aurora.3.08.0"
}

variable "allowed_proxy_cidr" {
  description = "CIDR block allowed to connect to the RDS Proxy"
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  project   = "AuroraMySQLProxy"
  managedby = "Terraform"
  tags = {
    Environment = var.environment
    Project     = local.project
    ManagedBy   = local.managedby
  }
  # Generate two private subnet CIDRs within the VPC
  private_subnet_cidrs = cidrsubnets(var.vpc_cidr, 8, 8)
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${var.environment}-vpc" })
}

# Private subnets (at least two)
resource "aws_subnet" "private" {
  count             = length(data.aws_availability_zones.available.names)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, { Name = "${var.environment}-private-subnet-${count.index}" })
}

# Security group for RDS cluster
resource "aws_security_group" "rds" {
  name_prefix = "${var.environment}-rds-sg-"
  vpc_id      = aws_vpc.main.id
  description = "Allow MySQL from proxy security group"

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.proxy.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${var.environment}-rds-sg" })
}

# Security group for RDS Proxy
resource "aws_security_group" "proxy" {
  name_prefix = "${var.environment}-proxy-sg-"
  vpc_id      = aws_vpc.main.id
  description = "Allow MySQL from specified CIDR"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.allowed_proxy_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${var.environment}-proxy-sg" })
}

# Random password for master user
resource "random_password" "master" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Secrets Manager secret for RDS credentials
resource "aws_secretsmanager_secret" "rds_credentials" {
  name_prefix = "${var.environment}-rds-master-"
  description = "Master credentials for Aurora MySQL cluster"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, { Name = "${var.environment}-rds-credentials" })
}

resource "aws_secretsmanager_secret_version" "rds_credentials" {
  secret_id = aws_secretsmanager_secret.rds_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.master.result
  })
}

# IAM role for RDS Proxy
resource "aws_iam_role" "proxy" {
  name_prefix = "${var.environment}-rds-proxy-role-"
  description = "IAM role for RDS Proxy"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.tags, { Name = "${var.environment}-rds-proxy-role" })
}

# IAM policy for RDS Proxy to access Secrets Manager
resource "aws_iam_policy" "proxy_secrets" {
  name_prefix = "${var.environment}-rds-proxy-secrets-policy-"
  description = "Allow RDS Proxy to read the secret"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "secretsmanager:GetSecretValue"
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.rds_credentials.arn
      }
    ]
  })

  tags = merge(local.tags, { Name = "${var.environment}-proxy-secrets-policy" })
}

resource "aws_iam_role_policy_attachment" "proxy_secrets" {
  role       = aws_iam_role.proxy.name
  policy_arn = aws_iam_policy.proxy_secrets.arn
}

# RDS Aurora MySQL cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier_prefix = "${var.environment}-aurora-cluster-"
  engine                    = "aurora-mysql"
  engine_version            = var.engine_version
  master_username           = var.db_username
  master_password           = random_password.master.result
  vpc_security_group_ids    = [aws_security_group.rds.id]
  db_subnet_group_name      = aws_db_subnet_group.aurora.name
  backup_retention_period   = 1
  storage_encrypted         = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.environment}-aurora-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, { Name = "${var.environment}-aurora-cluster" })
}

# DB subnet group for the cluster
resource "aws_db_subnet_group" "aurora" {
  name_prefix = "${var.environment}-aurora-subnet-group-"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${var.environment}-aurora-subnet-group" })
}

# Writer instance
resource "aws_rds_cluster_instance" "writer" {
  cluster_identifier = aws_rds_cluster.aurora.id
  identifier_prefix  = "${var.environment}-aurora-writer-"
  instance_class     = var.instance_class
  engine             = aws_rds_cluster.aurora.engine
  engine_version     = aws_rds_cluster.aurora.engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora.name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, { Name = "${var.environment}-aurora-writer" })
}

# RDS Proxy
resource "aws_db_proxy" "main" {
  name              = "${var.environment}-aurora-proxy"
  engine_family     = "MYSQL"
  role_arn          = aws_iam_role.proxy.arn
  vpc_subnet_ids    = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]

  auth {
    secret_arn = aws_secretsmanager_secret.rds_credentials.arn
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, { Name = "${var.environment}-aurora-proxy" })
}

# Proxy target (default target group for cluster)
resource "aws_db_proxy_target" "main" {
  db_proxy_name          = aws_db_proxy.main.name
  target_group_name      = "default"
  db_cluster_identifier  = aws_rds_cluster.aurora.id
}

# VPC endpoint for Secrets Manager (Interface)
resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoint_secretsmanager.id]
  private_dns_enabled = true

  tags = merge(local.tags, { Name = "${var.environment}-secretsmanager-endpoint" })
}

# Security group for the VPC endpoint (allow HTTPS from VPC CIDR)
resource "aws_security_group" "endpoint_secretsmanager" {
  name_prefix = "${var.environment}-sm-endpoint-sg-"
  vpc_id      = aws_vpc.main.id
  description = "Allow HTTPS from VPC CIDR for Secrets Manager endpoint"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${var.environment}-sm-endpoint-sg" })
}

# Outputs
output "cluster_endpoint" {
  value = aws_rds_cluster.aurora.endpoint
}

output "cluster_reader_endpoint" {
  value = aws_rds_cluster.aurora.reader_endpoint
}

output "proxy_endpoint" {
  value = aws_db_proxy.main.endpoint
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80.0"
    }
  }
}

locals {
  common_tags = {
    Name        = var.instance_name
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  type        = string
  default     = "basic-lightsail-instance"
}

variable "blueprint_id" {
  description = "Blueprint ID for the Lightsail instance (e.g., amazon_linux_2, ubuntu_24_04)"
  type        = string
  default     = "amazon_linux_2"
}

variable "bundle_id" {
  description = "Bundle ID for the Lightsail instance (e.g., micro_1_0, small_1_0)"
  type        = string
  default     = "micro_1_0"
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed for SSH access (use a more restrictive value in production)"
  type        = string
  default     = "0.0.0.0/0"
}

variable "ssh_public_key" {
  description = "Optional public SSH key for key-based authentication. If empty, the default Lightsail key pair is used."
  type        = string
  default     = ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_lightsail_key_pair" "this" {
  count      = var.ssh_public_key != "" ? 1 : 0
  name       = "${var.instance_name}-key"
  public_key = var.ssh_public_key
  tags       = local.common_tags
}

resource "aws_lightsail_instance" "main" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = var.ssh_public_key != "" ? aws_lightsail_key_pair.this[0].name : null
  tags              = local.common_tags
}

resource "aws_lightsail_instance_public_ports" "ssh" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = [var.allowed_ssh_cidr]
  }
}

resource "aws_lightsail_static_ip" "main" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "main" {
  static_ip_name = aws_lightsail_static_ip.main.name
  instance_name  = aws_lightsail_instance.main.name
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_lightsail_instance" "basic" {
  name              = "basic-lightsail"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_2_0"

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl start httpd
    systemctl enable httpd
    echo "Hello from Lightsail" > /var/www/html/index.html
  EOF

  tags = {
    Name = "basic-lightsail"
  }
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance"
  value       = aws_lightsail_instance.basic.public_ip_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
