  default     = "amazon_linux_2"
}

variable "bundle" {
  description = "Lightsail bundle (instance plan)"
  type        = string
  default     = "nano_2_0"
}

variable "common_tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Terraform = "true"
  }
}

locals {
