    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

resource "aws_lightsail_bucket" "main" {
  name      = "lightsail-bucket-${random_pet.suffix.id}"
  bundle_id = "small_1_0"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_instance" "main" {
  name              = "lightsail-instance-${random_pet.suffix.id}"
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "small_1_0"
  availability_zone = data.aws_availability_zones.available.names[0]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_bucket_resource_access" "main" {
  bucket_name   = aws_lightsail_bucket.main.name
  resource_name = aws_lightsail_instance.main.name
}

variable "domain_name" {
  description = "Domain name for the Lightsail certificate and Route53 zone"
  type        = string
  default     = "example.com"
}

variable "subject_alternative_names" {
  description = "Subject alternative names for the Lightsail certificate"
  type        = list(string)
  default     = []
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_lightsail_certificate" "main" {
  name                      = "lightsail-cert-${replace(var.domain_name, ".", "-")}"
  domain_name               = var.domain_name
  subject_alternative_names = var.subject_alternative_names
}

resource "aws_route53_record" "validation" {
  for_each = {
    for dvo in aws_lightsail_certificate.main.domain_validation_options : dvo.domain_name => dvo
  }

  zone_id = aws_route53_zone.main.zone_id
  name    = each.value.resource_record_name
  type    = each.value.resource_record_type
  records = [each.value.resource_record_value]
  ttl     = 300
}

output "certificate_arn" {
  description = "The ARN of the Lightsail certificate"
  value       = aws_lightsail_certificate.main.arn
}

output "validation_record_fqdns" {
  description = "List of validation record FQDNs for DNS validation"
  value = [
    for dvo in aws_lightsail_certificate.main.domain_validation_options : dvo.resource_record_name
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
  }
}

variable "glacier_vault_name" {
  description = "Name of the Glacier vault"
  type        = string
  default     = "archive-vault"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  vault_arn = "arn:aws:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${var.glacier_vault_name}"
}

# Vault access policy – restrict all actions to the dedicated IAM role
data "aws_iam_policy_document" "vault_access" {
  statement {
    sid    = "AllowRoleOnly"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.glacier_worker.arn]
    }
    actions   = ["glacier:*"]
    resources = [local.vault_arn]
  }
}

# Vault lock policy – enforce 365-day retention (WORM)
data "aws_iam_policy_document" "vault_lock" {
  statement {
    sid    = "DenyDeleteUnder365Days"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = ["glacier:DeleteArchive"]
    resources = ["${local.vault_arn}/*"]
    condition {
      test     = "NumericLessThan"
      variable = "glacier:ArchiveAgeInDays"
      values   = ["365"]
    }
  }
  statement {
    sid    = "DenyOverwriteUnder365Days"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = ["glacier:OverwriteArchive"]
    resources = ["${local.vault_arn}/*"]
    condition {
      test     = "NumericLessThan"
      variable = "glacier:ArchiveAgeInDays"
      values   = ["365"]
    }
  }
}

resource "aws_glacier_vault" "main" {
  name          = var.glacier_vault_name
  access_policy = data.aws_iam_policy_document.vault_access.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_glacier_vault_lock" "lock" {
  vault_name     = aws_glacier_vault.main.name
  policy         = data.aws_iam_policy_document.vault_lock.json
  complete_lock  = true
}

# IAM role for EC2 (or other compute) to interact with the vault
resource "aws_iam_role" "glacier_worker" {
  name = "glacier-worker-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Least‑privilege policy for the role
resource "aws_iam_role_policy" "glacier_worker" {
  name = "glacier-worker-policy"
  role = aws_iam_role.glacier_worker.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glacier:UploadArchive",
          "glacier:InitiateJob",
          "glacier:GetVaultAccessPolicy",
          "glacier:DescribeVault"
        ]
        Resource = local.vault_arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  tags = {
    Name        = "long-term-backup"
    Environment = "production"
    Purpose     = "long-term-data-storage-and-backup"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "long_term_backup" {
  bucket = "long-term-backup-${random_id.bucket_suffix.hex}"
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "long_term_backup" {
  bucket = aws_s3_bucket.long_term_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "long_term_backup" {
  bucket = aws_s3_bucket.long_term_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "long_term_backup" {
  bucket = aws_s3_bucket.long_term_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "long_term_backup" {
  bucket = aws_s3_bucket.long_term_backup.id

  rule {
    id     = "long-term-backup-lifecycle"
    status = "Enabled"

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 90
      storage_class = "DEEP_ARCHIVE"
    }

    expiration {
      days = 365
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_transition {
      noncurrent_days = 90
      storage_class   = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "vault_name" {
  description = "Name of the S3 Glacier vault"
  type        = string
  default     = "glacier-vault"
}

resource "aws_sns_topic" "notifications" {
  name = "${var.vault_name}-notifications"
}

resource "aws_sns_topic_policy" "notifications" {
  arn = aws_sns_topic.notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_glacier_vault" "main" {
  name = var.vault_name

  notification {
    sns_topic = aws_sns_topic.notifications.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  lifecycle {
    prevent_destroy = true
  }
}
